window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p56f583c407"]={"id":"p56f583c407","name":"2025-10-25 全国事业单位联考职业能力倾向测验 C类","year":2025,"region":"全国联考","examDate":"2025-10-25","examType":"institution","examClass":"C","count":100,"types":{"常识时政":5,"地理国情":2,"法律常识":1,"常识判断":1,"科技常识":11,"片段阅读":12,"逻辑填空":13,"数学运算":5,"资料分析":11,"图形推理":5,"定义判断":4,"逻辑判断":11,"类比推理":10,"综合分析":4,"实验设计":5},"modules":["常识判断","言语理解与表达","数量关系","资料分析","判断推理","综合分析"],"moduleCounts":{"常识判断":20,"言语理解与表达":25,"数量关系":5,"资料分析":11,"判断推理":30,"综合分析":9},"coverage":{"basis":"所给事业编原件","sourceCount":100,"expectedCount":null,"missingAnswers":0,"missingCount":null},"questions":[{"qid":"sy-c-20251025-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-001-题目-p02-106-181.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"水下兵器方队——潜匿大洋，出奇制胜"},{"k":"B","t":"电子对抗方队——自主巡弋，出击深蓝"},{"k":"C","t":"装备保障方队——抢救抢修，分秒必争"},{"k":"D","t":"对空抗击方队——剑指苍穹，御敌长空"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-001-解析-p01-120-469.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"纪念中国人民抗日战争暨世界反法西斯战争胜利80周年阅兵活动备受瞩目，本次阅兵中，下列受阅方队与解说词对应错误的是（    ）。","options":[{"k":"A","t":"水下兵器方队——潜匿大洋，出奇制胜"},{"k":"B","t":"电子对抗方队——自主巡弋，出击深蓝"},{"k":"C","t":"装备保障方队——抢救抢修，分秒必争"},{"k":"D","t":"对空抗击方队——剑指苍穹，御敌长空"}],"material":"","explanation":"1\n\n本题考查时事政治。\n\nA 项正确，水下兵器方队主要装备鱼雷等水下作战武器，其核心特点是依托海洋隐蔽部署、伺机突袭。阅兵当天解说词这样描述：“潜匿大洋，出奇制胜，水下兵器方队亮相阅兵场。”\n\nB 项错误，电子对抗方队的核心职能是通过电磁干扰、电子防御等手段争夺制电磁权，属于“无形战场”的作战力量。阅兵当天解说词这样描述：“电磁利剑，先手制敌，电子对抗方队开过来了。”“自主巡弋，出击深蓝。”对应的是海上无人作战方队。海上无人作战方队包括新型无人潜航器、无人艇、无人布雷系统，具备隐蔽布放封锁、自主探测识别、集群组网攻击等作战能力，是海上作战的奇兵利器。\n\nC 项正确，装备保障方队的主要任务是战场装备抢救、抢修和运输，确保作战装备持续发挥效能。阅兵当天解说词这样描述：“抢救抢修，分秒必争，接下来通过的是装备保障方队。”\n\nD 项正确，对空抗击方队以防空武器系统为主要装备，负责抵御空中来袭目标。阅兵当天解说词这样描述：“剑指苍穹，御敌长空，对空抗击方队接受检阅。”\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"p56f583c407"},{"qid":"sy-c-20251025-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-002-题目-p02-176-299.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-002-解析-p01-464-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-002-解析-p02-51-247.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记指出，推进中国式现代化必须推动海洋经济高质量发展，走出一条具有中国特色的向海图强之路。关于海洋强国建设，下列说法正确的是（   ）。\n\n①建设海洋强国是实现中华民族伟大复兴的重大战略任务\n\n②要加强海湾经济发展规划研究，有序推进沿海港口群优化整合\n\n③要保护海洋生态环境，着力推动海洋开发方式向经济利益主导型转变\n\n④建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"2\n\n本题考查时事政治。\n\n①项正确，2022 年4 月10 日，习近平总书记在中国海洋大学三亚海洋研究院调研考察时，对建设海洋强国作出重要指示：“建设海洋强国是实现中华民族伟大复兴的重大战略任务。”\n\n②项正确，2025 年7 月1 日，习近平主持召开中央财经委员会第六次会议强调：“推动海洋经济高质量发展，要加强顶层设计，加大政策支持力度······要加强海湾经济发展规划研究，有序推进沿海港口群优化整合。”\n\n③项错误，习近平总书记在主持中共中央政治局就建设海洋强国研究进行集体学习时（2013年7 月30 日）强调了建设海洋强国的四个基本要求，即“四个转变”。具体内容为：要提高海洋资源开发能力，着力推动海洋经济向质量效益型转变；要保护海洋生态环境，着力推动海洋开发方式向循环利用型转变；要发展海洋科学技术，着力推动海洋科技向创新引领型转变；要维护国家海洋权益，着力推动海洋维权向统筹兼顾型转变。因此，选项中“开发方式向经济利益主导型转变”说法错误。应为“推动海洋开发方式向循环利用型转变”。\n\n④项正确，习近平主席强调：“建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑，是实现中华民族伟大复兴中国梦的重要组成部分。”综上，①②④正确。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1,2]},"idx":1,"pid":"p56f583c407"},{"qid":"sy-c-20251025-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-003-题目-p02-295-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"大力发展超高层建筑，完善抗震设计标准"},{"k":"B","t":"严格落实安全生产责任制，坚持党政同责"},{"k":"C","t":"多部门、跨城市协同，强化公共卫生联防联控"},{"k":"D","t":"构建总量充足、布局合理的应急避难场所体系"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-003-解析-p02-243-663.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"城市是现代化建设的重要载体、人民幸福生活的重要空间。2025年8月，《中共中央国务院关于推动城市高质量发展的意见》公布，其中明确提出要增强城市安全韧性，下列做法与这一任务要求不符的是（    ）。","options":[{"k":"A","t":"大力发展超高层建筑，完善抗震设计标准"},{"k":"B","t":"严格落实安全生产责任制，坚持党政同责"},{"k":"C","t":"多部门、跨城市协同，强化公共卫生联防联控"},{"k":"D","t":"构建总量充足、布局合理的应急避难场所体系"}],"material":"","explanation":"3\n\n本题考查时事政治。\n\n2025 年8 月15 日，《中共中央国务院关于推动城市高质量发展的意见》公布，其中明确提出要增强城市安全韧性。具体包括以下四项措施：加强房屋和市政基础设施安全管理；强化重点行业领域安全生产管理；提高城市公共卫生防控救治水平；增强城市综合防灾减灾救灾能力。\n\nA 项错误，超高层建筑存在固有安全风险，与城市安全韧性要求存在冲突。文件原文强调，“加强房屋和市政基础设施安全管理。······严格限制超高层建筑，增强高空消防能力。”\n\nB 项正确，文件强调，“强化重点行业领域安全生产管理。严格落实安全生产责任制，坚持党政同责，坚持管行业必须管安全、管业务必须管安全、管生产经营必须管安全，督促生产经营单位落实安全生产主体责任。”\n\nC 项正确，文件强调，“提高城市公共卫生防控救治水平。······推进多部门、跨城市协同，强化公共卫生应急管理和联防联控。健全精神卫生服务体系。”\n\nD 项正确，文件强调，“增强城市综合防灾减灾救灾能力。······统筹利用地上地下空间，加强“平急两用”公共基础设施建设，构建总量充足、布局合理的应急避难场所体系。科学制定巨灾应急预案。”\n\n本题为选非题，故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2]},"idx":2,"pid":"p56f583c407"},{"qid":"sy-c-20251025-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-004-题目-p02-365-424.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"0～6岁儿童"},{"k":"B","t":"高血压患者"},{"k":"C","t":"65岁以上老年人"},{"k":"D","t":"急性脑卒中患者"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-004-解析-p02-658-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-004-解析-p03-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025年8月，国务院常务会议审议通过《医疗卫生强基工程实施方案》方案指出，强化重点人群系统连续服务。下列不属于上述重点人群的是（    ）。","options":[{"k":"A","t":"0～6岁儿童"},{"k":"B","t":"高血压患者"},{"k":"C","t":"65岁以上老年人"},{"k":"D","t":"急性脑卒中患者"}],"material":"","explanation":"4\n\n本题考查时事政治。\n\n2025 年8 月，国务院常务会议审议通过《医疗卫生强基工程实施方案》方案指出，强化孕产妇、0—6 岁儿童、65 岁以上老年人以及高血压、2 型糖尿病、慢阻肺病患者等重点人群系统连续服务，加强基层多病共防、多病共管和医防融合，到2030 年高血压、2 型糖尿病患者基层规范管理服务率达到70%以上。\n\n因此“急性脑卒中患者”不属于重点人群。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2,3]},"idx":3,"pid":"p56f583c407"},{"qid":"sy-c-20251025-005","no":5,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-005-题目-p02-419-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-005-解析-p03-195-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-005-解析-p04-51-88.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"工业和信息化部等五部门组织修订的强制性国家标准《电动自行车安全技术规范》（GB17761-2024），于2025年9月1日实施。下列说法符合该技术规范的是（   ）。\n\n①为保障行车安全，电动自行车必须安装后视镜\n\n②可使用电助力功能的电动自行车应具有脚踏骑行装置\n\n③具有电驱动功能的电动自行车最高设计车速不得超过40km/h\n\n④用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"material":"","explanation":"5\n\n本题考查时事政治。\n\n①项错误，根据《电动自行车安全技术规范》6.1.5.1 尺寸限值要求：电动自行车的尺寸限值应符合下列要求。a）整车高度（除后视镜及后视镜连接杆外）小于或等于1100mm；车体宽度（除车把、脚蹬、后视镜及后视镜连接杆外）小于或等于400mm；前后轮中心距小于或等于1250mm；鞍座高度大于或等于635mm。仅具有电助力功能的电动自行车的整车高度、前后轮中心距限值要求不适用。注：为保证行车安全，鼓励电动自行车安装后视镜。\n\n原文是鼓励安装后视镜，但没有规定必须安装。\n\n②项正确，根据《电动自行车安全技术规范》6.1.4.1 脚踏骑行要求：可使用电助力功能的电动自行车应具有脚踏骑行装置，并符合下列要求：a）应具有脚踏动力装置；b）脚踏骑行一周，车辆向前行驶距离应大于或等于2.7m；c）两曲柄外侧面最大距离应小于或等于300mm；d）鞍座前端在水平方向位置不应超过中轴中心线。仅具有电驱动功能的电动自行车，可设置脚踏骑行装置，也可不设置脚踏骑行装置。如设置，则应满足上述a）~d）的要求。\n\n③项错误，根据《电动自行车安全技术规范》6.1.1.1 车速限值要求，a 使用电驱动功能行驶时，最高车速不应超过最高设计车速，且最高设计车速不应超过25km/h；如果车速超过25km/h，电动机不应提供动力输出。注：连续下坡行驶等情况下，车速可能会超过25km/h。\n\n④项正确，根据《电动自行车安全技术规范》6.6.1 北斗模块的安装：用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块，且应安装于电动自行车不易损坏的固定部件中，并具备防拆卸、防篡改功能。采用通用工具、剪线、跳线等方式验证防拆卸、防篡改功能。对于其他类型的电动自行车，应设计有北斗模块，销售时由消费者选择是否保留。\n\n综上所述，正确的是②和④。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[3]},"idx":4,"pid":"p56f583c407"},{"qid":"sy-c-20251025-006","no":6,"type":"地理国情","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"地理国情","tag":"地理国情","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[4]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-006-题目-p02-538-629.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"河南——2024年小麦总产量首次跃居全国第一"},{"k":"B","t":"新疆——以占全国6%的耕地生产了全国10%的粮食"},{"k":"C","t":"浙江——目前全国“农林牧渔业总产值”最高的省域"},{"k":"D","t":"黑龙江——农业资源富集，主要农作物一年一熟"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-006-解析-p04-83-523.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于我国农业，下列省（区）与描述内容对应正确的是（    ）。","options":[{"k":"A","t":"河南——2024年小麦总产量首次跃居全国第一"},{"k":"B","t":"新疆——以占全国6%的耕地生产了全国10%的粮食"},{"k":"C","t":"浙江——目前全国“农林牧渔业总产值”最高的省域"},{"k":"D","t":"黑龙江——农业资源富集，主要农作物一年一熟"}],"material":"","explanation":"6\n\n本题考查地理国情。\n\nA 项错误，2024 年河南省粮食总产量1344 亿斤，居全国第二位，小麦单产、总产均稳居全国第一。但河南省小麦总产量常年居全国首位，“2024 年首次跃居全国第一”说法错误。\n\nB 项错误，河南省是全国重要的粮食生产核心区，用占全国6%的耕地，产出了全国10%的的小麦，粮食产量连续多年稳定在1300 亿斤以上。因此“新疆以占全国6%的耕粮食、地生产了全国10%的粮食”说法错误。\n\nC 项错误，山东省是全国“第一产业增加值、农林牧渔业增加值”最大的省域，也是全国“农林牧渔业总产值”最高的省域。因此“浙江省是目前全国‘农林牧渔业总产值’最高的省域”说法错误。\n\nD 项正确，黑龙江省农业资源富集，全省现有耕地2.579 亿亩，占全国，位居全国之首。\n\n之间，无霜期100～黑龙江省属中、寒温带大陆性季风气候，常年有效积温150 天，年降水量370～670 毫米，光、热、水同季，适于农作物生长，农作物熟制是一年一熟。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"地理国情","questionPages":[2],"answerPages":[4]},"idx":5,"pid":"p56f583c407"},{"qid":"sy-c-20251025-007","no":7,"type":"法律常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"法律常识","tag":"法律常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[4,5]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-007-题目-p02-624-731.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"若在小区安装人脸识别设备，应当在人脸信息采集区域设置显著的提示标识"},{"k":"B","t":"若小区需通过人脸识别提升安全等级，其数据不能自行通过互联网对外传输"},{"k":"C","t":"个人撤回同意小区处理其人脸信息的，撤回前已进行的个人信息处理活动无效"},{"k":"D","t":"若存在刷卡、密码等其他验证方式，小区不得将人脸识别作为唯一的验证方式"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-007-解析-p04-519-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-007-解析-p05-51-319.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025年3月，国家网信办与公安部联合发布《人脸识别技术应用安全管理办法》，对人脸识别技术使用做出了规范。以小区为例，下列说法不符合该办法的是（    ）。","options":[{"k":"A","t":"若在小区安装人脸识别设备，应当在人脸信息采集区域设置显著的提示标识"},{"k":"B","t":"若小区需通过人脸识别提升安全等级，其数据不能自行通过互联网对外传输"},{"k":"C","t":"个人撤回同意小区处理其人脸信息的，撤回前已进行的个人信息处理活动无效"},{"k":"D","t":"若存在刷卡、密码等其他验证方式，小区不得将人脸识别作为唯一的验证方式"}],"material":"","explanation":"7\n\n本题考查法律常识。\n\nA 项正确，根据《人脸识别技术应用安全管理办法》第十三条第一款规定：“在公共场所安装人脸识别设备，应当为维护公共安全所必需，依法合理确定人脸信息采集区域，并设置显著提示标识。”由此可知，在小区安装人脸识别设备，应当在人脸信息采集区域设置显著的提示标识。\n\nB 项正确，根据《人脸识别技术应用安全管理办法》第八条第一款规定：“除法律、行政法规另有规定或者取得个人单独同意外，人脸信息应当存储于人脸识别设备内，不得通过互联网对外传输。”由此可知，若小区需通过人脸识别提升安全等级，其数据不能自行通过互联网对外传输。\n\nC 项错误，根据《人脸识别技术应用安全管理办法》第六条第二款规定：“基于个人同意处理人脸信息的，个人有权撤回同意，个人信息处理者应当提供便捷的撤回同意的方式。个人撤回同意，不影响撤回前基于个人同意已进行的个人信息处理活动的效力。”由此可知，个人撤回同意，不影响撤回前基于个人同意已进行的个人信息处理活动的效力。\n\nD 项正确，根据《人脸识别技术应用安全管理办法》第十条第一款规定：“实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式。个人不同意通过人脸信息进行身份验证的，应当提供其他合理、便捷的方式。”由此可知，若存在刷卡、密码等其他验证方式，小区不得将人脸识别作为唯一的验证方式。\n\n本题为选非题，故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"法律常识","questionPages":[2],"answerPages":[4,5]},"idx":6,"pid":"p56f583c407"},{"qid":"sy-c-20251025-008","no":8,"type":"常识判断","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"常识判断","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"下列公文版头的编排不符合规范的是（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[2],"answer":[5]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-008-题目-p02-727-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-008-题目-p03-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"保密期限标注为“秘密★十年”"},{"k":"B","t":"份号顶格编排在版心左上角第一行"},{"k":"C","t":"紧急公文根据紧急程度标注“特急”"},{"k":"D","t":"发文机关标志使用发文机关规范化简称"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-008-解析-p05-315-678.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列公文版头的编排不符合规范的是（    ）。","options":[{"k":"A","t":"保密期限标注为“秘密★十年”"},{"k":"B","t":"份号顶格编排在版心左上角第一行"},{"k":"C","t":"紧急公文根据紧急程度标注“特急”"},{"k":"D","t":"发文机关标志使用发文机关规范化简称"}],"material":"","explanation":"8\n\n本题考查公文的概念和特点。\n\nA 项错误，根据《党政机关公文格式》7.2.2 规定：“如需标注密级和保密期限，一般用3 号黑体字，顶格编排在版心左上角第二行；保密期限中的数字用阿拉伯数字标注。”因此，保密期限应该标注为“秘密★10 年”。\n\nB 项正确，根据《党政机关公文格式》7.2.1 规定：“份号。版头如需标注份号，一般用6 位3 号阿拉伯数字，顶格编排在版心左上角第一行。”\n\nC 项正确，根据《党政机关公文处理工作条例》第九条第（三）项规定：根据紧急程度，紧急公文应当分别标注“特急”“加急”，电报应当分别标注“特提”“特急”“加急”“平急”。因此，紧急公文可以根据紧急程度标注“特急”。\n\nD 项正确，根据《党政机关公文处理工作条例》第九条第（四）项规定：“发文机关标志。\n\n由发文机关全称或者规范化简称加‘文件’二字组成，也可以使用发文机关全称或者规范化简称。联合行文时，发文机关标志可以并用联合发文机关名称，也可以单独用主办机关名称。”\n\n本题为选非题，故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"常识判断","questionPages":[2],"answerPages":[5]},"idx":7,"pid":"p56f583c407"},{"qid":"sy-c-20251025-009","no":9,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[5,6]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-009-题目-p03-87-194.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"高纤维食物可促进肠道蠕动，减少胆固醇吸收，有助于血压稳定"},{"k":"B","t":"体重增加可能引发血糖和血脂双升高，进而对血压产生不良影响"},{"k":"C","t":"盐分摄入过多会导致体内水分滞留，增加心脏负担，进而导致血压升高"},{"k":"D","t":"浓茶、咖啡类饮品可抑制交感神经兴奋，促使血管收缩，进而降低血压"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-009-解析-p05-674-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-009-解析-p06-51-343.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"血压波动会对身体造成不同程度的伤害，包括损害心、脑、肾等器官，增加心血管发病风险率，下列与血压波动相关的说法错误的是（    ）。","options":[{"k":"A","t":"高纤维食物可促进肠道蠕动，减少胆固醇吸收，有助于血压稳定"},{"k":"B","t":"体重增加可能引发血糖和血脂双升高，进而对血压产生不良影响"},{"k":"C","t":"盐分摄入过多会导致体内水分滞留，增加心脏负担，进而导致血压升高"},{"k":"D","t":"浓茶、咖啡类饮品可抑制交感神经兴奋，促使血管收缩，进而降低血压"}],"material":"","explanation":"9\n\n本题考查科技常识。\n\nA 项正确，高纤维食物能促进肠道蠕动，减少肠道对胆固醇的吸收，降低血脂水平；而血脂异常是血压波动的重要诱因。因此，高纤维饮食可通过改善血脂间接帮助稳定血压。\n\nB 项正确，体重增加会增加胰岛素抵抗的风险，胰岛素抵抗会引起血糖升高，同时脂肪堆积会引起血脂异常。血糖、血脂异常会损伤血管内皮细胞，从而降低血管弹性，最终导致血压升高或波动。\n\nC 项正确，盐分的主要成分为氯化钠，当盐分摄入过多时，体内钠离子浓度升高会引发渗透压变化，造成体内水分滞留，血容量增多；血容量增加会增加心脏泵血负担，迫使血管承受更高压力，最终导致血压升高。\n\nD 项错误，浓茶和咖啡类饮品中均含有咖啡因，咖啡因为中枢神经兴奋剂，会激活交感神经，从而导致心率加快、血管收缩；血管收缩会使外周血管阻力增加，进而引起血压升高。因此，选项中的“抑制交感神经兴奋”“降低血压”错误。应该是“激活交感神经”“升高血压”。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[5,6]},"idx":8,"pid":"p56f583c407"},{"qid":"sy-c-20251025-010","no":10,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[6,7]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-010-题目-p03-189-248.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"使用加湿器——提高空气导电性导出电荷"},{"k":"B","t":"携带金属物——通过人体电阻将电流释放"},{"k":"C","t":"涂抹护手霜——油脂绝缘增加电荷积累"},{"k":"D","t":"穿纯棉衣服——吸湿性强能减少离子交换"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-010-解析-p06-339-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-010-解析-p07-51-223.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"冬季北方常见静电困扰，下列与科学原理匹配正确的是（    ）。","options":[{"k":"A","t":"使用加湿器——提高空气导电性导出电荷"},{"k":"B","t":"携带金属物——通过人体电阻将电流释放"},{"k":"C","t":"涂抹护手霜——油脂绝缘增加电荷积累"},{"k":"D","t":"穿纯棉衣服——吸湿性强能减少离子交换"}],"material":"","explanation":"10\n\n本题考查科技常识。\n\nA 项正确，冬季北方空气干燥，物体表面因缺乏水分，难以形成导电层，摩擦产生的静电荷（如衣物摩擦、人体活动）无法及时释放，导致电荷积累。使用加湿器增加空气湿度后，空气中的水分子会吸附在物体表面，形成一层极薄的“水膜”。水膜中含有微量杂质离子（如钙、镁离子），成为微弱的导体，既能降低物体表面电阻，又能通过空气中的离子传导，使静电荷缓慢释放到空气中，从而减少静电积累。因此，“使用加湿器，提高空气导电性导出电荷”的原理符合静电消散的科学机制。\n\nB 项错误，携带金属物（如钥匙、硬币）接触导体（如门把手、电梯按钮）时，金属作为良导体，会优先将人体积累的静电荷通过自身尖端集中释放（尖端放电效应）。由于金属电阻远小于人体组织，电流几乎全部经金属路径导走，避免了手指直接接触时瞬间高电流对皮肤的刺激。其核心原理是“利用金属导电性安全放电”，而非“通过人体电阻释放电流”——若依赖人体电阻放电，反而会因电流通过人体造成刺痛。因此该选项对原理的表述完全颠倒。\n\nC 项错误，涂抹护手霜的主要作用是保湿，其中含有的水分和亲水成分能够提高皮肤表面的导电性，有助于静电荷的缓慢释放，从而减少静电积累。虽然部分护手霜含有油脂成分具有一定绝缘性，但整体效果是降低皮肤干燥程度，抑制静电产生。因此，“油脂绝缘增加电荷积累”的说法与实际作用相反。\n\nD 项错误，穿纯棉衣服减少静电，是因为棉纤维吸湿性较强，能从空气中吸收少量水分，使织物表面形成微弱导电层，降低摩擦产生的电荷积累。但静电的本质是“不同材料摩擦时电子转移”（如化纤衣物与皮肤摩擦，电子从一方转移到另一方），而非“离子交换”。纯棉衣物通过提高导电性促进电荷中和，而非“减少离子交换”，该选项与静电产生的原理不匹配。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[6,7]},"idx":9,"pid":"p56f583c407"},{"qid":"sy-c-20251025-011","no":11,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[7]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-011-题目-p03-244-334.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"用较小的力捏住闸把即可以完成制动，这是利用了杠杆原理"},{"k":"B","t":"传统尾灯利用光线反射原理，提醒后方车辆注意前方骑行者"},{"k":"C","t":"踩脚蹬时，人的机械能通过链条传动系统转化为前进的动能"},{"k":"D","t":"车轮半径越小，与地面接触面积越小，其滚动阻力也就越小"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-011-解析-p07-219-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-011-解析-p08-51-103.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列与自行车相关的说法，错误的是（    ）。","options":[{"k":"A","t":"用较小的力捏住闸把即可以完成制动，这是利用了杠杆原理"},{"k":"B","t":"传统尾灯利用光线反射原理，提醒后方车辆注意前方骑行者"},{"k":"C","t":"踩脚蹬时，人的机械能通过链条传动系统转化为前进的动能"},{"k":"D","t":"车轮半径越小，与地面接触面积越小，其滚动阻力也就越小"}],"material":"","explanation":"11\n\n本题考查科技常识。\n\nA 项正确，自行车的闸把是典型的省力杠杆。闸把的支点靠近刹车线连接点，人手捏闸的位置为动力臂，刹车块作用于车轮的位置为阻力臂。动力臂远大于阻力臂，因此用较小的力就能产生较大的刹车力。\n\nB 项正确，尾灯内部凹凸不平的表面叫“角反射器”，其中每个结构单元是由三个相互垂直的镜面组成的。其特殊在于，无论光线以何种角度射入，经过多次反射后，最终都会平行于入射光线射出。后方车辆的灯光照射到尾灯时，光线会通过角反射器反射，沿原方向返回，让后方驾驶员清晰看到骑行者，从而起到警示作用，核心是利用了光的反射原理。\n\nC 项正确，人踩脚蹬时，身体会消耗储存的化学能，转化为腿部肌肉运动的机械能（包含肌肉收缩的动能和势能）。腿部的机械能传递给脚蹬，脚蹬带动曲柄旋转。曲柄与牙盘（大齿轮）固定，牙盘通过链条将动力传递给飞轮（后轮上的小齿轮），完成机械传动。飞轮与后轮同轴，飞轮转动时直接带动后轮旋转。后轮与地面产生静摩擦力，地面给后轮向前的反作用力，推动自行车和骑行者整体前进，此时机械能最终转化为自行车前进的动能。\n\nD 项错误，滚动阻力的核心影响因素是路面硬度、轮胎形变程度、接触面积的压强，与车轮半径无直接关联。当车轮接触地面时，地面会轻微凹陷，轮胎也会发生形变（接触部分被压平）。在滚动过程中，轮胎需要不断“恢复形变”，这个过程会消耗能量；同时，接触面的微小摩擦也会产生阻力，两者共同构成滚动阻力。滚动阻力的4 个关键影响因素包括：轮胎胎压、轮胎材质与结构、路面条件、载重大小。胎压越高（在安全范围内），轮胎形变越小，滚动阻力越小，这也是公路自行车胎压远高于山地车的原因。材质偏硬的轮胎形变小，滚动阻力更小。路面越软、越粗糙，滚动阻力越大。车身总重量（车+人+负载）越大，对地面的压力越大，轮胎和地面的形变越严重，滚动阻力也随之增大。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[7]},"idx":10,"pid":"p56f583c407"},{"qid":"sy-c-20251025-012","no":12,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[8]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-012-题目-p03-330-421.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"取暖电暖器通过红外辐射加热，升温快，适合局部取暖"},{"k":"B","t":"电热毯通过内置电热丝产生热量，能自动调节空气的温度"},{"k":"C","t":"空调制热主要依靠电阻丝加热空气，其效率不取决于室外温度"},{"k":"D","t":"暖风机通过加热空气并强制对流送风，是地暖系统的核心设备"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-012-解析-p08-99-486.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列关于取暖设备的说法，正确的是（    ）。","options":[{"k":"A","t":"取暖电暖器通过红外辐射加热，升温快，适合局部取暖"},{"k":"B","t":"电热毯通过内置电热丝产生热量，能自动调节空气的温度"},{"k":"C","t":"空调制热主要依靠电阻丝加热空气，其效率不取决于室外温度"},{"k":"D","t":"暖风机通过加热空气并强制对流送风，是地暖系统的核心设备"}],"material":"","explanation":"12\n\n本题考查科技常识。\n\nA 项正确，石英管电暖器的核心原理是利用石英管通电后发射远红外线，直接辐射加热周围物体，具有升温速度快、热量集中的特点，无需大面积加热空气，因此特别适合小空间局部取暖。\n\nB 项错误，电热毯通过内置电热丝（或碳纤维）通电发热，热量通过接触传导至人体和床品，而非“自动调节空气的温度”。\n\nC 项错误，空调制热主要依靠热泵技术（制冷剂循环）：室外机吸收空气中的热量，通过压缩机制热后释放到室内，仅当室外温度过低时，才辅以电阻丝加热。另外，热泵制热效率依赖室外温度——室外温度越低，空气中可转移的热量越少，空调制热效率会显著下降。因此，选项中“空调制热主要依靠电阻丝加热空气，其效率不取决于室外温度”表述错误。\n\nD 项错误，暖风机通过加热元件（如电热丝）加热空气，再用风机强制吹出热风，它是一种独立取暖设备；而地暖系统的核心设备是分集水器、壁挂炉（或电加热模块）、地暖管，通过地暖管内的热水（或电加热）辐射加热地面，进而升温室内空气。二者加热原理并无关联。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[8]},"idx":11,"pid":"p56f583c407"},{"qid":"sy-c-20251025-013","no":13,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[8,9]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-013-题目-p03-416-475.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"真空状态下的气体压力低于一个大气压"},{"k":"B","t":"电磁波和声音的传递不受真空状态影响"},{"k":"C","t":"自然环境中只有外太空最接近真空空间"},{"k":"D","t":"真空灯泡能防止灯丝氧化，延长其寿命"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-013-解析-p08-482-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-013-解析-p09-51-247.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列与真空有关的说法，错误的是（    ）。","options":[{"k":"A","t":"真空状态下的气体压力低于一个大气压"},{"k":"B","t":"电磁波和声音的传递不受真空状态影响"},{"k":"C","t":"自然环境中只有外太空最接近真空空间"},{"k":"D","t":"真空灯泡能防止灯丝氧化，延长其寿命"}],"material":"","explanation":"13\n\n本题考查科技常识。\n\nA 项正确，真空的本质是气体分子数密度极低的空间状态。物理学中，通常以“气体压力低于标准大气压（约101.325kPa）”作为真空的判定条件。因此，只要空间内气压低于一个大气压，即可称为真空状态。\n\nB 项错误，电磁波（如光、无线电波等）可以在真空中传播，不需要介质，因此在真空中不受影响；但声音是机械波，必须依靠介质（如空气、水、固体）才能传播，在真空中由于缺乏介质，声音无法传播。例如，在外太空（接近真空）中，即使发生剧烈爆炸也听不到声音。\n\n因此，选项整体表述错误。\n\nC 项正确，自然环境中，地球表面被稠密大气层包裹（气压约101kPa）；随高度上升，空气逐渐稀薄，但仍远未达到真空标准。而外太空（如星际空间）气体分子极其稀少（气压趋近于0），是自然条件下最接近理想真空的环境。尽管实验室可制造更高真空度的人工环境，但从自然环境角度看，外太空是唯一最接近真空的空间。\n\nD 项正确，灯泡灯丝多为钨丝，高温下易与氧气反应生成氧化钨（导致灯丝熔断）。真空灯泡通过抽走内部空气（降低氧气含量），阻断了灯丝与氧气的接触，从而减缓氧化和蒸发，延长使用寿命。\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[8,9]},"idx":12,"pid":"p56f583c407"},{"qid":"sy-c-20251025-014","no":14,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[9]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-014-题目-p03-471-562.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"铜、氩气、氢气都属于单质"},{"k":"B","t":"、 、 都是可燃性气体"},{"k":"C","t":"盐水、糖水、蒸馏水都是溶液"},{"k":"D","t":"、 、 都属于空气污染物"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-014-解析-p09-243-720.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于下列物质的分类，说法正确的是（    ）。","options":[{"k":"A","t":"铜、氩气、氢气都属于单质"},{"k":"B","t":"、 、 都是可燃性气体"},{"k":"C","t":"盐水、糖水、蒸馏水都是溶液"},{"k":"D","t":"、 、 都属于空气污染物"}],"material":"","explanation":"14\n\n本题考查科技常识。\n\nA 项正确，单质是指由同种元素组成的纯净物。铜（）是由铜元素组成的金属单质，氩气（）是由氩元素组成的稀有气体单质，氢气（）是由氢元素组成的非金属气体单质。三者均由单一元素构成，且为纯净物，因此均属于单质。因此该说法正确。\n\nB 项错误，可燃性气体是指能够燃烧的气体。\n\n（氢气）和（一氧化碳）具有可燃性，（氢气）燃烧生成水，（一氧化碳）燃烧生成二氧化碳；但（氧气）是助燃剂，仅支持其他物质燃烧（如铁丝在氧气中燃烧），自身不能燃烧。因此该说法错误。\n\nC 项错误，溶液是由溶质和溶剂组成的均一、稳定的混合物。盐水是氯化钠溶于水形成的溶液，糖水是蔗糖溶于水形成的溶液，二者均符合溶液的定义；但蒸馏水是经过蒸馏提纯的纯净水，不含任何溶质，属于纯净物，不是混合物，因此不属于溶液。因此该说法错误。\n\nD 项错误，空气污染物是指对环境和人体健康有害的异常或过量存在的物质。\n\n（二氧化硫）和（二氧化氮）是公认的有害气体，可导致酸雨、雾霾和呼吸系统疾病，属于常规空气污染物；而（二氧化碳）是大气中的天然成分，参与自然循环，虽然过量不被列为“空气污染物”。因排放会加剧温室效应，但在环境科学和空气质量标准中，此该说法错误。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[9]},"idx":13,"pid":"p56f583c407"},{"qid":"sy-c-20251025-015","no":15,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[9,10]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-015-题目-p03-557-648.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"“中国冷极”是由国家气候中心授予黑龙江漠河的国家气候标志"},{"k":"B","t":"北极上空极地涡旋增强使冷空气随之南下是极寒天气的发生背景"},{"k":"C","t":"导致极寒天气的主要因素有北极涛动、气候变暖、拉尼娜现象等"},{"k":"D","t":"某地48小时内最低气温将下降8℃，气象部门应发布寒潮红色预警"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-015-解析-p09-716-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-015-解析-p10-51-565.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列与寒冷天气有关的说法，正确的是（    ）。","options":[{"k":"A","t":"“中国冷极”是由国家气候中心授予黑龙江漠河的国家气候标志"},{"k":"B","t":"北极上空极地涡旋增强使冷空气随之南下是极寒天气的发生背景"},{"k":"C","t":"导致极寒天气的主要因素有北极涛动、气候变暖、拉尼娜现象等"},{"k":"D","t":"某地48小时内最低气温将下降8℃，气象部门应发布寒潮红色预警"}],"material":"","explanation":"15\n\n本题考查科技常识。\n\nA 项错误，“中国冷极”通常指内蒙古根河市，而非黑龙江漠河。内蒙古自治区根河市因多年观测记录显示其冬季极端低温更低、严寒日数更长，于2008 年被国家气候中心正式授予“中国冷极”称号。因此该说法不准确。\n\nB 项错误，极寒天气的发生通常与极地涡旋减弱或分裂有关，而非增强。极地涡旋是北极上空的大型冷性低压系统，正常情况下将冷空气“锁”在极地。当极地涡旋因平流层增温、大气波动等因素减弱或分裂时，冷空气会从北极地区突破西风带屏障南下，侵入中纬度地区，导致我国北方及北美等地出现极端寒潮天气。若极地涡旋增强，反而会更紧密地“封锁”冷空气，减少南下可能。因此，“极地涡旋增强导致冷空气南下”的说法与科学事实相反。\n\nC 项正确，现代气象研究认为，极寒天气的频繁发生并非单一因素所致，而是多种气候系统异常共同作用的结果。其中，北极涛动（AO）处于负相位时，极地与中纬度的气压差减小，极地冷空气更容易向南扩散；全球气候变暖导致北极放大效应（北极地区的气候变暖速度显著快于全球平均水平），削弱了极地与中纬度之间的温度梯度，使极地涡旋更不稳定，易发生分裂；拉尼娜现象则通过改变热带太平洋的海温分布，影响全球大气环流，增强冷空气活动的强度和频率。这三者是近年来我国出现阶段性极寒天气的重要背景因素。\n\nD 项错误，根据中国气象局《气象灾害预警信号发布与传播办法》，寒潮红色预警（最高等级）的发布标准为：48 小时内最低气温将要下降以上，且最低气温小于等于，并可能持续。仅“48 小时内最低气温将下或已经下降以上，最低气温小于等于”这一条件，远未达到红色预警标准，通常对应的是寒潮蓝色预警。因此该说法错误。\n\n降\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[9,10]},"idx":14,"pid":"p56f583c407"},{"qid":"sy-c-20251025-016","no":16,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[10,11]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-016-题目-p03-643-718.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"碱基、核糖均是核糖核苷酸分子的组成部分"},{"k":"B","t":"人类遗传物质以DNA为模板转录生成mRNA"},{"k":"C","t":"人类注射mRNA疫苗是为了获得非特异性免疫"},{"k":"D","t":"mRNA的序列决定了翻译得到的蛋白质的结构"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-016-解析-p10-561-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-016-解析-p11-51-319.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年诺贝尔生理学或医学奖表彰了在核苷碱基修饰方面的发现，这些发现使得mRNA疫苗得以开发。下列有关说法错误的是（    ）。","options":[{"k":"A","t":"碱基、核糖均是核糖核苷酸分子的组成部分"},{"k":"B","t":"人类遗传物质以DNA为模板转录生成mRNA"},{"k":"C","t":"人类注射mRNA疫苗是为了获得非特异性免疫"},{"k":"D","t":"mRNA的序列决定了翻译得到的蛋白质的结构"}],"material":"","explanation":"16\n\n本题考查科技常识。\n\nA 项正确，核苷酸是组成核酸的基本单位，一个核苷酸分子是由一分子含氮的碱基、一分子五碳糖和一分子磷酸组成的。根据五碳糖的不同可以将核苷酸分为脱氧核糖核苷酸和核糖核苷酸，在核糖核苷酸分子中的五碳糖是D－核糖。因此，碱基、核糖均是核糖核苷酸分子的组成部分。\n\nB 项正确，mRNA 即信使RNA，是由DNA 的一条链作为模板转录而来的、携带遗传信息的能指导蛋白质合成的一类单链核糖核酸。\n\nC 项错误，mRNA 疫苗是通过将含有编码抗原蛋白的mRNA 导入人体，跳过复制、转录过程，直接进行翻译，形成相应的抗原蛋白，从而诱导机体产生特异性免疫应答。非特异性免疫即先天性免疫，是机体固有的防御机制，人类注射mRNA 疫苗是为了获得特异性免疫，而不是非特异性免疫。\n\nD 项正确，以细胞中基因为模板，依据碱基互补配对原则转录生成mRNA 后，mRNA 就含有与DNA 分子中某些功能片段相对应的碱基序列，作为蛋白质生物合成的直接模板。因此，mRNA 将遗传信息从DNA 传递到核糖体，在那里作为蛋白质合成模板并决定基因表达蛋白产物肽链的氨基酸序列。\n\n本题为选非题，故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[10,11]},"idx":15,"pid":"p56f583c407"},{"qid":"sy-c-20251025-017","no":17,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[3],"answer":[11]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-017-题目-p03-714-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-017-题目-p04-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"春季有些树木嫩芽因富含花青素而呈褐红色"},{"k":"B","t":"夏季土壤中氮元素过量会导致叶尖黄化焦枯"},{"k":"C","t":"秋季落叶前，树叶会因叶绿素被分解而变黄"},{"k":"D","t":"冬季常绿树木的叶片蜡质层变薄，气孔增多"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-017-解析-p11-315-750.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列关于植物季节性变化的说法，错误的是（    ）。","options":[{"k":"A","t":"春季有些树木嫩芽因富含花青素而呈褐红色"},{"k":"B","t":"夏季土壤中氮元素过量会导致叶尖黄化焦枯"},{"k":"C","t":"秋季落叶前，树叶会因叶绿素被分解而变黄"},{"k":"D","t":"冬季常绿树木的叶片蜡质层变薄，气孔增多"}],"material":"","explanation":"17\n\n本题考查科技常识。\n\nA 项正确，花青素是一种水溶性色素，在细胞液中呈现红色、紫色或蓝色。新芽中叶绿素尚未大量合成，花青素随着气温变化而逐渐合成，颜色便显现出来了，这也是为了保护植物嫩芽不受过度曝晒损伤的一种自我保护机制。\n\nB 项正确，氮元素是植物体内氨基酸的组成部分、是构成蛋白质的成分，也是植物进行光合作用起决定作用的叶绿素的组成部分。钾元素在植物体内以游离钾离子形式存在，它能促进碳水化合物和氮的代谢，钾是维持叶片健康的关键，过量氮肥会打破水稻营养平衡，阻碍钾元素吸收，从而导致叶片边缘黄化焦枯。\n\nC 项正确，随着秋季日照变短、气温降低，植物会将叶片中的养分回收，储存在树干或根部，为冬季生存和来年新生做准备。叶绿素中含有大量的氮和镁，因此，树叶中的叶绿素会迅速分解，而原本被绿色掩盖的类胡萝卜素比较稳定，其颜色便显现出来，使叶片变黄。\n\nD 项错误，常绿树之所以能在冬季保持绿色，主要是因为它们的叶子相对较厚，并且能够分泌出一种蜡质。这种蜡质不仅有助于减少树叶水分的流失，还能为树木提供额外的保护，使其能够有效地抵御寒冷，顺利度过冬季。气孔是植物进行气体交换和水分散失的通道，在冬季，植物为了在寒冷环境中维持体温平衡，部分气孔会自然关闭以减少热量流失。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[3],"answerPages":[11]},"idx":16,"pid":"p56f583c407"},{"qid":"sy-c-20251025-018","no":18,"type":"地理国情","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"地理国情","tag":"地理国情","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[11,12]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-018-题目-p04-87-146.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"小行星带位于水星轨道内侧"},{"k":"B","t":"土卫六的大气主要成分是氮气"},{"k":"C","t":"太阳风产生于太阳的光球层区域"},{"k":"D","t":"人类对海王星的发现早于哈雷彗星"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-018-解析-p11-746-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-018-解析-p12-51-439.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于太阳系的天体，下列说法正确的是（    ）。","options":[{"k":"A","t":"小行星带位于水星轨道内侧"},{"k":"B","t":"土卫六的大气主要成分是氮气"},{"k":"C","t":"太阳风产生于太阳的光球层区域"},{"k":"D","t":"人类对海王星的发现早于哈雷彗星"}],"material":"","explanation":"18\n\n本题考查地理国情。\n\nA 项错误，小行星带位于火星和木星轨道之间，而不是水星轨道内侧。水星是离太阳最近的行星，其轨道内侧没有小行星带。\n\nB 项正确，土卫六又称为泰坦星，是环绕土星运行的一颗卫星，是土星卫星中最大的一个，也是太阳系第二大的卫星。它是太阳系唯一一个拥有浓厚大气层的卫星，其大气主要成分是氮气，是太阳系中惟一除了地球外的富氮星体，那里还有大量不同种类的碳氢化合物残余。\n\nC 项错误，太阳风是一种连续存在，来自太阳并以200-800km/s 的速度运动的等离子体流。\n\n太阳的大气结构从内到外依次为光球层、色球层和日冕层。太阳风是由太阳大气层的最外层——日冕层的剧烈运动产生的。\n\nD 项错误，《春秋》记载，公元前613 年，“有星孛入于北斗”，即指哈雷彗星，这一记录是世界公认的关于哈雷彗星的最早记录。海王星是环绕太阳运行的第八颗行星，也是太阳系中第四大天体，在1846 年才通过数学预测和望远镜观测被发现。因此，人类对海王星的发现是晚于哈雷彗星。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"地理国情","questionPages":[4],"answerPages":[11,12]},"idx":17,"pid":"p56f583c407"},{"qid":"sy-c-20251025-019","no":19,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[12,13]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-019-题目-p04-141-232.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"具身智能体可以有多种形态，能够代替人类从事危险的工作"},{"k":"B","t":"具身智能相较于传统人工智能在静态和结构化任务中表现更好"},{"k":"C","t":"人工智能大模型的发展使具身智能成为人工智能浪潮的重点方向"},{"k":"D","t":"具身智能的机器大脑能够决策，并控制肢体对外部环境变化做出反应"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-019-解析-p12-435-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-019-解析-p13-51-247.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025年《政府工作报告》提出，要培育具身智能等未来产业。关于具身智能，下列说法错误的是（    ）。","options":[{"k":"A","t":"具身智能体可以有多种形态，能够代替人类从事危险的工作"},{"k":"B","t":"具身智能相较于传统人工智能在静态和结构化任务中表现更好"},{"k":"C","t":"人工智能大模型的发展使具身智能成为人工智能浪潮的重点方向"},{"k":"D","t":"具身智能的机器大脑能够决策，并控制肢体对外部环境变化做出反应"}],"material":"","explanation":"19\n\n本题考查科技常识。\n\n具身智能是指智能体（如机器人、无人机、智能汽车等）通过物理实体与环境实时交互，实现感知、认知、决策和行动一体化。\n\nA 项正确，具身智能的核心特征是拥有物理载体（如机器人、无人机等），形态可根据任务需求设计（工业机械臂、家用服务机器人、特种作业机器人等）。其物理实体特性使其能够进入人类无法涉足的危险场景（如高温环境作业、核辐射区域巡检、火灾现场救援等），代替人类完成高风险任务。\n\nB 项错误，传统人工智能主要依赖符号处理和逻辑推理，通过内部算法和计算实现智能行为，通常在虚拟环境中进行大规模的模式识别和推理。而具身智能强调智能的生成依赖于身体和环境的动态交互，智能体在物理空间中感知和行动，进而影响其行为。具身智能对环境的依赖更强，更适合动态、多变的场景，而传统人工智能通常在静态和结构化任务中表现较好。\n\nC 项正确，区别于仅依赖计算的“离身智能”，具身智能设备既能通过传感器感知物理世界，又能借助大模型理解任务、自主决策并执行。近年来随着人工智能大模型的出现与不断迭代，具身智能取得了飞速进步，成为新一波人工智能浪潮的重点方向。\n\nD 项正确，具身智能是指具有身体的智能，其机器大脑能够帮助决策，从而支配肢体能够快速对外部环境变化做出反应，核心在于实体设备与智能决策的深度融合。\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[4],"answerPages":[12,13]},"idx":18,"pid":"p56f583c407"},{"qid":"sy-c-20251025-020","no":20,"type":"科技常识","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"科技常识","tag":"科技常识","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[13]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-020-题目-p04-227-321.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"无人机处于悬停状态时总推力与重力相等"},{"k":"B","t":"无人机可用于评估农作物风险和受灾情况"},{"k":"C","t":"民用无人驾驶航空器所有者应当依法实名登记"},{"k":"D","t":"民用无人机遥控系统可以使用航空无线电频率"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-020-解析-p13-243-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"关于民用无人机，下列说法错误的是（    ）。","options":[{"k":"A","t":"无人机处于悬停状态时总推力与重力相等"},{"k":"B","t":"无人机可用于评估农作物风险和受灾情况"},{"k":"C","t":"民用无人驾驶航空器所有者应当依法实名登记"},{"k":"D","t":"民用无人机遥控系统可以使用航空无线电频率"}],"material":"","explanation":"20\n\n本题考查科技常识。\n\nA 项正确，无人机悬停时处于受力平衡状态，其螺旋桨产生的总推力需要完全抵消自身的重力，才能保持高度不变。这符合基本的力学平衡原理。\n\nB 项正确，民用无人机已广泛应用于农业领域，通过搭载相机、光谱仪等设备，可快速获取农田影像，用于评估农作物长势、病虫害风险及自然灾害后的受灾面积和程度。\n\nC 项正确，根据我国《民用无人驾驶航空器实名制管理规定》，重量在250 克及以上的民用无人机所有者，必须依法进行实名登记，登记信息与无人机绑定，以落实安全责任。\n\nD 项错误，航空无线电频率属于专用频率，主要用于民航客机、运输机等有人航空器的通信、导航和监视，受严格保护。民用无人机的遥控系统通常使用工业、科学和医疗（ISM）频段（如2.4GHz、5.8GHz），禁止擅自使用航空无线电频率，避免干扰民航安全。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"科技常识","questionPages":[4],"answerPages":[13]},"idx":19,"pid":"p56f583c407"},{"qid":"sy-c-20251025-021","no":21,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[13,14]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-021-题目-p04-317-392.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"方兴未艾"},{"k":"B","t":"任重道远"},{"k":"C","t":"拭目以待"},{"k":"D","t":"适当其时"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-021-解析-p13-554-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-021-解析-p14-51-127.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"每个人都是自己健康的第一责任人，健康促进也需要从倡导文明健康的生活方式入手。爱国卫生运动是把群众路线运用于卫生防病工作的成功实践，坚持党的领导、促进全民参与，才能取得最好效果。对偏远地区特别是农村地区而言，群众健康素养水平还有待提升，健康科普还（    ）。","options":[{"k":"A","t":"方兴未艾"},{"k":"B","t":"任重道远"},{"k":"C","t":"拭目以待"},{"k":"D","t":"适当其时"}],"material":"","explanation":"21根据并列词“还”可知，横线处所填词语应和有待提升语义相近，体现出健康素养未达标，健康科普的任务尚未完成之意。B 项“任重道远”比喻责任重大，还需要长期艰苦奋斗，符合文意，当选。\n\nA 项“方兴未艾”指事物正在兴起、发展，一时不会终止，侧重“新生事物处于蓬勃发展阶段”，但健康科普并非“新生事物”，且文段强调的是“任务未完成”，而非“正在蓬勃发展”，与文意不符，排除；C 项“拭目以待”指擦亮眼睛等待着，形容殷切期望或密切关注事态的动向及结果，主语多为“关注者”，如“我们对结果拭目以待”，而此处主语是“健康科普”，搭配不当，排除；D 项“适当其时”指恰巧遇到合适的时机，侧重“时机恰当”，与文意无关，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[4],"answerPages":[13,14]},"idx":20,"pid":"p56f583c407"},{"qid":"sy-c-20251025-022","no":22,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[14]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-022-题目-p04-387-462.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"见怪不怪"},{"k":"B","t":"岿然不动"},{"k":"C","t":"众口一词"},{"k":"D","t":"默不作声"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-022-解析-p14-123-366.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"人形机器人跑“半马”，腿部关节、传动部件在持续的高强度运动中会承受巨大的压力。赛道上，机器人因轴承过热、连杆磨损而摔倒的情况此起彼伏，有的甚至摔得“头身分离”，现场的技术工程师们对此却（    ）。\n\n因为只有让它们在真实、复杂的环境中长距离奔跑，才能够充分暴露存在的技术问题，进而倒逼技术创新。","options":[{"k":"A","t":"见怪不怪"},{"k":"B","t":"岿然不动"},{"k":"C","t":"众口一词"},{"k":"D","t":"默不作声"}],"material":"","explanation":"22根据后文的原因解释可知，横线处应体现出技术工程师们对于机器人出现的各种状况是不意外的，有所预料的。A 项“见怪不怪”指看到怪异的现象或事物不大惊小怪，习以为常，比喻熟视无睹或沉得住气，符合文意，当选。B 项“岿然不动”指像高山一样挺立不动，形容高大、坚强或坚固、不可动摇，主要侧重“身体或立场坚定，不受外界影响”，与文段语境不符，排除；C 项“众口一词”形容许多人说同样的话，与文意无关，排除；D 项“默不作声”指沉默着，不作声，不说话，文段并未指出工程师对此没有说话和出声，而是体现工程师认为摔倒现象是正常的态度，与文段语境不符，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[4],"answerPages":[14]},"idx":21,"pid":"p56f583c407"},{"qid":"sy-c-20251025-023","no":23,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"综合辨析","auxiliary":["搭配对象","转折关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution.multiple","evidence":"与“植物种子自然演化的模式”搭配；转折关系","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[14]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-023-题目-p04-458-517.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"单一 合理"},{"k":"B","t":"简单 精妙"},{"k":"C","t":"便捷 神奇"},{"k":"D","t":"悠久 完美"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-023-解析-p14-362-605.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"某些植物种子迎风而起、随风而落，（    ）的模式其实历经千万年的自然选择演化——能在无主动驱动力的情况下“与风同行”几公里甚至更远的距离，其中包含着特殊的几何结构与（   ）的力学设计。","options":[{"k":"A","t":"单一 合理"},{"k":"B","t":"简单 精妙"},{"k":"C","t":"便捷 神奇"},{"k":"D","t":"悠久 完美"}],"material":"","explanation":"23第一空，根据“其实”可知，此处需与“历经千万年的自然选择演化”构成转折关系，即需体现表面看似简单实则复杂的逻辑。B 项“简单”指不复杂、头绪少，符合语境，当选。A 项“单一”侧重模式唯一，文段未体现种子传播只有这一种方式，不符合语境，排除；C 项“便捷”侧重使用方便，与“植物种子自然演化的模式”搭配不当，排除；D 项“悠久”强调时间久，与后文“历经千万年”无法构成转折关系，不符合语境，排除。\n\n第二空代入验证。“精妙”指精巧、巧妙，置于此处可精准形容力学设计的精细性，与前文“特殊的几何结构”呼应，验证正确。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[4],"answerPages":[14]},"idx":22,"pid":"p56f583c407"},{"qid":"sy-c-20251025-024","no":24,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"搭配对象","auxiliary":["搭配对象"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution","evidence":"固定搭配","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[14,15]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-024-题目-p04-512-587.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"崛起 衍生"},{"k":"B","t":"突起 迸发"},{"k":"C","t":"隆升 酝酿"},{"k":"D","t":"推升 孕育"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-024-解析-p14-601-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-024-解析-p15-51-223.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"地球板块运动所造成的海陆变迁，过去有，现在有，未来仍会继续。不同地貌的形成都是板块运动的一部分。\n\n未来，青藏高原也许会继续（    ），也许会走向垮塌。那么，它影响范围内的地形、水系和气候也会改变，并随之（    ）新的地貌物质基础或新的侵蚀力量。","options":[{"k":"A","t":"崛起 衍生"},{"k":"B","t":"突起 迸发"},{"k":"C","t":"隆升 酝酿"},{"k":"D","t":"推升 孕育"}],"material":"","explanation":"24第一空，搭配“青藏高原”，根据“也许会······也许会······”可知，所填词语应与“垮塌”相对，体现相反的运动。C 项“隆升”是描述地表或地质构造体垂直抬升的地质术语，其核心语义为隆起、升高，在地质学领域特指地壳构造运动引发的区域性抬升现象，此处为固定搭配，当选。A项“崛起”原指地势突起或隆起，后引申为事物兴起、奋起，现在多用于形容势力、国家等，置于此处搭配不当，排除；B 项“突起”指突然爆发，与板块运动的缓慢性矛盾，不符合语境，排除；D 项“推升”侧重外力推动，而青藏高原隆升是板块内力作用的结果，不符合语境，排除。\n\n第二空代入验证。“酝酿”比喻事情逐渐达到成熟的准备过程，置于此处可体现地形、水系变化后，新地貌基础和侵蚀力量缓慢形成，符合语境，当选。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[4],"answerPages":[14,15]},"idx":23,"pid":"p56f583c407"},{"qid":"sy-c-20251025-025","no":25,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"程度轻重","auxiliary":["程度轻重"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution","evidence":"程度过重","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[15]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-025-题目-p04-582-657.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"限定 不容置疑"},{"k":"B","t":"控制 顺理成章"},{"k":"C","t":"束缚 一脉相承"},{"k":"D","t":"局限 实至名归"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-025-解析-p15-219-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"职称要“与职相称”，农民获得职称的业绩和能力是实实在在的“与职相称”，惯常认识中将职称与论文、科研成果、发明专利等挂钩，把职称认知（    ）在高校、科研院所等视野范围。农民职称突破了这些要素，但依然体现了职称是衡量技术水平和专业能力的主要标志，（    ）。","options":[{"k":"A","t":"限定 不容置疑"},{"k":"B","t":"控制 顺理成章"},{"k":"C","t":"束缚 一脉相承"},{"k":"D","t":"局限 实至名归"}],"material":"","explanation":"25\n\n本题可从第二空入手。根据“但依然体现了职称是衡量技术水平和专业能力的主要标志”可知，此处强调农民职称的获得是“实际能力支撑下的合理结果”。D 项“实至名归”指实际的成就到了，名誉也会随之而来，符合语境，当选。A 项“不容置疑”指不允许有任何怀疑，表示论证严密，真实可信，侧重“没有质疑的余地”，强调权威性，未体现“业绩、能力与职称匹配”，不符合语境，且置于此处程度过重，排除；B 项“顺理成章”原指写文章遵循条理便能自然成章，后多指说话、办事合乎情理或自然产生结果，未突出“实际能力支撑”，农民职称的关键是“实实在在的业绩”，而非单纯“合乎情理”，不合语境，排除；C 项“一脉相承”指同一血统或派系的世代传承，后比喻思想学说、行为模式的继承关系，但前文明确说农民职称“突破了这些要素”（传统职称的论文、科研等），故置于此处语义矛盾，排除。\n\n第一空代入验证。“局限”指将认知限制在特定范围（高校、科研院所），符合“惯常认识”对职称的视野窄化，搭配“认知”和“视野范围”得当，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[4],"answerPages":[15]},"idx":24,"pid":"p56f583c407"},{"qid":"sy-c-20251025-026","no":26,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4],"answer":[15]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-026-题目-p04-653-744.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"集成式 举世瞩目"},{"k":"B","t":"跨越式 前所未有"},{"k":"C","t":"爆发式 鹤立鸡群"},{"k":"D","t":"创新式 望尘莫及"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-026-解析-p15-554-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-026-解析-p16-51-88.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"截至2025年5月，全球共发射了超过70颗旨在观测和研究太阳的人造卫（行）星。中国在轨运行卫星“羲和一号”和“夸父一号”实现了我国天基太阳探测卫星的 突破，开启了综合性太阳探测的新时代。为研究太阳磁场、太阳耀斑和日冕物质抛射等现象提供了 的观测能力，使科学家们能够更深入地了解太阳活动的形成、演化、相互作用和可能存在的因果关联。","options":[{"k":"A","t":"集成式 举世瞩目"},{"k":"B","t":"跨越式 前所未有"},{"k":"C","t":"爆发式 鹤立鸡群"},{"k":"D","t":"创新式 望尘莫及"}],"material":"","explanation":"26第一空，根据“开启了综合性太阳探测的新时代”可知，我国的“羲和一号”和“夸父一号”有了划时代的突破。B 项“跨越式”指巨大的、里程碑式的进步，强调质的飞跃和阶段的直接跨越，符合文意，保留。A 项“集成式”指将多个部分、功能整合为一体；C 项“爆发式”指在短时间内集中、剧烈地发生；D 项“创新式”指具有新的想法或方法，三项均与文意不符，排除。\n\n第二空，代入验证。B 项“前所未有”指以前从来没有过。置于此处可体现出“羲和一号”和“夸父一号”开启新时代的观测能力，符合文意，当选。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[4],"answerPages":[15]},"idx":25,"pid":"p56f583c407"},{"qid":"sy-c-20251025-027","no":27,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"综合辨析","auxiliary":["因果关系","并列关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution.multiple","evidence":"因果关系；近义并列","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[4,5],"answer":[16]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-027-题目-p04-739-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-027-题目-p05-51-130.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"伪装性 难以招架"},{"k":"B","t":"普及性 趋于崩溃"},{"k":"C","t":"迷惑性 风光不再"},{"k":"D","t":"逻辑性 面临危机"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-027-解析-p16-83-327.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"生成式AI降低了标题党、“擦边”内容的制作门槛，但技术的加持让AI谣言更具“说服力”、 和强传播性，这使得传统辟谣手段 。可以说，部分生成式AI正在重塑谣言的传播生态，并严重扰乱网络环境。\n\n依次填入画横线部分最恰当的一项是（    ）。","options":[{"k":"A","t":"伪装性 难以招架"},{"k":"B","t":"普及性 趋于崩溃"},{"k":"C","t":"迷惑性 风光不再"},{"k":"D","t":"逻辑性 面临危机"}],"material":"","explanation":"27第一空，根据“、”可知，空处应与“说服力”形成近义并列关系，体现AI 谣言容易让人相信之义。A 项“伪装性”指将虚假的核心伪装成一个真实的外表；C 项“迷惑性”指使辨不清是非；D项“逻辑性”侧重说法听起来很有道理，三项均可体现出AI 谣言更具可信度，保留。B 项“普及性”指推广，使大众化，与“说服力”无关，排除。\n\n第二空，根据“使得”可知，空处应与前文构成因果关系，体现传统辟谣手段很难再阻止AI谣言之义。A 项“难以招架”指无法抵挡、承受或应对，符合文意，当选。C 项“风光不再”指事物由盛转衰的状态，D 项“面临危机”指面临严重困难，两项均与文意不符，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[4,5],"answerPages":[16]},"idx":26,"pid":"p56f583c407"},{"qid":"sy-c-20251025-028","no":28,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[16]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-028-题目-p05-125-216.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"亦步亦趋 落地"},{"k":"B","t":"萧规曹随 明确"},{"k":"C","t":"东施效颦 配套"},{"k":"D","t":"见贤思齐 适用"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-028-解析-p16-322-589.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在出租车行业中，向乘客收取空驶费是许多城市的通行做法。以此推论，网约车“ ”不算随意加价。然而，相关平台对此却没有 的细则，一般是让司机与乘客协商解决。平台此举有变相推卸责任、逃避矛盾纠纷的嫌疑。\n\n依次填入画横线部分最恰当的一项是（    ）。","options":[{"k":"A","t":"亦步亦趋 落地"},{"k":"B","t":"萧规曹随 明确"},{"k":"C","t":"东施效颦 配套"},{"k":"D","t":"见贤思齐 适用"}],"material":"","explanation":"28第一空，根据完整语句“在出租车行业中，向乘客收取空驶费是许多城市的通行做法”可知，横线处应体现网约车借鉴出租车的通行做法。A 项“亦步亦趋”比喻没有主见，处处追随模仿；\n\nB 项“萧规曹随”指完全按照前人的成规办事，两项均符合文意，保留。C 项“东施效颦”比喻模仿别人，不但模仿不好，反而出丑；D 项“见贤思齐”指见到贤能的人就想向他看齐，两项均与文意不符，排除。\n\n第二空，根据“一般是让司机与乘客协商解决”可知，平台对此没有相应的细则。B 项“明确”指清晰明白而确定不移，符合文意，当选。A 项“落地”指政策、规则等从制定到实际实施，侧重过程而非规则本身，与文意不符，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[16]},"idx":27,"pid":"p56f583c407"},{"qid":"sy-c-20251025-029","no":29,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"并列关系","auxiliary":["并列关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution","evidence":"反义并列","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[16,17]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-029-题目-p05-211-318.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"防微杜渐 独立"},{"k":"B","t":"刻舟求剑 中心"},{"k":"C","t":"亡羊补牢 前置"},{"k":"D","t":"不拘一格 领先"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-029-解析-p16-585-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-029-解析-p17-51-223.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"车联网具有“五危一体”的安全特性，即与人身安全强相关、风险范围异常广泛、数据庞大流通难控、智能联网监督难管、多网融合风险蔓延等特性。有别于传统网络安全“附加性”“            ”的技术定位，车联网的安全技术应该处于关键且        的地位。目前，该领域还面临固有网络安全模式风险防范能力不足、法律界定存在真空地带等诸多挑战。\n\n依次填入画横线部分最恰当的一项是（    ）。","options":[{"k":"A","t":"防微杜渐 独立"},{"k":"B","t":"刻舟求剑 中心"},{"k":"C","t":"亡羊补牢 前置"},{"k":"D","t":"不拘一格 领先"}],"material":"","explanation":"29根据“有别于传统网络安全”“车联网的安全技术应该处于”可知，前后空处应构成反义并列。\n\nC 项一空“亡羊补牢”比喻出了问题以后想办法补救，免得以后继续受损失；二空“前置”指将事物置于前面或优先阶段。两空构成反义并列，符合文意，当选。\n\nA 项“防微杜渐”指在错误或坏事刚露出苗头的时候就加以制止，不使其发展，与二空“独立”无法构成反义并列，不符合文意，排除；\n\nB 项“刻舟求剑”比喻办事拘泥、不知根据实际情况变化而灵活处理，与二空“中心”无法构成反义并列，不符合文意，排除；\n\nD 项“不拘一格”指不局限于一种规格或方式，与二空“领先”无法构成反义并列，不符合文意，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[16,17]},"idx":28,"pid":"p56f583c407"},{"qid":"sy-c-20251025-030","no":30,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"综合辨析","auxiliary":["搭配对象","程度轻重"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution.multiple","evidence":"搭配恰当；程度过重","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[17]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-030-题目-p05-314-389.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"相辅相成 后顾之忧"},{"k":"B","t":"此唱彼和 心腹之患"},{"k":"C","t":"相得益彰 池鱼之虑"},{"k":"D","t":"声气相通 当务之急"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-030-解析-p17-219-510.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"保障劳动者权益，不是给企业加“包袱”，社会责任与商业效率可以 。为骑手缴纳社保，不仅能够解除他们的 ，也可以激发他们的工作热情，从而提升服务品质，推动企业收入增长。\n\n依次填入画横线部分最恰当的一项是（    ）。","options":[{"k":"A","t":"相辅相成 后顾之忧"},{"k":"B","t":"此唱彼和 心腹之患"},{"k":"C","t":"相得益彰 池鱼之虑"},{"k":"D","t":"声气相通 当务之急"}],"material":"","explanation":"30第一空，根据“保障劳动者权益，不是给企业加‘包袱’”可知，社会责任（保障劳动者权益）与商业效率并非对立关系，二者可以共同发展，横线处应体现共同发展、相互配合之意。A项“相辅相成”指两件事物互相配合，B 项“此唱彼和”比喻人与人之间或事物之间互相配合、彼此呼应的状态，C 项“相得益彰”指相互配合得好，各方的长处就更能显现，三项均符合文意，保留。D 项“声气相通”指彼此串通，互通消息，与文意无关，排除。\n\n第二空，搭配“解除”，横线处应体现为骑手缴纳社保后消除他们的生活困扰。A 项“后顾之忧”形容来自后方的忧患，符合文意，且搭配恰当，当选。B 项“心腹之患”比喻隐藏在内部的严重祸害，程度过重，且与“解除”搭配不当；C 项“池鱼之虑”比喻因牵连而蒙受灾祸的忧虑，与文意无关，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[17]},"idx":29,"pid":"p56f583c407"},{"qid":"sy-c-20251025-031","no":31,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"综合辨析","auxiliary":["搭配对象","程度轻重","感情色彩"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution.multiple","evidence":"与“限制”搭配；程度过重；感情色彩","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[17,18]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-031-题目-p05-384-475.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"确定 取决 破除"},{"k":"B","t":"固定 借助 去除"},{"k":"C","t":"特定 依赖 突破"},{"k":"D","t":"一定 受制 攻破"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-031-解析-p17-506-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-031-解析-p18-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"过去，科研人员进行遗传育种，主要“靠天吃饭”，许多鱼类有（    ）的繁殖周期，基本上一年才产一次卵，其繁殖受到季节和环境的严格限制，育种工作者只能在鱼类自然繁殖季节进行相关操作。这使得育种进程在很大程度上（    ）于自然繁殖周期。而使用现代循环水系统的遗传育种研究平台，可以（    ）这一周期的限制，助力鱼类遗传育种发展。","options":[{"k":"A","t":"确定 取决 破除"},{"k":"B","t":"固定 借助 去除"},{"k":"C","t":"特定 依赖 突破"},{"k":"D","t":"一定 受制 攻破"}],"material":"","explanation":"31第一空，搭配“繁殖周期”，根据后文“基本上一年才产一次卵，其繁殖受到季节和环境的严格限制”可知，许多鱼类的繁殖周期是具有规律性、周期性的，B 项“固定”，C 项“特定”，D项“一定”均符合文意，保留。A 项“确定”指明确肯定，由文中只知道基本上一年一次，但是具体的周期无法确定，故程度过重，排除。\n\n第二空，根据指代词“这”及因果词“使得”可知，前文描述的情况对后文造成了影响，即“育种工作者只能在鱼类自然繁殖季节进行相关操作”这件事让育种进程取决于自然繁殖周期，C项“依赖”、D 项“受制”符合文意，保留。B 项“借助”指凭借、依靠别的人或事物的帮助，感情色彩积极，而此处要体现自然繁殖周期对育种进程的限制，故置于此处感情色彩不符，排除。\n\n第三空，搭配“限制”，根据前文可知，使用现代循环水系统的遗传育种研究平台，可以让育种进程不再受到自然繁殖周期的限制。C 项“突破”符合文意且搭配得当，当选。D 项“攻破”一般搭配“难关”“难题”等，与“限制”搭配不当，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[17,18]},"idx":30,"pid":"p56f583c407"},{"qid":"sy-c-20251025-032","no":32,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[18]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-032-题目-p05-471-578.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"理性 真实 雅量"},{"k":"B","t":"准确 普遍 胸襟"},{"k":"C","t":"清楚 客观 风范"},{"k":"D","t":"完整 具体 姿态"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-032-解析-p18-195-510.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"患者在评价自身的就医体验时，可能并不总是那么 ，有时候欠缺专业，甚至难免夹杂着情绪。患者基于 就医体验而发出的抱怨、吐槽乃至于批评，医院应该认真倾听，应抱着有则改之、无则加勉的态度对待各方的声音。即便是一些比较激烈的言辞，只要没有越过法律和道德的底线，也要有倾听的 ，这有利于把风险隐患消除于萌芽之中，缓解医患矛盾。\n\n依次填入画横线部分最恰当的一项是（    ）。","options":[{"k":"A","t":"理性 真实 雅量"},{"k":"B","t":"准确 普遍 胸襟"},{"k":"C","t":"清楚 客观 风范"},{"k":"D","t":"完整 具体 姿态"}],"material":"","explanation":"32第一空，根据“有时候欠缺专业，甚至难免夹杂着情绪”可知，患者对自身就医体验的评价不够专业，较为主观，横线处应体现合理、客观之意，A 项“理性”指处理问题按照事物发展的规律和自然进化原则，不冲动、不情绪化，B 项“准确”指符合事实、标准或真实情况，两项均符合文意，保留。C 项“清楚”指清晰明白、不模糊，D 项“完整”指具有或保持着应有的各部分，没有损坏或残缺，两项均与文意不符，排除。\n\n第二空，根据“患者在评价自身的就医体验时”可知，横线处应体现患者是结合自身实际经历的就医过程。A 项“真实”指跟客观事实相符合，符合文意，当选。B 项“普遍”指存在的面很广泛、具有共同性，与文意不符，排除。\n\n代入验证第三空。医院面对未越底线的激烈言辞时，应具备包容、接纳的气度，A 项“雅量”意为宽宏的气度，符合文意，当选。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[18]},"idx":31,"pid":"p56f583c407"},{"qid":"sy-c-20251025-033","no":33,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[18,19]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-033-题目-p05-573-664.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"吸附 调整 任务"},{"k":"B","t":"舔食 改进 途径"},{"k":"C","t":"蘸取 变换 策略"},{"k":"D","t":"稀释 更新 方法"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-033-解析-p18-506-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-033-解析-p19-51-112.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"不同植物的花蜜糖分和粘度各异，最甜美的花蜜通常也最粘稠、最难采集，蜜蜂可以通过多毛的中唇舌很容易地（    ）高粘度的花蜜，也能主动（    ）口器操控方法，用其喙部直接吸食花冠深处的花蜜，这使得转运低粘度的远处液体更有效率，蜜蜂这种特化的口器结构和摄食（    ），是通过上亿年与植物的共同演化逐渐成熟的。","options":[{"k":"A","t":"吸附 调整 任务"},{"k":"B","t":"舔食 改进 途径"},{"k":"C","t":"蘸取 变换 策略"},{"k":"D","t":"稀释 更新 方法"}],"material":"","explanation":"33第一空，结合语境“蜜蜂通过多毛的中唇舌”“高粘度的花蜜”，可知应体现通过多毛的唇舌可粘住高粘度的花蜜，从而实现采集。B 项“舔食”能够体现出成功采集花蜜，保留；C 项“蘸取”指沾染取用，能体现出多毛结构粘住粘稠液体的特点，保留；A 项“吸附”侧重动作“吸”从而\n\n本题从第二空入手更为简便。空处与前文“层层递进、重点突出”形成并列，且对应后文“闭环链条”，可知此处需体现教学链条的逻辑关联性与完整性。A 项“严丝合缝”指衔接紧密，毫无缝隙，B 项“连续不断”强调不间断，此两项均无法体现出教学链条的完整性，不合文意，均排除；C 项“环环相扣”可体现出逻辑关联性，但无法对应与后文“闭环”，不合文意，排除。\n\nD 项“首尾呼应”指开头结尾相呼应，能体现链条的逻辑关联性与完整性，当选。\n\n第一空、第三空代入验证，“对问题进行整体化、链条式推进”能体现出问题设计具备系统性，符合语境；“消化知识时游刃有余”能体现出学生消化知识的状态从容熟练，符合语境，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[18,19]},"idx":32,"pid":"p56f583c407"},{"qid":"sy-c-20251025-034","no":34,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[5],"answer":[19]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-034-题目-p05-660-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-034-题目-p06-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"全方位 严丝合缝 抽丝剥茧"},{"k":"B","t":"阶段性 连续不断 洞若观火"},{"k":"C","t":"一站式 环环相扣 了然于胸"},{"k":"D","t":"整体化 首尾呼应 游刃有余"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-034-解析-p19-107-335.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在教学实践中，教师既要学会用有效精准的问题架构课堂，又要锚定课程目标，对问题进行（    ）、链条式推进，这一过程中，要根据课程目标合理设置主干问题、辅助问题、承上启下的介质问题，形成层层递进、重点突出、（    ）的闭环链条。这样一来，既能让学生构筑起理论知识的大厦，又能让他们掌握其四梁八柱、内在机理，在消化知识时（    ）。","options":[{"k":"A","t":"全方位 严丝合缝 抽丝剥茧"},{"k":"B","t":"阶段性 连续不断 洞若观火"},{"k":"C","t":"一站式 环环相扣 了然于胸"},{"k":"D","t":"整体化 首尾呼应 游刃有余"}],"material":"","explanation":"34\n\n本题从第二空入手更为简便。空处与前文“层层递进、重点突出”形成并列，且对应后文“闭环链条”，可知此处需体现教学链条的逻辑关联性与完整性。A 项“严丝合缝”指衔接紧密，毫无缝隙，B 项“连续不断”强调不间断，此两项均无法体现出教学链条的完整性，不合文意，均排除；C 项“环环相扣”可体现出逻辑关联性，但无法对应与后文“闭环”，不合文意，排除。\n\nD 项“首尾呼应”指开头结尾相呼应，能体现链条的逻辑关联性与完整性，当选。\n\n第一空、第三空代入验证，“对问题进行整体化、链条式推进”能体现出问题设计具备系统性，符合语境；“消化知识时游刃有余”能体现出学生消化知识的状态从容熟练，符合语境，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[5],"answerPages":[19]},"idx":33,"pid":"p56f583c407"},{"qid":"sy-c-20251025-035","no":35,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"综合辨析","auxiliary":["搭配对象","感情色彩","并列关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"fill.solution.multiple","evidence":"搭配恰当；感情色彩；近义并列","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6],"answer":[19]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-035-题目-p06-87-178.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"津津乐道 框架性 消极"},{"k":"B","t":"绘声绘色 历史性 具象"},{"k":"C","t":"眉飞色舞 抽象性 悲观"},{"k":"D","t":"兴致勃勃 总括性 负面"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-035-解析-p19-331-646.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"说起欧洲，人们会（    ）地谈起每个国家的特色，历史与当下，优点与缺点；但是说起非洲，似乎只是“非洲”——没有具体的国家，没有鲜明的文化面貌，有的只是一个模糊的、（    ）的概念，一个遥远的、与现实脱节的标签，并且往往被贫穷、饥饿、暴力、疾病等（    ）词语所裹挟，我们对世界的认知，是如此不平衡。","options":[{"k":"A","t":"津津乐道 框架性 消极"},{"k":"B","t":"绘声绘色 历史性 具象"},{"k":"C","t":"眉飞色舞 抽象性 悲观"},{"k":"D","t":"兴致勃勃 总括性 负面"}],"material":"","explanation":"35第一空，搭配“谈起”，体现人们谈论欧洲各国特色时的积极状态。A 项“津津乐道”指很有兴趣地说个不停，B 项“绘声绘色”指语言表达或文学描写具有强烈的真实感与画面感，C 项“眉飞色舞”指人因喜悦或得意而神情兴奋，D 项“兴致勃勃”指兴趣很浓厚，情绪很高，四项均符合文意，保留。\n\n第二空，横线处需同“模糊的”构成近义并列关系，C 项“抽象性”指笼统的，D 项“总括性”指抽象概括，两项均符合文意，保留。A 项“框架性”侧重知识的清晰、确定性，B 项“历史性”侧重与历史相关，两项均文意无关，排除。\n\n第三空，搭配“词语”，且根据“贫穷、饥饿、暴力、疾病”可知，横线处所填内容感情色彩应偏消极，D 项“负面”指坏的、消极的，搭配恰当，当选。C 项“悲观”指精神颓丧，对事物的发展缺乏信心，常搭配“人”，搭配“词语”不当，排除。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[6],"answerPages":[19]},"idx":34,"pid":"p56f583c407"},{"qid":"sy-c-20251025-036","no":36,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"意图判断","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"意在","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6],"answer":[19,20]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-036-题目-p06-173-312.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"应理性看待CT检查"},{"k":"B","t":"“拍CT致癌”纯属谣言"},{"k":"C","t":"CT检查可能存在健康风险"},{"k":"D","t":"CT检查致癌研究存在严重缺陷"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-036-解析-p19-641-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-036-解析-p20-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"一篇研究文章称，某地2023年的CT检查，预计将导致约10.3万癌症新发病例；如果状况持续下去，CT相关癌症最终可能占每年所有新发癌症病例的5%。该事件在传播过程中被贴上“CT是癌症制造机”的标签，引发公众关注。“拍CT致癌”的相关说法已经不是第一次出现了。我们仔细看一下这个研究就能发现，它分析的是CT检查与癌症发生之间的相关性，而数据统计中的相关性并不等于因果性。所以，对此研究不必过分担忧，医学界也有共识，一般来说，常规CT检查收益大于风险，避免过度CT检查即可。\n\n这段文字意在说明（    ）。","options":[{"k":"A","t":"应理性看待CT检查"},{"k":"B","t":"“拍CT致癌”纯属谣言"},{"k":"C","t":"CT检查可能存在健康风险"},{"k":"D","t":"CT检查致癌研究存在严重缺陷"}],"material":"","explanation":"36文段开篇通过一篇研究文章引出CT 检查导致的癌症新发病例，随后指出“CT 是癌症制造机”的传播误区，再通过“相关性≠因果性”澄清研究结论，最终通过“所以”得出结论，不必过分担忧CT 检查会导致癌症发生，避免过度CT 检查即可。故文段属于分总结构，重点强调不必过分担忧CT 检查会导致癌症发生，即应理性看待CT 检查，对应A 项。\n\nB 项，“纯属谣言”表述绝对，文段并未完全否定CT 检查致癌的可能性，排除；\n\nC 项，“可能存在健康风险”偏离文段重点，排除；\n\nD 项，“严重缺陷”无中生有，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[6],"answerPages":[19,20]},"idx":35,"pid":"p56f583c407"},{"qid":"sy-c-20251025-037","no":37,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"意图判断","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"意在","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6],"answer":[20]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-037-题目-p06-308-447.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"军事理论科学性的主要来源"},{"k":"B","t":"军事理论跃升发展的新路径"},{"k":"C","t":"构建军事理论体系的切入点"},{"k":"D","t":"推进军事理论创新的必要性"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-037-解析-p20-195-438.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"当前，实现建军一百年奋斗目标进入攻坚期，如何拓展新征程军队改革建设成果，如何高效攻坚，需要科学理论指引；建设世界一流军队，如何引领未来、破局开新，全面提升现代军事体系软硬件水平，如何培育一流军队的思维理念、胜战能力和精神气魄，需要卓越理论灌注。有加快推进军事理论创新，深刻洞悉强军大业深层规律，科学把握近期、中期、远期的战略衔接，形成世界一流的战争理论、战略指导和军事思想，才能又好又快地引领我军强军事业高起点跃升、高质量发展。\n\n这段文字意在说明（    ）。","options":[{"k":"A","t":"军事理论科学性的主要来源"},{"k":"B","t":"军事理论跃升发展的新路径"},{"k":"C","t":"构建军事理论体系的切入点"},{"k":"D","t":"推进军事理论创新的必要性"}],"material":"","explanation":"37文段开篇通过两个“如何”提出问题，点明新征程军队建设面临的关键需求：实现建军百年奋斗目标，需要科学理论指引；建设世界一流军队，需要卓越理论灌注。尾句以必要条件关联词“只有······才”点明观点，论述“军事理论创新”的必要性及其意义效果，即引领强军事业跃升和发展。故文段重点强调对策，对应D 项。\n\nA 项，“来源”文段未提及，无中生有，排除。\n\nB 项，“跃升发展”对应意义效果部分，且“新路径”与“创新”相比，表述不明确，排除。\n\nC 项，“切入点”意为做事最先着手之处，文段未提及，排除。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[6],"answerPages":[20]},"idx":36,"pid":"p56f583c407"},{"qid":"sy-c-20251025-038","no":38,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"主旨概括","auxiliary":["主题词","解释说明与例证"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"主要介绍","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6],"answer":[20]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-038-题目-p06-442-597.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"太空微重力环境对原子钟的影响"},{"k":"B","t":"晶体振荡器与原子钟的运作机制"},{"k":"C","t":"空间冷原子钟高精度计时的奥秘"},{"k":"D","t":"原子钟在航空航天领域中的应用"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-038-解析-p20-434-701.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在浩瀚的宇宙中，有一只特殊的钟，它没有钟摆的摆动，也没有秒针的滴答声，它静静地存在于天宫二号空间实验室内，精准地记录着时间的流逝。这只钟，就是人类历史上首次在太空中进行科学实验的空间冷原子钟。\n\n在太空微重力环境下，激光冷却技术使得原子能做出超慢速的匀速直线运动，譬如，对于铯原子气体，激光冷却能将其温度降至接近绝对零度，原子的热运动几乎被完全抑制，这极大地消除了原子热运动对原子钟性能的影响，所以原子在空间中振动得非常规律，之后，通过晶体振荡器来放大这个振动，就能实现高精度的时间测量。\n\n这段文字主要介绍（    ）。","options":[{"k":"A","t":"太空微重力环境对原子钟的影响"},{"k":"B","t":"晶体振荡器与原子钟的运作机制"},{"k":"C","t":"空间冷原子钟高精度计时的奥秘"},{"k":"D","t":"原子钟在航空航天领域中的应用"}],"material":"","explanation":"38文段开篇引入空间冷原子钟的话题并描述其存在的位置。接着指出激光冷却技术能使原子能做出超慢速的匀速直线运动并举例说明。最后通过结论词“所以”总结全文，强调正是因为有上文介绍的特性，空间冷原子钟可以实现高精度的时间测量。故文段为因果文段，重点强调尾句的结论，对应C 项。\n\nA 项，属于中间解释说明的内容，非重点，且文段围绕冷原子钟展开，该项主题词错误，排除；\n\nB 项，属于结论之前的内容，非重点，排除；\n\nD 项，属于结论之前的内容，非重点且“应用”表述不明确，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[6],"answerPages":[20]},"idx":37,"pid":"p56f583c407"},{"qid":"sy-c-20251025-039","no":39,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"语句表达","tag":"接语选择","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"接下来","curriculum":{"file":"言语理解与表达.pdf","pages":"39–58","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6],"answer":[20,21]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-039-题目-p06-593-716.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"推进文化育人的工作方向"},{"k":"B","t":"构建文化育人体系的必要性"},{"k":"C","t":"文化育人对落实立德树人的基本要求"},{"k":"D","t":"中华优秀传统文化对文化育人的作用"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-039-解析-p20-697-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-039-解析-p21-51-271.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"文化育人是人与文化的双向构建活动，旨在用先进文化教育人、引导人、鼓舞人、塑造人，贯穿于学校办学治校特别是人才培养的全过程和各方面。文化育人不仅重要而且紧要，是落实立德树人根本任务、培养担当民族复兴大任的时代新人的要求，是继续推动文化繁荣、建设文化强国、建设中华民族现代文明的迫切需要，是提升国家文化软实力、以中国式现代化全面推进中华民族伟大复兴的强大精神力量。\n\n这段文字接下来最可能介绍（    ）。","options":[{"k":"A","t":"推进文化育人的工作方向"},{"k":"B","t":"构建文化育人体系的必要性"},{"k":"C","t":"文化育人对落实立德树人的基本要求"},{"k":"D","t":"中华优秀传统文化对文化育人的作用"}],"material":"","explanation":"39文段首句通过下定义引出“文化育人”这一话题，指出“文化育人”贯穿于学校办学治校特别是人才培养的全过程和各方面。接着从三个角度论述“文化育人”的重要性以及重要作用，按照“是什么—为什么—怎么做”的常见逻辑，接下来最可能讲如何推进文化育人，对应A 项。\n\nB 项，“构建文化育人体系的必要性”为前文已论述内容，排除；\n\nC 项，“立德树人”、D 项，“中华优秀传统文化”均为文段尾句的片面部分，属于前文已论述内容，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[6],"answerPages":[20,21]},"idx":38,"pid":"p56f583c407"},{"qid":"sy-c-20251025-040","no":40,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[6,7],"answer":[21]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-040-题目-p06-711-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-040-题目-p07-51-178.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"我国野苹果资源只分布在新疆伊犁地区"},{"k":"B","t":"苹果小吉丁的幼虫以尚未成熟的苹果为食"},{"k":"C","t":"苹果小吉丁已对巩留县野果林造成普遍危害"},{"k":"D","t":"苹果小吉丁上世纪九十年代初开始在新疆发现"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-040-解析-p21-267-534.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"苹果小吉丁属于鞘翅目吉丁虫科，一年发生一代，主要以幼虫钻蛀野苹果枝干的韧皮部和木质部造成危害，导致营养和水分输断，常造成枝条干枯或整树枯死，是新疆巩留县乃至伊犁地区野果林的重要蛀干性害虫。自1993年在新疆发现以来，已经在野果林中大面积扩散蔓延，巩留县野果林苹果小吉丁发生面积甚至已与野果林分布面积相当，伊犁天山野果林是我国唯一的野生苹果林资源分布区，也是我国唯一的世界野苹果基因库组成部分，研究影响苹果小吉丁种群数量的重要环境因子，对控制苹果小吉丁的危害及传播有重要意义。\n\n下列说法与原文不符的是（    ）。","options":[{"k":"A","t":"我国野苹果资源只分布在新疆伊犁地区"},{"k":"B","t":"苹果小吉丁的幼虫以尚未成熟的苹果为食"},{"k":"C","t":"苹果小吉丁已对巩留县野果林造成普遍危害"},{"k":"D","t":"苹果小吉丁上世纪九十年代初开始在新疆发现"}],"material":"","explanation":"40\n\nA 项，根据“伊犁天山野果林是我国唯一的野生苹果林资源分布区”可知，“唯一分布区”直接对应“我国野苹果资源只分布在新疆伊犁地区”，选项表述正确，排除；\n\nB 项，根据“主要以幼虫钻蛀野苹果枝干的韧皮部和木质部造成危害”可知，文中并未提及以尚未成熟的苹果为食，选项表述与原文不符，当选；\n\nC 项，根据“巩留县野果林苹果小吉丁发生面积甚至已与野果林分布面积相当”可知，危害已覆盖大部分区域，即“普遍危害”，选项表述正确，排除；\n\nD 项，根据“自1993 年在新疆发现以来，已经在野果林中大面积扩散蔓延”可知，苹果小吉丁被大量发现的时候是在上世纪九十年代，时间表述一致，选项正确，排除。\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[6,7],"answerPages":[21]},"idx":39,"pid":"p56f583c407"},{"qid":"sy-c-20251025-041","no":41,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[7],"answer":[21]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-041-题目-p07-173-296.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"作用方式"},{"k":"B","t":"优势特点"},{"k":"C","t":"应用领域"},{"k":"D","t":"未来发展"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-041-解析-p21-530-749.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"传统的口服或者静脉给药方式效率有限，药物在全身循环中容易“迷路”，难以精准到达病灶部位。对此，某研究团队研发了一种柔性可植入式电子贴片，该贴片融合了柔性电子、微纳加工等前沿技术，具有无线控制、轻薄、易贴附的特点，可以像创可贴一样贴在生物体器官上，将药物精准送达靶器官和细胞内部。对比传统的递送方法，该贴片将药物分子递送速度提升上万倍，还能通过调控电参数精准控制药物进入器官的深度及剂量。目前，该技术已实现成果转化，应用在皮肤创伤修复等领域。\n\n关于这种电子贴片，这段文字没有提及（    ）。","options":[{"k":"A","t":"作用方式"},{"k":"B","t":"优势特点"},{"k":"C","t":"应用领域"},{"k":"D","t":"未来发展"}],"material":"","explanation":"41\n\nA 项“作用方式”对应文段“该贴片融合了柔性电子、微纳加工等前沿技术······可以像创可贴一样贴在生物体器官上，将药物精准送达靶器官和细胞内部”，文段有提及，排除；\n\nB 项“优势特点”对应文段“递送速度提升上万倍还能通过调控电参数精准控制药物进入器官的深度及剂量”，文段有提及，排除；\n\nC 项“应用领域”对应文段“应用在皮肤创伤修复等领域”，文段有提及，排除；\n\nD 项“未来发展”，文段中未提及，当选。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[7],"answerPages":[21]},"idx":40,"pid":"p56f583c407"},{"qid":"sy-c-20251025-042","no":42,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"片段阅读","tag":"标题选择","auxiliary":["主题词"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"标题","curriculum":{"file":"言语理解与表达.pdf","pages":"1–38","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[7],"answer":[21,22]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-042-题目-p07-292-447.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"先天具备克隆本领的植物"},{"k":"B","t":"发现地球上最古老的生物"},{"k":"C","t":"研究揭示潘多森林的长寿秘诀"},{"k":"D","t":"自我复制成就最庞大的克隆体"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-042-解析-p21-745-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-042-解析-p22-51-319.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"美国犹他州的潘多森林是一片由近5万棵克隆体植株组成的大规模无性系颤杨林，其地下部分来自同一个庞大的根系。研究人员对其中500多棵植株的体细胞组织样本进行遗传测序分析，通过构建系统发育模型，结合附近湖泊沉积物中的古花粉证据，确认其已存活了16000～80000年，是地球上最古老的生物之一。通过分析潘多森林在反复克隆自身时出现的近4000个体细胞遗传突变，发现整个森林的遗传信息呈现出较为均匀的混合模式。这暗示了植物中或许存在某种遗传机制，可以防止有害突变在克隆体基因组之间的积累和传播，因此它们不会因持续克隆而患病或严重退化。\n\n最适合做这段文字标题的是（    ）。","options":[{"k":"A","t":"先天具备克隆本领的植物"},{"k":"B","t":"发现地球上最古老的生物"},{"k":"C","t":"研究揭示潘多森林的长寿秘诀"},{"k":"D","t":"自我复制成就最庞大的克隆体"}],"material":"","explanation":"42文段开篇介绍潘多森林的基本特征，接着通过研究确认其是地球最古老生物之一，随后进一步说明研究发现其遗传信息均匀混合。文段最后通过“这暗示了”引出观点，紧接着通过“因此”得出结论，指出潘多森林不会因持续克隆而患病或严重退化，故文段重在论述潘多森林能存活上万年，即潘多森林寿命长的原因，对应C 项。\n\nA 项，缺少主题词“潘多森林”，且对应结论前内容，非重点，排除。\n\nB 项，缺少主题词“潘多森林”，且该项表述绝对，文中提及“最古老生物之一”，而非“最古老生物”，排除。\n\nD 项，缺少主题词“潘多森林”，且对应结论前内容，非重点，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[7],"answerPages":[21,22]},"idx":41,"pid":"p56f583c407"},{"qid":"sy-c-20251025-043","no":43,"type":"逻辑填空","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"逻辑填空","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"言语理解与表达.pdf","pages":"59–81","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[7],"answer":[22]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-043-题目-p07-442-581.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"可以助推天气与气候领域的研究"},{"k":"B","t":"就能得到一个更全面的天气预报"},{"k":"C","t":"准确预测极端天气事件就成为可能"},{"k":"D","t":"有望在算力和预测效果间达成平衡"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-043-解析-p22-315-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"迄今为止，一些已发布的基于机器学习的人工智能天气预报系统都是“确定性”模型，这意味着它们只提供单一预测，并且无法对预测的正确性进行估测。相比之下，基于扩散模型的天气预报系统生成的是“集合”预报。换言之，它是一系列预测的集合，其中每个预测都具有略微不同的初始条件，每个预测都代表一个可能的天气轨迹。通过将这些预测集合成一个整体，                    。集合预报比单一预报更为有效，因为它可以呈现未来几天或几周内可能发生的多种天气情况，并衡量每种情况的可能性。\n\n填入文中横线处最恰当的一项是（    ）。","options":[{"k":"A","t":"可以助推天气与气候领域的研究"},{"k":"B","t":"就能得到一个更全面的天气预报"},{"k":"C","t":"准确预测极端天气事件就成为可能"},{"k":"D","t":"有望在算力和预测效果间达成平衡"}],"material":"","explanation":"43横线在中间，需要承上启下。横线前将“扩散模型的天气预报系统”同“机器学习的人工智能天气预报系统”进行对比，凸显“集合预报”的优势。横线后再次指出“集合预报”对于呈现天气情况的有效性。故横线处需体现“集合成一个整体”的结果——即得到一个更全面、更有效的天气预报，对应B 项。\n\nA 项，“天气与气候领域”偷换概念，文段强调“集合预报对于天气预报的优势”，排除；\n\nC 项，“极端天气事件”无中生有，排除；\n\nD 项，“算力和预测效果间达成平衡”无中生有，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"逻辑填空","questionPages":[7],"answerPages":[22]},"idx":42,"pid":"p56f583c407"},{"qid":"sy-c-20251025-044","no":44,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"语句表达","tag":"语句排序","auxiliary":["确定首尾句","时间顺序"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"排序","curriculum":{"file":"言语理解与表达.pdf","pages":"39–58","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[7],"answer":[22]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-044-题目-p07-577-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-044-题目-p08-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③②⑤⑥④"},{"k":"B","t":"①⑥③④⑤②"},{"k":"C","t":"④③①⑥⑤②"},{"k":"D","t":"④⑤②③①⑥"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-044-解析-p22-554-749.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"①由于糖的成瘾性和人类味觉对糖与甜的独特嗜好，以古代中国和古印度为中心的甘蔗种植与蔗糖生产不断冲破地域和国家界限\n\n②大航海时代以来，蔗糖成为国际贸易中同香料、茶叶、瓷器等同等重要的大宗商品，对近代欧洲和国际事务产生了广泛而深刻的影响\n\n③在蔗糖出现前，蜂蜜作为主要甜味剂，在古代中国、印度等国家的社会生活中扮演了重要角色\n\n④糖在人类活动中用途广泛，可食用、可入药、可作防腐剂，甚至用于宗教文化活动等\n\n⑤具有重要商业价值的甘蔗，是近代早期“哥伦布大交换”中旧大陆向新大陆移植最成功、影响最大的经济作物\n\n⑥甘蔗在南亚、东亚和地中海等诸多地区实现了广泛栽培、食用与传播将以上六个句子重新排序，语序正确的是（    ）。","options":[{"k":"A","t":"①③②⑤⑥④"},{"k":"B","t":"①⑥③④⑤②"},{"k":"C","t":"④③①⑥⑤②"},{"k":"D","t":"④⑤②③①⑥"}],"material":"","explanation":"44对比选项，确定首句。首句分别是①和④两句，①句围绕“糖”的话题，介绍其用途广泛，④句分析糖在不同地域和国家扩散的原因，按照逻辑顺序，应先从宏观上论述糖的“实用、入药”等作用，再具体分析，故①不适合做首句，排除A、B 项。\n\n观察选项，④句后紧跟③句或⑤句，③句论述“蔗糖出现之前”的甜味剂，⑤句围绕“甘蔗”介绍其商业价值，故按照时间顺序，③句应在⑤句前，对应C 项。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[7],"answerPages":[22]},"idx":43,"pid":"p56f583c407"},{"qid":"sy-c-20251025-045","no":45,"type":"片段阅读","module":"言语理解与表达","classification":{"version":"shiye-v1.20261011","group":"语句表达","tag":"语句排序","auxiliary":["确定首尾句"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"verbal.request","evidence":"排序","curriculum":{"file":"言语理解与表达.pdf","pages":"39–58","map":"5.言语理解与表达.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8],"answer":[22,23]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-045-题目-p08-87-293.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"②④③①⑥⑤"},{"k":"B","t":"④②⑥③①⑤"},{"k":"C","t":"⑤③②④⑥①"},{"k":"D","t":"⑥③⑤②④①"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-045-解析-p22-745-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-045-解析-p23-51-250.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"①但整体而言，这些定向能武器的技术成熟度仍不够高，例如激光武器功率偏低，对无人机持续照射数秒才能将其击落，难以应对大批无人机来袭\n\n②目前许多国家都在研制和装备新一代精确制导火箭弹，希望用这种成本相对较低的精确制导武器拦截飞行路线固定的无人机\n\n③其中枪支和速射炮射程与精度有限，对无人机的毁伤效果不好\n\n④激光和高功率微波武器发射时只消耗电力，成本最低，因此也受到各国青睐\n\n⑤防空导弹虽然命中率高，但成本过于昂贵，价格动辄数万甚至数十万美元，远远超过多旋翼无人机的价格\n\n⑥针对无人机的硬杀伤手段种类较多，从传统的枪支或防空速射炮，到防空导弹和精确制导火箭弹，再到激光或高功率微波等定向能武器，大都已经投入实战或进入测试阶段将以上六个句子重新排序，语序正确的是（    ）。","options":[{"k":"A","t":"②④③①⑥⑤"},{"k":"B","t":"④②⑥③①⑤"},{"k":"C","t":"⑤③②④⑥①"},{"k":"D","t":"⑥③⑤②④①"}],"material":"","explanation":"45对比选项，确定首句。根据选项可知，首句各不相同，②句介绍的是精确制导火箭弹对无人机的拦截，④句指出激光和高功率微波武器对无人机的拦截，⑤句介绍防空导弹的优缺点，\n\n⑥句引出各类针对无人机的硬杀伤手段，包括了②④⑤句中的话题，且根据句内的“从······到······再到······”可知，展开顺序依次为防空导弹（⑤句）、精确制导火箭弹（②句）、激光和高功率微波武器（④句）。即⑥句在前，总领全文。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/言语理解与表达.md","module":"言语理解与表达","sourceModule":"言语理解与表达","sourceType":"片段阅读","questionPages":[8],"answerPages":[22,23]},"idx":44,"pid":"p56f583c407"},{"qid":"sy-c-20251025-046","no":46,"type":"数学运算","module":"数量关系","classification":{"version":"shiye-v1.20261011","group":"数学运算","tag":"经济利润","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"math.source-solution","evidence":"46 由题可得甲公司每年盈利100-50=50万元，则归还本金需要 310 =6.2年，6年不足以偿 50 还，则需要第7年才能还完。 故正确答案为D。","curriculum":{"file":"数量关系.pdf","pages":"1–24","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8],"answer":[23]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-046-题目-p08-289-347.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"4"},{"k":"B","t":"5"},{"k":"C","t":"6"},{"k":"D","t":"7"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-046-解析-p23-245-359.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025年1月甲公司收到借款310万元，甲公司预计每年总支出50万元，总收入100万元。若盈利全部用来归还本金，问第几年能还完？（    ）","options":[{"k":"A","t":"4"},{"k":"B","t":"5"},{"k":"C","t":"6"},{"k":"D","t":"7"}],"material":"","explanation":"46=6.2年，6年不足以偿50还，则需要第7年才能还完。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/数量分析.md","module":"数量关系","sourceModule":"数量分析","sourceType":"数学运算","questionPages":[8],"answerPages":[23]},"idx":45,"pid":"p56f583c407"},{"qid":"sy-c-20251025-047","no":47,"type":"数学运算","module":"数量关系","classification":{"version":"shiye-v1.20261011","group":"数学运算","tag":"工程问题","auxiliary":[],"methods":["赋值法"],"forms":[],"confidence":"中","needsReview":false,"rule":"math.source-solution","evidence":"48 600 600 600 赋值工程总量为600，则甲、乙、丙的效率分别为 12、 15, ：10。要让丙 50 40 60 参与修天数最少，则令甲尽可能多参与，即参与30天，则丙至少需要修 10 故正确答案为C。","curriculum":{"file":"数量关系.pdf","pages":"1–24","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8],"answer":[23]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-047-题目-p08-343-402.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"6"},{"k":"B","t":"7"},{"k":"C","t":"9"},{"k":"D","t":"12"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-047-解析-p23-355-483.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"某条道路的翻新工程需要在30天内完成，已知甲、乙、丙三个施工队单独修缮分别需要50天、40天、60天。已知甲全程参与，乙参与了10天，丙至少要参与修缮几天才能按期完工？（    ）（不足1天计1天）","options":[{"k":"A","t":"6"},{"k":"B","t":"7"},{"k":"C","t":"9"},{"k":"D","t":"12"}],"material":"","explanation":"47600600600赋值工程总量为600，则甲、乙、丙的效率分别为10。要让丙1215504060参与修天数最少，则令甲尽可能多参与，即参与30天，则丙至少需要修10\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/数量分析.md","module":"数量关系","sourceModule":"数量分析","sourceType":"数学运算","questionPages":[8],"answerPages":[23]},"idx":46,"pid":"p56f583c407"},{"qid":"sy-c-20251025-048","no":48,"type":"数学运算","module":"数量关系","classification":{"version":"shiye-v1.20261011","group":"数学运算","tag":"浓度问题","auxiliary":[],"methods":["方程法"],"forms":[],"confidence":"中","needsReview":false,"rule":"math.source-solution","evidence":"48 要使瓶中溶液的浓度为15%，设需要10%的甲溶液：毫升，40%的乙溶液y毫升。方法一： 溶质 方程法。根据公式：浓度= =15%，解得a：9=51 r+y 40%-15%_5 15%-10%=i° y 距离（15%-10%）：（40%-15%）=1:5 10% 15% 40","curriculum":null,"basis":"原题解析补充（本讲义未覆盖）","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8],"answer":[23]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-048-题目-p08-397-472.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"30"},{"k":"B","t":"40"},{"k":"C","t":"50"},{"k":"D","t":"60"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-048-解析-p23-479-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-048-解析-p24-51-74.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"现有瓶身容量均为500毫升的甲、乙两个瓶子，其中甲瓶有10%的酒精溶液200毫升，乙瓶有40%的酒精溶液100毫升。现将甲瓶溶液向乙瓶转移或将乙瓶溶液向甲瓶转移，则至少转移多少毫升溶液才能使某个瓶中溶液的浓度恰好为15%？（    ）","options":[{"k":"A","t":"30"},{"k":"B","t":"40"},{"k":"C","t":"50"},{"k":"D","t":"60"}],"material":"","explanation":"48要使瓶中溶液的浓度为15%，设需要10%的甲溶液：毫升，40%的乙溶液y毫升。方法一：溶质方程法。根据公式：浓度==15%，解得a：9=51r+y40%-15%_515%-10%=i°y距离（15%-10%）：（40%-15%）=1:510%15%40%量5:1假设将甲瓶溶液向乙瓶转移，即y=100毫升，则=500毫升。甲瓶一共只有200毫升酒精溶液，并且乙瓶的瓶身容量仅为500毫升，故无法实现，排除。\n\n假设将乙瓶溶液向甲瓶转移，即=200毫升，则y=40毫升。所以至少转移40毫升，可以使甲瓶溶液的浓度恰好为15%。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/数量分析.md","module":"数量关系","sourceModule":"数量分析","sourceType":"数学运算","questionPages":[8],"answerPages":[23]},"idx":47,"pid":"p56f583c407"},{"qid":"sy-c-20251025-049","no":49,"type":"数学运算","module":"数量关系","classification":{"version":"shiye-v1.20261011","group":"数学运算","tag":"几何问题","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"math.source-solution","evidence":"49 如图，过B作BEAD于点E，则ED=BC=100。根据题意可知AD=2×BC=200，则 AE=AD-ED=200-100=100。在直角三角形BEA中， BE=VAB2-AE2=V2602-1002=240，故DC=BE=240；根据公式： ×底×高，可得SAABQ=SA","curriculum":{"file":"数量关系.pdf","pages":"1–24","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8],"answer":[24]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-049-题目-p08-468-668.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"19000"},{"k":"B","t":"26000"},{"k":"C","t":"30000"},{"k":"D","t":"38000"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-049-解析-p24-69-386.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"某室外音乐会活动区域是如下图所示的直角梯形。主办方划分出无人机使用区域为三角形ABQ，已知AB为260米，BC与DQ相等为100米，且为AD的一半，问三角形ABQ的面积是多少平方米？（    ）","options":[{"k":"A","t":"19000"},{"k":"B","t":"26000"},{"k":"C","t":"30000"},{"k":"D","t":"38000"}],"material":"","explanation":"49如图，过B作BEAD于点E，则ED=BC=100。根据题意可知AD=2×BC=200，则AE=AD-ED=200-100=100。在直角三角形BEA中，BE=VAB2-AE2=V2602-1002=240，故DC=BE=240；根据公式：×底×高，可得SAABQ=SABCD-SAADQ-SBCQ11×(100+200)×240×100×200×(240-100)×100=19000。\n\n222AEBDQ\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/数量分析.md","module":"数量关系","sourceModule":"数量分析","sourceType":"数学运算","questionPages":[8],"answerPages":[24]},"idx":48,"pid":"p56f583c407"},{"qid":"sy-c-20251025-050","no":50,"type":"数学运算","module":"数量关系","classification":{"version":"shiye-v1.20261011","group":"数学运算","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"数量关系.pdf","pages":"1–24","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[8,9],"answer":[24]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-050-题目-p08-663-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-050-题目-p09-51-699.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-050-解析-p24-382-526.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"一个容器上下两部分本是相同的空心圆锥体（如左图所示），现将其上部分圆锥体截去若干高度。若从容器上方开口处匀速向内注入水（如右图所示），64分钟后下部分容器刚好灌满水，再过63分钟后上部分容器刚好灌满水。问容器上下两部分高度之比为多少？（    ）","options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"material":"","explanation":"50设截去的小圆锥体和大圆锥体的高分别为为h1、h。根据题意可知，上半部分容器与下半部分容器的体积之比为63:64，则截去的小圆锥与大圆锥的体积之比为1:64。根据几何等比部分高度之比为h-h1_3h4°\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/数量分析.md","module":"数量关系","sourceModule":"数量分析","sourceType":"数学运算","questionPages":[8,9],"answerPages":[24]},"idx":49,"pid":"p56f583c407"},{"qid":"sy-c-20251025-051","no":51,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"增长","tag":"增长量计算","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"51 根据题干及选项2023年较2022年同期增加减少.吨\"可判定本题为增长量计算问题 定位表格矿产量数据，可得矿产量2023年及2022年各季度数据。根据公式： 增长量=现期量－基期量，可得题干所求为(852.5+909.0+952.1+930.8) -（839.4+889.7","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[9],"answer":[24]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-051-题目-p09-695-737.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m51-材料-p09-401-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":51,"options":[{"k":"A","t":"增加了不到30吨"},{"k":"B","t":"增加了30吨以上"},{"k":"C","t":"减少了不到30吨"},{"k":"D","t":"减少了30吨以上"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-051-解析-p24-522-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年全球黄金供应量中矿产量较2022年同期（    ）。","options":[{"k":"A","t":"增加了不到30吨"},{"k":"B","t":"增加了30吨以上"},{"k":"C","t":"减少了不到30吨"},{"k":"D","t":"减少了30吨以上"}],"material":"（一）注：套保即套期保值，是指交易人在买进（或卖出）实际货物的同时，在期货交易所卖出（或买进）同等数量的期货交易合同作为保值。它是一种为避免或减少价格发生不利变动的损失，而以期货交易临时替代实物交易的一种行为。","explanation":"51根据题干及选项2023年较2022年同期增加减少.吨\"可判定本题为增长量计算问题定位表格矿产量数据，可得矿产量2023年及2022年各季度数据。根据公式：增长量=现期量－基期量，可得题干所求为(852.5+909.0+952.1+930.8)-（839.4+889.7+949.1+946.7）=19.5吨，即增加了不到30吨。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[9],"answerPages":[24]},"idx":50,"pid":"p56f583c407"},{"qid":"sy-c-20251025-052","no":52,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"倍数","tag":"现期倍数","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"52 根据题干\"2023年下半年，约是多少倍”，结合材料时间给出2023年，可判定本题为现期 倍数问题。定位表格可知，2023年三季度和四季度，全球黄金央行类需求量分别为353.2吨 353.2 +229.4 582.6 和229.4吨，科技类需求量分别为75.3吨和80.6吨。","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[9],"answer":[24,25]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-052-题目-p09-733-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-052-题目-p10-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m51-材料-p09-401-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":51,"options":[{"k":"A","t":"2.5"},{"k":"B","t":"3.1"},{"k":"C","t":"3.7"},{"k":"D","t":"4.3"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-052-解析-p24-663-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-052-解析-p25-51-200.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年下半年，全球黄金央行类需求量约是科技需求量的多少倍？（    ）","options":[{"k":"A","t":"2.5"},{"k":"B","t":"3.1"},{"k":"C","t":"3.7"},{"k":"D","t":"4.3"}],"material":"（一）注：套保即套期保值，是指交易人在买进（或卖出）实际货物的同时，在期货交易所卖出（或买进）同等数量的期货交易合同作为保值。它是一种为避免或减少价格发生不利变动的损失，而以期货交易临时替代实物交易的一种行为。","explanation":"52根据题干\"2023年下半年，约是多少倍”，结合材料时间给出2023年，可判定本题为现期倍数问题。定位表格可知，2023年三季度和四季度，全球黄金央行类需求量分别为353.2吨353.2 +229.4582.6和229.4吨，科技类需求量分别为75.3吨和80.6吨。则题干所求为~3.775.3 + 80.6155.9倍。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[9],"answerPages":[24,25]},"idx":51,"pid":"p56f583c407"},{"qid":"sy-c-20251025-053","no":53,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"资料分析","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[10],"answer":[25]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-053-题目-p10-87-130.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m51-材料-p09-401-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":51,"options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-053-解析-p25-196-434.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在黄金4类需求中，2022年下半年全球需求量大于上半年的有几类？（    ）","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"material":"（一）注：套保即套期保值，是指交易人在买进（或卖出）实际货物的同时，在期货交易所卖出（或买进）同等数量的期货交易合同作为保值。它是一种为避免或减少价格发生不利变动的损失，而以期货交易临时替代实物交易的一种行为。","explanation":"53定位表格可得2022年一季度~四季度4类黄金需求量。\n\n方法一：2022年下半年黄金4类需求量分别为：珠宝：582.6+601.9=1184.5吨；科技：77.3+72.1=149.4吨；投资：100.5+247.4=347.9吨；央行：458.8+382.1=840.9吨；2022年上半年黄金4类需求量分别为：珠宝：517.4+493.5=1010.9吨；科技：81.1+78.3=159.4吨；投资：555.9+209.3=765.2吨；央行：82.4+158.6=241吨。比较可得，2022年下半年全球需求量大于上半年的有珠宝、央行2类，对应B项。\n\n方法二：观察2022年每类黄金需求量中，四个季度的数据，发现：珠宝：三季度>一季度，四季度>二季度，故下半年需求量>上半年；科技：三季度<一季度，四季度<二季度，故下半年需求量<上半年；投资：四季度<一季度，三季度<二季度，故下半年需求量<上半年；央行：三季度>一季度，四季度>二季度，故下半年需求量>上半年。因此满足题意的有珠宝、央行2类。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[10],"answerPages":[25]},"idx":52,"pid":"p56f583c407"},{"qid":"sy-c-20251025-054","no":54,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"资料分析","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[10],"answer":[25]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-054-题目-p10-125-168.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m51-材料-p09-401-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":51,"options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-054-解析-p25-430-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年，全球黄金供应量高于需求量的季度有几个？（    ）","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"material":"（一）注：套保即套期保值，是指交易人在买进（或卖出）实际货物的同时，在期货交易所卖出（或买进）同等数量的期货交易合同作为保值。它是一种为避免或减少价格发生不利变动的损失，而以期货交易临时替代实物交易的一种行为。","explanation":"54定位统计表可知，2023年第一季度～第四季度全球黄金供应量和需求量。\n\n第一季度：全球黄金供应量为852.5+39.4+312=1203.9吨；需求量为512.3+70.8+273+287.7=1143.8吨;第二季度：全球黄金供应量为909－19.8+323.5=1212.7吨；需求量为493+71+257.5+167.1=988.6吨;第三季度：全球黄金供应量为952.1+19.7+288.9=1260.7吨；需求量为581.2+75.3+156.4+353.2=1166.1吨，第四季度：全球黄金供应量为930.8-22.3+312.9=1221.4吨；需求量为581.5+80.6+258.3+229.4=1149.8吨。\n\n比较可知，2023年第一季度~第四季度全球黄金供应量均高于需求量，共4个季度符合题意。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[10],"answerPages":[25]},"idx":53,"pid":"p56f583c407"},{"qid":"sy-c-20251025-055","no":55,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"增长","tag":"增长量比较","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"55 根据题干\"供应量环比增量的变化趋势”，可判定本题为增长量比较问题。 定位统计表可知，2022、2023年第一季度~第四季度全球黄金供应量情况。根据图形特征 可知：①第二季度环比增量>0：2022年第二季度回收量环比增量为285.2-295.9=-10.7吨 0：2023年第","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[10],"answer":[25,26]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-055-题目-p10-163-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-055-题目-p11-51-330.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m51-材料-p09-401-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":51,"options":[{"k":"A","t":"2022年，矿产量"},{"k":"B","t":"2022年，回收量"},{"k":"C","t":"2023年，矿产量"},{"k":"D","t":"2023年，回收量"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-055-解析-p25-663-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-055-解析-p26-51-231.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下柱状图反映了哪一年二季度至四季度，全球黄金哪一类供应量环比增量的变化趋势（横轴位置代表增量为0）？（    ）","options":[{"k":"A","t":"2022年，矿产量"},{"k":"B","t":"2022年，回收量"},{"k":"C","t":"2023年，矿产量"},{"k":"D","t":"2023年，回收量"}],"material":"（一）注：套保即套期保值，是指交易人在买进（或卖出）实际货物的同时，在期货交易所卖出（或买进）同等数量的期货交易合同作为保值。它是一种为避免或减少价格发生不利变动的损失，而以期货交易临时替代实物交易的一种行为。","explanation":"55根据题干\"供应量环比增量的变化趋势”，可判定本题为增长量比较问题。\n\n定位统计表可知，2022、2023年第一季度~第四季度全球黄金供应量情况。根据图形特征可知：①第二季度环比增量>0：2022年第二季度回收量环比增量为285.2-295.9=-10.7吨<0，排除B项；②第三季度环比增量>0：2023年第三季度回收量环比增量为288.9-323.5=-34.6吨<0，排除D项；③第三季度环比增量>第二季度环比增量：2023年第二季度矿产量环比增量为909-852.5=56.5吨，第三季度环比增量为952.1-909=43.1吨，第三季度环比增量<第二季度环比增量，排除C项。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[10],"answerPages":[25,26]},"idx":54,"pid":"p56f583c407"},{"qid":"sy-c-20251025-056","no":56,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"增长","tag":"增长量计算","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"56 根据题干\"2024年1一5月较2022年同期\"，结合选项为增加/减少+单位，可判定本题为间 隔增长量问题。定位统计图1可知，2023年1一5月、2024年1一5月全国限额以上企业化妆 品累计零售总额分别为16.2百亿元、17.6百亿元，2024年1一5月、2023年1一5月","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[11],"answer":[26]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-056-题目-p11-326-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p10-297-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p11-51-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":56,"options":[{"k":"A","t":"增加了不到200亿元"},{"k":"B","t":"增加了200亿元以上"},{"k":"C","t":"减少了不到200亿元"},{"k":"D","t":"减少了200亿元以上"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-056-解析-p26-226-496.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2024年1—5月全国限额以上企业化妆品累计零售总额较2022年同期（    ）。","options":[{"k":"A","t":"增加了不到200亿元"},{"k":"B","t":"增加了200亿元以上"},{"k":"C","t":"减少了不到200亿元"},{"k":"D","t":"减少了200亿元以上"}],"material":"（二）","explanation":"56根据题干\"2024年1一5月较2022年同期\"，结合选项为增加/减少+单位，可判定本题为间隔增长量问题。定位统计图1可知，2023年1一5月、2024年1一5月全国限额以上企业化妆品累计零售总额分别为16.2百亿元、17.6百亿元，2024年1一5月、2023年1一5月全国限额以上企业化妆品累计零售总额同比增长率分别为8.9%、9.9%。\n\n现期量方法一：根据公式：基期量：可得2022年1一5月全国限额以上企业化妆品累计零1+r售总额为，16.216.2~14.7百亿元。根据公式：增长量=现期量－基期量，可得题干所1+9.9%~1.1求为17.6-14.7=2.9百亿元=290亿元，即增加了200亿元以上。\n\n方法二：根据公式：7间隔=T1+T2+T1×r2，可得2024年1一5月全国限额以上企业化妆品累计零售总额较2022年同期增长了8.9%+9.9%+8.9%×9.9%~19.7%；根据公式：17.6现期量17.6117.6增长量：~2.93百亿元1+#1+r6=293亿元，即增长加了200亿元以上。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[11],"answerPages":[26]},"idx":55,"pid":"p56f583c407"},{"qid":"sy-c-20251025-057","no":57,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"增长","tag":"混合增长率","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"57 根据题干\"2023年3~12月，……超过1月至当月累计增速的月份有几个？”，结合材料给出 1至各月累计销售额的同比增速，可判定本题为混合增长率问题。根据口决“混合后居中“可 得：若当月增速>1月至当月累计增速，则1月至当月累计增速>1至上月累计增速。定位统 计图1，可知满足","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[11],"answer":[26]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-057-题目-p11-364-423.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p10-297-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p11-51-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":56,"options":[{"k":"A","t":"3"},{"k":"B","t":"4"},{"k":"C","t":"5"},{"k":"D","t":"6"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-057-解析-p26-492-636.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年3～12月，全国限额以上企业化妆品当月零售总额同比增速超过1月至当月累计零售总额同比增速的月份有几个？（    ）","options":[{"k":"A","t":"3"},{"k":"B","t":"4"},{"k":"C","t":"5"},{"k":"D","t":"6"}],"material":"（二）","explanation":"57根据题干\"2023年3~12月，……超过1月至当月累计增速的月份有几个？”，结合材料给出1至各月累计销售额的同比增速，可判定本题为混合增长率问题。根据口决“混合后居中“可得：若当月增速>1月至当月累计增速，则1月至当月累计增速>1至上月累计增速。定位统计图1，可知满足的月份有3月、4月、8月，共计3个。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[11],"answerPages":[26]},"idx":56,"pid":"p56f583c407"},{"qid":"sy-c-20251025-058","no":58,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"增长","tag":"增长量比较","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"58 根据题干及选项\"2024年3~5月，同比增量增加/减少\"，可判定本题为增长量比较问题。 定位图2可知，2024年3~5月全国限额以上企业商品当月零售总额分别为419－275=144百 亿元、542－419=123百亿元、680－542=138百亿元；2023年3~5月各月分","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[11],"answer":[26,27]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-058-题目-p11-418-461.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p10-297-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p11-51-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":56,"options":[{"k":"A","t":"逐月递增"},{"k":"B","t":"逐月递减"},{"k":"C","t":"先增后减"},{"k":"D","t":"先减后增"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-058-解析-p26-631-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-058-解析-p27-51-216.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2024年3~5月，全国限额以上企业商品当月零售总额同比增量（    ）。","options":[{"k":"A","t":"逐月递增"},{"k":"B","t":"逐月递减"},{"k":"C","t":"先增后减"},{"k":"D","t":"先减后增"}],"material":"（二）","explanation":"58根据题干及选项\"2024年3~5月，同比增量增加/减少\"，可判定本题为增长量比较问题。\n\n定位图2可知，2024年3~5月全国限额以上企业商品当月零售总额分别为419－275=144百亿元、542－419=123百亿元、680－542=138百亿元；2023年3~5月各月分别为406－265=141百亿元、515-406=109百亿元、636-515=121百亿元。根据公式：增长量=现期量－基期量，可得2024年3~5月各月的同比增量分别为144－141=3百亿元、123－109=14百亿元、138-121=17百亿元，则增量逐月递增。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[11],"answerPages":[26,27]},"idx":57,"pid":"p56f583c407"},{"qid":"sy-c-20251025-059","no":59,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"比重","tag":"现期比重","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"data.explicit-or-request","evidence":"59 根据题干\"将2023年10一12月按照占比重由高到低排序，以下正确的是”，结合材料给出 2023年相关数据，可判定本题为现期比重比较问题。定位图1可知2023年全国限额以上企 业化妆品累计零售总额，定位图2可知全国限额以上企业商品累计零售总额。则2023年10 12月全国限","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[11],"answer":[27]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-059-题目-p11-456-531.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p10-297-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p11-51-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":56,"options":[{"k":"A","t":"10月、11月、12月"},{"k":"B","t":"11月、10月、12月"},{"k":"C","t":"11月、12月、10月"},{"k":"D","t":"12月、11月、10月"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-059-解析-p27-211-496.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"将2023年10—12月按全国限额以上企业化妆品当月零售总额占商品当月零售总额的比重由高到低排序，以下正确的是（    ）。","options":[{"k":"A","t":"10月、11月、12月"},{"k":"B","t":"11月、10月、12月"},{"k":"C","t":"11月、12月、10月"},{"k":"D","t":"12月、11月、10月"}],"material":"（二）","explanation":"59根据题干\"将2023年10一12月按照占比重由高到低排序，以下正确的是”，结合材料给出2023年相关数据，可判定本题为现期比重比较问题。定位图1可知2023年全国限额以上企业化妆品累计零售总额，定位图2可知全国限额以上企业商品累计零售总额。则2023年10一12月全国限额以上企业化妆品当月零售总额为：10月：32.9－29.7=3.2百亿元；11月：38.4-32.9=5.5百亿元；12月：41.4-38.4=3百亿元；2023年10—12月全国限额以上企业商品当月零售总额为：10月：1338-1197=141百亿元；11月：1494－1338=156百亿元；\n\n12月：1652-1494=158百亿元。\n\n则2023年10一12月所求比重分别为：3.210月：~2.3%;1415.511月：312月：~ 1.9%。\n\n158则2023年10一12月按全国限额以上企业化妆品当月零售总额占商品当月零售总额的比重由高到低排序为11月、10月、12月。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[11],"answerPages":[27]},"idx":58,"pid":"p56f583c407"},{"qid":"sy-c-20251025-060","no":60,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"资料分析","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[11,12],"answer":[27]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-060-题目-p11-527-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-060-题目-p12-51-240.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p10-297-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/C-2025-10-25-m56-材料-p11-51-326.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":56,"options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-060-解析-p27-492-730.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下折线图中，最能准确反映2023年二季度至四季度全国限额以上企业化妆品当期零售总额环比增速的是（    ）。","options":[{"k":"A","t":"- **B**."},{"k":"B","t":"B"},{"k":"C","t":"- **D**."},{"k":"D","t":"D"}],"material":"（二）","explanation":"60根据题干\"以下折线图中，最能准确反映2023年二季度至四季度环比增速的是”，可判定本题为一般增长率比较问题。定位统计图1可知：2023年1一3月、1一6月、1—9月、1一12月全国限额以上企业化妆品累计零售总额分别为10.4百亿元、20.7百亿元、29.7百亿元、41.4百亿元，则2023年二季度至四季度全国限额以上企业化妆品当期零售总额为：二季度：20.7-10.4=10.3百亿元；三季度：29.7-20.7=9百亿元；四季度：41.4-29.7=11.7百亿元。根据公式：增长率基期量10.3-10.40.1化妆品当期零售总额的环比增速分别为：T二季度=~-1%,10.410.49 -10.3-1.311.7-92.7T三季度=10.3~-13%，T四季度=-一30%，T三季度为最小值，对应为-10.399图中最低点，T四季度为最大值，对应为图中最高点，对应D项。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"数量分析","sourceType":"资料分析","questionPages":[11,12],"answerPages":[27]},"idx":59,"pid":"p56f583c407"},{"qid":"sy-c-20251025-061","no":61,"type":"图形推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"图形推理","tag":"数量规律·面数量","auxiliary":["数量规律·面数量"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"graphic.solution","evidence":"数面","curriculum":{"file":"判断推理.pdf","pages":"1–33","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[12],"answer":[27,28]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-061-题目-p12-236-446.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-061-解析-p27-725-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-061-解析-p28-51-223.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（    ）。","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"","explanation":"61元素组成不同，且无明显属性规律，优先考虑数量规律。观察发现，题干图形被分割且封闭面明显，考虑数面。第一组图形面数量均为4，第二组前两幅图形面数量均为5，但无法选出唯一答案，考虑面的细化。继续观察发现，第一组图形均有2 个相同面，第二组前两幅图均有3 个相同面，故？处应选择有3 个相同面的图形，只有A 项符合。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"图形推理","questionPages":[12],"answerPages":[27,28]},"idx":60,"pid":"p56f583c407"},{"qid":"sy-c-20251025-062","no":62,"type":"图形推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"图形推理","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"判断推理.pdf","pages":"1–33","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[12],"answer":[28]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-062-题目-p12-441-658.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-062-解析-p28-219-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性（    ）。","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"","explanation":"62元素组成不同，且无明显属性规律和数量规律，考虑特殊规律。观察发现，题干图形均由多个图形相交在一起，考虑图形间关系。圆内部的两个全直多边形依次为线连接和点连接交替出现，故？处应选择圆内部的两个全直多边形为点连接的图形，只有C 项符合。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"图形推理","questionPages":[12],"answerPages":[28]},"idx":61,"pid":"p56f583c407"},{"qid":"sy-c-20251025-063","no":63,"type":"图形推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"图形推理","tag":"空间类·六面体","auxiliary":["空间类·六面体"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"graphic.spatial-request","evidence":"正方体纸盒的外表面展开","curriculum":{"file":"判断推理.pdf","pages":"1–33","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[12,13],"answer":[28]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-063-题目-p12-654-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-063-题目-p13-51-110.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-063-解析-p28-363-570.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下为4个正方体纸盒的外表面展开图，问哪一个折叠成的纸盒和其他3个不一样？（    ）","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"","explanation":"63\n\n本题为空间重构题，如下图所示，A、C、D项中，“直角梯形\"面中梯形的短直角边与\"灰色半圆\"面不相邻，但B项中，“直角梯形“面中梯形的短直角边与\"灰色半圆“面相邻，因此B项折成的纸盒与其他三个不同。\n\nMDAABD\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"图形推理","questionPages":[12,13],"answerPages":[28]},"idx":62,"pid":"p56f583c407"},{"qid":"sy-c-20251025-064","no":64,"type":"图形推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"图形推理","tag":"空间类·三视图","auxiliary":["空间类·三视图"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"graphic.spatial-request","evidence":"俯视图","curriculum":{"file":"判断推理.pdf","pages":"1–33","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[13],"answer":[28,29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-064-题目-p13-106-371.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-064-解析-p28-566-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-064-解析-p29-51-402.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"下列选项中，作为给定立体图形的俯视图和主视图均正确的是（    ）。","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"material":"","explanation":"64\n\n本题考查三视图。\n\n俯视图是立体图从上向下观察，如下图所示，立体图形红色线条标注部分从俯视图中无法观察到，排除A、C项。\n\n主视图是立体图从前向后观察，如下图所示，立体图形绿色线条标注部分从主视图中可以观察到，为三角形轮廓，排除B项。\n\nABD\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"图形推理","questionPages":[13],"answerPages":[28,29]},"idx":63,"pid":"p56f583c407"},{"qid":"sy-c-20251025-065","no":65,"type":"图形推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"图形推理","tag":"空间类·其他立体","auxiliary":["空间类·其他立体"],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"graphic.spatial-request","evidence":"立体图形","curriculum":{"file":"判断推理.pdf","pages":"1–33","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[13],"answer":[29]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-065-题目-p13-366-650.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"仅②"},{"k":"B","t":"仅③"},{"k":"C","t":"仅①或②"},{"k":"D","t":"仅②或③"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-065-解析-p29-398-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-065-解析-p30-51-72.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"左图为14个白色正方体和3个灰色正方体组成的立体图形，其可以由Ⅰ、Ⅱ和Ⅲ三个多面体组合而成，问哪项可以填入问号处？（    ）","options":[{"k":"A","t":"仅②"},{"k":"B","t":"仅③"},{"k":"C","t":"仅①或②"},{"k":"D","t":"仅②或③"}],"material":"","explanation":"65\n\n本题考查立体拼合。\n\n将图工、工和②项按照下图方式进行拼合，可得出左图所示立方体：图I将图I、立和③项按照下图方式进行拼合，可得出左图所示立方体：图1\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"图形推理","questionPages":[13],"answerPages":[29]},"idx":64,"pid":"p56f583c407"},{"qid":"sy-c-20251025-066","no":66,"type":"定义判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"定义判断","tag":"单定义","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"definition.structure","evidence":"题面有 1 个明确定义标志","curriculum":{"file":"判断推理.pdf","pages":"44–58","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[13],"answer":[30]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-066-题目-p13-645-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-066-题目-p14-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"某计算机程序仅按照预设的简单算法，就生成了一种非常复杂的分形几何图形"},{"k":"B","t":"防汛指挥部统筹调派千名官兵在指定位置堆叠沙包，构筑防洪堤坝抵御洪水侵袭"},{"k":"C","t":"乐队指挥依据乐谱协调各位乐手的演奏，献给听众一场和谐悦耳、荡气回肠的交响乐"},{"k":"D","t":"每只鸟遵循“保持间距、对齐方向、靠近群体”三原则，鸟群整体呈现复杂旋涡状迁飞"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-066-解析-p30-68-575.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"涌现是指在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象，其特征是整体行为无法通过个体行为直接推导。\n\n根据上述定义，下列属于涌现的是（    ）。","options":[{"k":"A","t":"某计算机程序仅按照预设的简单算法，就生成了一种非常复杂的分形几何图形"},{"k":"B","t":"防汛指挥部统筹调派千名官兵在指定位置堆叠沙包，构筑防洪堤坝抵御洪水侵袭"},{"k":"C","t":"乐队指挥依据乐谱协调各位乐手的演奏，献给听众一场和谐悦耳、荡气回肠的交响乐"},{"k":"D","t":"每只鸟遵循“保持间距、对齐方向、靠近群体”三原则，鸟群整体呈现复杂旋涡状迁飞"}],"material":"","explanation":"66\n\n第一步：找出定义关键词。\n\n“在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象”、“整体行为无法通过个体行为直接推导”。\n\n第二步：逐一分析选项。\n\nA 项：计算机程序是单一执行主体，不符合“在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象”，且生成图形是对预设算法的直接执行，整体行为（分形图形）可通过个体行为（算法步骤）直接推导，不符合“整体行为无法通过个体行为直接推导”，不符合定义，排除；\n\nB 项：官兵的行为受到防汛指挥部的统一外部指挥，并非个体自发遵循简单规则，不符合“在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象”，不符合定义，排除；\n\nC 项：乐手的演奏节奏、音准等受到乐队指挥的实时协调，并非个体自发遵循简单规则，不符合“在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象”，不符合定义，排除；\n\nD 项：鸟群是由多只鸟组成的复杂系统，每只鸟仅遵循保持间距、对齐方向、靠近群体三个简单规则，无外部统一指挥，自发与其他鸟相互作用，符合“在复杂系统中，个体遵循简单规则相互作用，自发形成宏观层面具有新特性或功能的现象”，且通过单只鸟的规则无法预判鸟群整体呈现旋涡状，符合“整体行为无法通过个体行为直接推导”，符合定义，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"定义判断","questionPages":[13],"answerPages":[30]},"idx":65,"pid":"p56f583c407"},{"qid":"sy-c-20251025-067","no":67,"type":"定义判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"定义判断","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"判断推理.pdf","pages":"44–58","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[30,31]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-067-题目-p14-87-258.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"企业间签订的购销合同——（1）"},{"k":"B","t":"企业广告宣传方案——（3）"},{"k":"C","t":"企业员工培训办法——（4）"},{"k":"D","t":"企业的产品技术鉴定书——（5）"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-067-解析-p30-571-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-067-解析-p31-51-376.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"经济文书是经济管理部门或企事业单位制作和使用的与经济活动相关的具有实用价值和固定格式的文书。按性质分为：（1）经营类文书是企业生产经营和财务活动中处理经济业务时使用的文书；\n\n（2）管理类文书是企业在制订规章制度时使用的文书；\n\n（3）信息交流类文书是用于传播或反馈经济信息，报道经济活动时使用的文书；\n\n（4）科技类文书是企业在科学技术和经济规律研究时所使用的文书；\n\n（5）经济诉讼类文书是企业之间或企业和职工之间在经济活动中发生民事或刑事纠纷时使用的文书。\n\n根据上述定义，下列文书与其性质对应正确的是（    ）。","options":[{"k":"A","t":"企业间签订的购销合同——（1）"},{"k":"B","t":"企业广告宣传方案——（3）"},{"k":"C","t":"企业员工培训办法——（4）"},{"k":"D","t":"企业的产品技术鉴定书——（5）"}],"material":"","explanation":"67\n\n第一步：找出定义关键词。\n\n（1）经营类文书：“企业生产经营和财务活动中处理经济业务时使用的文书”；\n\n（2）管理类文书：“企业在制订规章制度时使用的文书”；\n\n（3）信息交流类文书：“用于传播或反馈经济信息，报道经济活动时使用的文书”；\n\n（4）科技类文书：“企业在科学技术和经济规律研究时所使用的文书”；\n\n（5）经济诉讼类文书：“企业之间或企业和职工之间在经济活动中发生民事或刑事纠纷时使用的文书”。\n\n第二步：逐一分析选项。\n\nA 项：企业间签订的购销合同，是企业在生产经营中处理经济业务（商品买卖）时使用的文书，符合“企业生产经营和财务活动中处理经济业务时使用的文书”，对应（1），对应正确，当选；\n\nB 项：企业广告宣传方案，是企业用于推广产品或者宣传品牌而制作的文书，是营销策略，属于企业生产经营中处理经济业务（宣传推广）时使用的文书，符合“企业生产经营和财务活动中处理经济业务时使用的文书”，对应（1）而不是（3），对应错误，排除；\n\nC 项：企业员工培训办法，是企业为了规范员工培训活动制定的规章制度，符合“企业在制订规章制度时使用的文书”，对应（2）而不是（4），对应错误，排除；\n\nD 项：企业的产品技术鉴定书，是用于评估企业产品技术的文书，符合“企业在科学技术和经济规律研究时所使用的文书”，对应（4）而不是（5），对应错误，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"定义判断","questionPages":[14],"answerPages":[30,31]},"idx":66,"pid":"p56f583c407"},{"qid":"sy-c-20251025-068","no":68,"type":"定义判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"定义判断","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"判断推理.pdf","pages":"44–58","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[31,32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-068-题目-p14-253-409.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"某些昆虫的翅膀长度在一代代的繁衍中逐渐发生微小的改变，从短翅膀逐渐演变为长翅膀"},{"k":"B","t":"对生物生存有利的变异在生存斗争中保存了下来，经过生存斗争，变异得到逐渐积累，新物种得以形成"},{"k":"C","t":"化石研究发现，在进化史上，相当长的时间内新种化石很少，有时大量的新种化石集中出现在较短的地质年代"},{"k":"D","t":"新种是由其祖先种转变成的，这种转变是缓慢的、持续的过程，且发生于祖先种地理分布的整个范围或大部分地区"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-068-解析-p31-371-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-068-解析-p32-51-184.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"渐变论是关于生物进化的一种学说。此学说认为生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果。\n\n根据上述定义，下列不符合渐变论观点的是（    ）。","options":[{"k":"A","t":"某些昆虫的翅膀长度在一代代的繁衍中逐渐发生微小的改变，从短翅膀逐渐演变为长翅膀"},{"k":"B","t":"对生物生存有利的变异在生存斗争中保存了下来，经过生存斗争，变异得到逐渐积累，新物种得以形成"},{"k":"C","t":"化石研究发现，在进化史上，相当长的时间内新种化石很少，有时大量的新种化石集中出现在较短的地质年代"},{"k":"D","t":"新种是由其祖先种转变成的，这种转变是缓慢的、持续的过程，且发生于祖先种地理分布的整个范围或大部分地区"}],"material":"","explanation":"68\n\n第一步：找出定义关键词。\n\n“生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果”。\n\n第二步：逐一分析选项。\n\nA 项：某些昆虫的翅膀长度在一代代的繁衍中逐渐发生微小的改变从短翅膀变为长翅膀，体现了翅膀从短到长的进化是随着漫长的时间由微小变化逐渐积累产生的，是长期缓慢的渐变过程，符合“生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果”，符合定义，排除；\n\nB 项：对生物生存有利的变异经过生存斗争得到保存并逐渐积累，最终形成新物种，体现了生物经过变异最终进化形成新物种是逐渐积累产生的，是长期缓慢的渐变过程，符合“生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果”，符合定义，排除；\n\nC 项：新种化石在较短的地质年代中集中出现，体现了生物进化可能存在某种快速的变化，而不是一个长期缓慢的渐变过程，不符合“生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果”，不符合定义，当选；\n\nD 项：新种由祖先种经过缓慢、持续的过程转变形成，体现了生物进化成新种是逐渐积累产生的，是长期缓慢的渐变过程，符合“生物进化是一个长期而缓慢的渐变过程，漫长的时间足以使微小的渐变逐渐积累，产生惊人的效果”，符合定义，排除。\n\n本题为选非题，故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"定义判断","questionPages":[14],"answerPages":[31,32]},"idx":67,"pid":"p56f583c407"},{"qid":"sy-c-20251025-069","no":69,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[32]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-069-题目-p14-404-511.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"研究气溶胶粒子吸附水分子成为凝结核或冰核的机制，解析云滴的形成过程"},{"k":"B","t":"研究不同云系的热力-动力耦合机制，如地形抬升引发山地波状云的发展规律"},{"k":"C","t":"研究用气象雷达探测大气的原理和方法，及其在天气预报、云和降水中的物理应用"},{"k":"D","t":"研究云雾粒子对红外辐射的吸收和发射，以及云雾粒子对可见光的散射和反射作用"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-069-解析-p32-179-665.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"云物理学是研究大气中云的发生、发展、结构及其产生降水（如雨、雪等）所遵循的物理和动力过程的学科。\n\n下列不属于云物理学研究范畴的是（    ）。","options":[{"k":"A","t":"研究气溶胶粒子吸附水分子成为凝结核或冰核的机制，解析云滴的形成过程"},{"k":"B","t":"研究不同云系的热力-动力耦合机制，如地形抬升引发山地波状云的发展规律"},{"k":"C","t":"研究用气象雷达探测大气的原理和方法，及其在天气预报、云和降水中的物理应用"},{"k":"D","t":"研究云雾粒子对红外辐射的吸收和发射，以及云雾粒子对可见光的散射和反射作用"}],"material":"","explanation":"69\n\n第一步：找出定义关键词。\n\n“研究大气中云的发生、发展、结构”、“其产生降水（如雨、雪等）所遵循的物理和动力过程”。\n\n第二步：逐一分析选项。\n\nA 项：研究气溶胶粒子吸附水分子成为凝结核或冰核的机制，解析云滴的形成过程，云滴增大为雨滴、雪花或其它降水物，从而形成降水，体现了研究云的发生、其产生降水（如雨、雪等）的过程，符合“研究大气中云的发生、发展、结构”，符合定义，排除；\n\nB 项：研究不同云系的热力-动力耦合机制，如地形抬升引发山地波状云的发展规律，体现了研究云的发展，并且波状云与云的结构有关，符合“研究大气中云的发生、发展、结构”，符合定义，排除；\n\nC 项：研究用气象雷达探测大气的原理和方法，及其在天气预报、云和降水中的物理应用，体现了研究气象雷达在云和降水中的应用，并未对云进行研究，不符合“研究大气中云的发生、发展、结构”、“其产生降水（如雨、雪等）所遵循的物理和动力过程”，不符合定义，当选；\n\nD 项：研究云雾粒子对红外辐射的吸收和发射，以及云雾粒子对可见光的散射和反射作用，云雾粒子是云的基本构成单元，研究其散射和反射作用就是在研究云的微观结构，符合“研究大气中云的发生、发展、结构”，符合定义，排除。\n\n本题为选非题，故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[14],"answerPages":[32]},"idx":68,"pid":"p56f583c407"},{"qid":"sy-c-20251025-070","no":70,"type":"定义判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"定义判断","tag":"多定义","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"definition.structure","evidence":"题面有 3 个明确定义标志","curriculum":{"file":"判断推理.pdf","pages":"44–58","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[32,33]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-070-题目-p14-506-597.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"密殖指数大于零，但不会超过百分之百"},{"k":"B","t":"密殖指数反映了人均已开垦种植的耕地面积"},{"k":"C","t":"已开垦种植的耕地面积越大，则密殖指数越小"},{"k":"D","t":"垦殖指数越高说明该地区的耕地开发利用越合理"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-070-解析-p32-660-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-070-解析-p33-51-434.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"垦殖指数指的是一国或一地区已开垦种植的耕地面积占土地总面积的百分比；人口密度指的是单位土地面积上的人口数量；密殖指数指的是垦殖指数和人口密度之比。\n\n根据上述定义，下列说法正确的是（    ）。","options":[{"k":"A","t":"密殖指数大于零，但不会超过百分之百"},{"k":"B","t":"密殖指数反映了人均已开垦种植的耕地面积"},{"k":"C","t":"已开垦种植的耕地面积越大，则密殖指数越小"},{"k":"D","t":"垦殖指数越高说明该地区的耕地开发利用越合理"}],"material":"","explanation":"70\n\n第一步：找出定义关键词。\n\n垦殖指数：”一国或一地区已开垦种植的耕地面积占土地总面积的百分比”；\n\n人口密度：“单位士地面积上的人口数量”；\n\n密殖指数：“垦殖指数和人口密度之比\"。\n\n第二步：逐一分析选项。\n\nA项：密殖指数是垦殖指数和人口密度之比，其中垦殖指数一国或一地区已开垦种植的耕地面积土地总面积土地总面积指数是百分比（0一100%），如果某一国或某一地区人口密度极小，此时密殖指数可能大于100%，故选项说法错误，排除；\n\nB项：密殖指数是垦殖指数和人口密度之比，所以密殖指数一国或一地区已开垦种植的耕地面积×100%，所以密殖指数可以反映人均已开垦种植的耕一国或一地区人口总数地面积，故选项说法正确，当选；\n\nC项：密殖指数是垦殖指数和人口密度之比，所以密殖指数一国或一地区已开垦种植的耕地面积×100%，因此密殖指数不仅与已开垦种植的耕地面积一国或一地区人口总数有关，还与人口数量有关，无法得出已开垦种植的耕地面积越大，则密殖指数越小，故选项说法错误，排除；\n\n土地总面积积占土地总面积的比例，与耕地开发利用是否合理无关，故选项说法错误，排除。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"定义判断","questionPages":[14],"answerPages":[32,33]},"idx":69,"pid":"p56f583c407"},{"qid":"sy-c-20251025-071","no":71,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[33]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-071-题目-p14-593-636.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"等比：等差"},{"k":"B","t":"分数：小数"},{"k":"C","t":"单价：利润"},{"k":"D","t":"税额：税率"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-071-解析-p33-430-699.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"增量：增速","options":[{"k":"A","t":"等比：等差"},{"k":"B","t":"分数：小数"},{"k":"C","t":"单价：利润"},{"k":"D","t":"税额：税率"}],"material":"","explanation":"71\n\n第一步：判断题干词语间逻辑关系。\n\n增量=增速×基期，当基期值固定时，增量和增速成正比关系，二者为正比的对应关系。\n\n第二步：判断选项词语间逻辑关系。\n\nA项：等比数列是指从第二项起，每一项与它的前一项的比值等于同一个常数的数列；等差数列是相邻两项之差为常数的数列。二者是数列的两种不同类型，为并列关系，与题干逻辑关系不一致，排除；\n\nB项：分数是数学中表示整体等分后部分量的数值，形式为a/b（a，b为整数且b≠0）；小数是数学中用于表示整数无法完整度量的数值的记数方式，所有的分数都可以用小数表示，二者不为正比的对应关系，与题干逻辑关系不一致，排除；\n\nC项：利润=单价×销量－成本，当销量固定时，利润不仅与单价有关，还与成本有关，单价和利润不是正比的对应关系，与题干逻辑关系不一致，排除；\n\nD项：税额－税率×税基，当税基值固定时，税额和税率成正比关系，二者为正比的对应关系，与题干逻辑关系一致，当选。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[14],"answerPages":[33]},"idx":70,"pid":"p56f583c407"},{"qid":"sy-c-20251025-072","no":72,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[33,34]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-072-题目-p14-631-674.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"坡度：下滑速度"},{"k":"B","t":"身高：进球概率"},{"k":"C","t":"利率：金融市场"},{"k":"D","t":"税收：企业经营"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-072-解析-p33-694-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-072-解析-p34-51-391.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"浓度：反应速率","options":[{"k":"A","t":"坡度：下滑速度"},{"k":"B","t":"身高：进球概率"},{"k":"C","t":"利率：金融市场"},{"k":"D","t":"税收：企业经营"}],"material":"","explanation":"72\n\n第一步：判断题干词语间逻辑关系。\n\n浓度是影响反应速率的关键因素，浓度越高，反应速率越快，二者为正相关的对应关系。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：坡度是影响下滑速度的关键因素，坡度越大，下滑速度通常越快（在无摩擦或恒定摩擦条件下），二者为正相关的对应关系，与题干逻辑关系一致，当选；\n\nB 项：身高有可能会影响进球概率，但并不是身高越高，进球概率就一定越高，二者不为正相关的对应关系，与题干逻辑关系不一致，排除；\n\nC 项：利率是影响金融市场的一个因素，但金融市场是一个复杂系统，受经济、政治、心理等多重因素影响，并不是利率越高，金融市场就会受到相关的正向影响，二者不为正相关的对应关系，与题干逻辑关系不一致，排除；\n\nD 项：税收会影响企业的经营，但企业经营是一个综合过程，涉及生产、销售、管理等多方面，并不是税收越高，企业经营就会受到相关的正向影响，二者不为正相关的对应关系，与题干逻辑关系不一致，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[14],"answerPages":[33,34]},"idx":71,"pid":"p56f583c407"},{"qid":"sy-c-20251025-073","no":73,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[34]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-073-题目-p14-669-712.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"石墨：绝缘性"},{"k":"B","t":"氨水：挥发性"},{"k":"C","t":"铁锈：氧化性"},{"k":"D","t":"铜绿：还原性"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-073-解析-p34-387-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-073-解析-p35-51-88.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"活性炭：吸附性","options":[{"k":"A","t":"石墨：绝缘性"},{"k":"B","t":"氨水：挥发性"},{"k":"C","t":"铁锈：氧化性"},{"k":"D","t":"铜绿：还原性"}],"material":"","explanation":"73\n\n第一步：判断题干词语间逻辑关系。\n\n活性炭具有吸附性，二者为属性对应关系，且吸附性是活性炭自身就具有的属性。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：石墨是一种导体，不是绝缘体，因此石墨不具有绝缘性，二者为反向属性关系，与题干逻辑关系不一致，排除；\n\nB 项：氨水为气体氨的水溶液，氨具有挥发性，因此氨水也容易蒸发，具有挥发性，二者为属性对应关系，且挥发性是氨水自身就具有的属性，与题干逻辑关系一致，当选；\n\nC 项：铁锈是铁被氧化的产物，虽然铁锈也具有一定的氧化性，但铁锈的氧化性通常需在特定条件下（如高温或酸性环境）才能体现，其自身不具有氧化性，与题干逻辑关系不一致，排除；\n\nD 项：铜绿是铜被腐蚀后的氧化物，虽然铜绿也有一定的还原性，但铜绿的还原性通常需要特定条件（如高温、酸碱环境）才能触发，其自身不具有还原性，与题干逻辑关系不一致，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[14],"answerPages":[34]},"idx":72,"pid":"p56f583c407"},{"qid":"sy-c-20251025-074","no":74,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系","功能对应"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"功能的对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14],"answer":[35]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-074-题目-p14-708-750.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"银粉：导电填料"},{"k":"B","t":"射频：电磁频率"},{"k":"C","t":"溶剂：相似相溶"},{"k":"D","t":"电池：存储电荷"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-074-解析-p35-83-311.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"过滤器：分离杂质","options":[{"k":"A","t":"银粉：导电填料"},{"k":"B","t":"射频：电磁频率"},{"k":"C","t":"溶剂：相似相溶"},{"k":"D","t":"电池：存储电荷"}],"material":"","explanation":"74\n\n第一步：判断题干词语间逻辑关系。\n\n过滤器有分离杂质的功能，二者为功能的对应关系。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：银粉是一种导电填料，二者为种属关系，与题干逻辑关系不一致，排除；\n\nB 项：射频是可以辐射到空间的电磁频率，二者为种属关系，与题干逻辑关系不一致，排除；\n\nC 项：溶剂有相似相溶的特点，二者为属性的对应关系，与题干逻辑关系不一致，排除；\n\nD 项：电池有储存电荷的功能，二者为功能的对应关系，与题干逻辑关系一致，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[14],"answerPages":[35]},"idx":73,"pid":"p56f583c407"},{"qid":"sy-c-20251025-075","no":75,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系","材料对应","工艺对应"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[14,15],"answer":[35]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-075-题目-p14-746-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-075-题目-p15-51-110.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"土：烧结：陶瓷"},{"k":"B","t":"铁：加热：铁水"},{"k":"C","t":"油脂：皂化：甘油"},{"k":"D","t":"淀粉：水解：葡萄糖"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-075-解析-p35-307-630.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"水：凝华：冰花","options":[{"k":"A","t":"土：烧结：陶瓷"},{"k":"B","t":"铁：加热：铁水"},{"k":"C","t":"油脂：皂化：甘油"},{"k":"D","t":"淀粉：水解：葡萄糖"}],"material":"","explanation":"75\n\n第一步：判断题干词语间逻辑关系。\n\n水经过凝华可以制成冰花，二者为原材料、工艺与成品的对应关系，且凝华为物理变化。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：土经过烧结可以制成陶瓷，二者为原材料、工艺与成品的对应关系，但烧结为化学变化，与题干逻辑关系不一致，排除；\n\nB 项：铁经过加热可以制成铁水，二者为原材料、工艺与成品的对应关系，且铁加热成为铁水的过程为物理变化，与题干逻辑关系一致，当选；\n\nC 项：油脂经过皂化可以制成甘油，二者为原材料、工艺与成品的对应关系，但皂化为化学变化，与题干逻辑关系不一致，排除；\n\nD 项：淀粉经过水解可以制成葡萄糖，二者为原材料、工艺与成品的对应关系，但水解为化学变化，与题干逻辑关系不一致，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[14,15],"answerPages":[35]},"idx":74,"pid":"p56f583c407"},{"qid":"sy-c-20251025-076","no":76,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"对应关系","auxiliary":["对应关系","功能对应","方式目的对应"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation","evidence":"对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[35,36]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-076-题目-p15-106-149.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"造船：车间：船台"},{"k":"B","t":"竹尺：墨斗：测量"},{"k":"C","t":"纺纱：纺轮：纺锤"},{"k":"D","t":"养蚕：蚕茧：桑叶"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-076-解析-p35-626-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-076-解析-p36-51-247.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"修车：改锥：扳手","options":[{"k":"A","t":"造船：车间：船台"},{"k":"B","t":"竹尺：墨斗：测量"},{"k":"C","t":"纺纱：纺轮：纺锤"},{"k":"D","t":"养蚕：蚕茧：桑叶"}],"material":"","explanation":"76\n\n第一步：判断题干词语间逻辑关系。\n\n改锥和扳手是修车时需要用到的工具，后两个词和第一个词之间是工具的对应关系。\n\nA 项：车间和船台是造船的场所，后两个词和第一个词之间是场所的对应关系，与题干逻辑关系不一致，排除；\n\nB 项：竹尺和墨斗都可以用来测量，前两个词和第三个词之间是功能的对应关系，与题干逻辑关系不一致，排除；\n\nC 项：纺轮和纺锤是纺纱时需要用到的工具，后两个词和第一个词之间是工具的对应关系，与题干逻辑关系一致，当选；\n\nD 项：养蚕是为了得到蚕茧，二者是方式目的的对应关系，与题干逻辑关系不一致，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[15],"answerPages":[35,36]},"idx":75,"pid":"p56f583c407"},{"qid":"sy-c-20251025-077","no":77,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"综合关系","auxiliary":["语法关系","对应关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation.multiple","evidence":"动宾；对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[36]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-077-题目-p15-144-187.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"影像：器材：捕捉"},{"k":"B","t":"算法：接收：解码"},{"k":"C","t":"电脑：电影：播放"},{"k":"D","t":"植物：阳光：反射"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-077-解析-p36-243-582.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"算法：数据：处理","options":[{"k":"A","t":"影像：器材：捕捉"},{"k":"B","t":"算法：接收：解码"},{"k":"C","t":"电脑：电影：播放"},{"k":"D","t":"植物：阳光：反射"}],"material":"","explanation":"77\n\n第一步：判断题干词语间逻辑关系。\n\n处理数据，二者为动宾关系，算法是处理数据的工具，二者为工具对应关系。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：捕捉影像，二者为动宾关系，器材是捕捉影像的工具，但词语顺序与题干不符，与题干逻辑关系不一致，排除；\n\nB 项：信号需要先接收再解码，二者是时间先后顺序的对应关系，与题干逻辑关系不一致，排除；\n\nC 项：播放电影，二者为动宾关系，电脑是播放电影的工具，二者为工具对应关系，与题干逻辑关系一致，当选；\n\nD 项：反射阳光，二者为动宾关系，但植物不是反射阳光的工具，与题干逻辑关系不一致，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[15],"answerPages":[36]},"idx":76,"pid":"p56f583c407"},{"qid":"sy-c-20251025-078","no":78,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"综合关系","auxiliary":["并列关系","语法关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation.multiple","evidence":"矛盾关系；动宾","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[36,37]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-078-题目-p15-182-225.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"招聘：应届生：往届生"},{"k":"B","t":"装修：家属楼：居民楼"},{"k":"C","t":"就诊：候诊区：治疗区"},{"k":"D","t":"土壤：有机质：无机质"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-078-解析-p36-578-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-078-解析-p37-51-223.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"注册：实体店：虚拟店","options":[{"k":"A","t":"招聘：应届生：往届生"},{"k":"B","t":"装修：家属楼：居民楼"},{"k":"C","t":"就诊：候诊区：治疗区"},{"k":"D","t":"土壤：有机质：无机质"}],"material":"","explanation":"78\n\n第一步：判断题干词语间逻辑关系。\n\n实体店和虚拟店是店铺的不同形式，店铺除了实体店就是虚拟店，二者为矛盾关系，注册实体店、注册虚拟店，二者与注册之间均为动宾关系。\n\n第二步：判断选项词语间逻辑关系。\n\nA 项：应届生和往届生是毕业生的不同身份，毕业生除了应届生就是往届生，二者为矛盾关系，招聘应届生、招聘往届生，二者与招聘之间均为动宾关系，与题干逻辑关系一致，当选；\n\nB 项：家属楼是一种居民楼，二者为种属关系，与题干逻辑关系不一致，排除；\n\nC 项：候诊区和治疗区是医院的不同区域，除了候诊区和治疗区还有后勤支持区等其他区域，二者为反对关系，且就诊和后两词之间不是动宾关系，与题干逻辑关系不一致，排除；\n\nD 项：有机质和无机质是物质的不同形式，除了有机质就是无机质，二者为矛盾关系，土壤中含有有机质和无机质，后两词与土壤之间为组成关系，与题干逻辑关系不一致，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[15],"answerPages":[36,37]},"idx":77,"pid":"p56f583c407"},{"qid":"sy-c-20251025-079","no":79,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"综合关系","auxiliary":["包容关系·种属","并列关系","对应关系"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation.multiple","evidence":"种属关系；并列关系；对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[37]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-079-题目-p15-221-263.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"政府补助 军用仓库"},{"k":"B","t":"财政预算 交通设施"},{"k":"C","t":"政策支持 军事设备"},{"k":"D","t":"承贷企业 作战军团"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-079-解析-p37-219-510.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"财政贴息对于（    ）相当于（    ）对于军事设施","options":[{"k":"A","t":"政府补助 军用仓库"},{"k":"B","t":"财政预算 交通设施"},{"k":"C","t":"政策支持 军事设备"},{"k":"D","t":"承贷企业 作战军团"}],"material":"","explanation":"79逐一代入选项。\n\nA 项：财政贴息是政府补助，二者为种属关系，军用仓库是军事设施，二者为种属关系，前后逻辑关系一致，当选；\n\nB 项：财政贴息的资金需纳入财政预算安排，二者为对应关系，交通设施与军事设施是不同范畴的基础设施，二者为并列关系，前后逻辑关系不一致，排除；\n\nC 项：财政贴息是政策支持，二者为种属关系，军事设备（如枪支、坦克）与军事设施（如基地、仓库）是军事领域的不同装备，二者为并列关系，前后逻辑关系不一致，排除；\n\nD 项：承贷企业是财政贴息的对象，二者为行为与对象的对应关系，作战军团使用军事设施，二者为主体与工具的对应关系，前后逻辑关系不一致，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[15],"answerPages":[37]},"idx":78,"pid":"p56f583c407"},{"qid":"sy-c-20251025-080","no":80,"type":"类比推理","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"类比推理","tag":"综合关系","auxiliary":["包容关系·种属","并列关系","对应关系","功能对应"],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"analogy.stem-relation.multiple","evidence":"属于资源开发的一种；并列关系；功能的对应关系","curriculum":{"file":"判断推理.pdf","pages":"34–43","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[37]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-080-题目-p15-259-302.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"三峡大坝 岩浆活动"},{"k":"B","t":"资源开发 地质景观"},{"k":"C","t":"核能发电 休眠火山"},{"k":"D","t":"经济发展 物质喷发"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-080-解析-p37-506-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-080-解析-p38-51-103.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"水力发电对于（    ）相当于（    ）对于活火山","options":[{"k":"A","t":"三峡大坝 岩浆活动"},{"k":"B","t":"资源开发 地质景观"},{"k":"C","t":"核能发电 休眠火山"},{"k":"D","t":"经济发展 物质喷发"}],"material":"","explanation":"80逐一代入选项。\n\nA 项：三峡大坝能实现水力发电，二者为功能的对应关系，岩浆活动是活火山喷发的动力来源，二者为动力来源的对应关系，前后逻辑关系不一致，排除；\n\nB 项：水利发电属于资源开发的一种，二者为种属关系，活火山属于地质景观的一种，二者为种属关系，前后逻辑关系一致，但词语前后顺序相反，排除；\n\nC 项：水力发电与核能发电是不同类型的发电方式，二者为并列关系，活火山与休眠火山是不同状态的火山，二者为并列关系，前后逻辑关系一致，当选；\n\nD 项：水力发电能促进经济发展，二者为功能对应关系，活火山活动时会有物质喷发，二者为喷发方式对应关系，前后逻辑关系不一致，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"类比推理","questionPages":[15],"answerPages":[37]},"idx":79,"pid":"p56f583c407"},{"qid":"sy-c-20251025-081","no":81,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"翻译推理","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.explanation","evidence":"翻译题干","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[38]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-081-题目-p15-297-372.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"所有的管理人员都必须在分公司工作满5年"},{"k":"B","t":"在分公司工作满5年的员工都具有硕士学位"},{"k":"C","t":"有些具有硕士学位的员工已在分公司连续工作3年"},{"k":"D","t":"已进入公司理事会的都是具有硕士学位的管理人员"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-081-解析-p38-99-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"在某公司，所有管理人员都具有硕士学位，部分管理人员已经进入公司理事会。只有在分公司工作满5年，并且其中至少连续3年被评为优秀的员工，才有资格进入公司理事会。由此可以推出（    ）。","options":[{"k":"A","t":"所有的管理人员都必须在分公司工作满5年"},{"k":"B","t":"在分公司工作满5年的员工都具有硕士学位"},{"k":"C","t":"有些具有硕士学位的员工已在分公司连续工作3年"},{"k":"D","t":"已进入公司理事会的都是具有硕士学位的管理人员"}],"material":"","explanation":"81\n\n第一步：翻译题干。\n\n①管理人员硕士学位；\n\n②有的管理人员进入公司理事会；\n\n在分公司工作满5 年且至少连续3 年被评为优秀的员工。\n\n③进入公司理事会\n\n第二步：逐一分析选项。\n\nA 项：翻译为：管理人员在分公司工作满5 年，根据②③可得有的管理人员进入公在分公司工作满5 年且至少连续3 年被评为优秀的员工，有的推不出所有，无司理事会法推出，排除；\n\nB 项：翻译为：在分公司工作满5 年的员工具有硕士学位，在分公司工作满5 年是对③箭头后一部分的肯定，无法推出任何结论，排除；\n\nC 项：翻译为：有的具有硕士学位的员工在分公司连续工作3 年，②换位得：有的进入公司理事会管理人员，与①串联得④：有些进入公司理事会管理人员硕士学位，将④换位得有的硕士学位进入公司理事会，与③串联得：有的硕士学位进入公司理在分公司工作满5 年且至少连续3 年被评为优秀的员工，可以推出，当选；\n\n事会\n\nD 项：翻译为：已进入公司理事会具有硕士学位的管理人员，已进入公司理事会是对②的肯后，肯后无必然结论，无法推出，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[15],"answerPages":[38]},"idx":80,"pid":"p56f583c407"},{"qid":"sy-c-20251025-082","no":82,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"前提假设","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"前提","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[38,39]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-082-题目-p15-368-523.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"无氧代谢越多，体内 堆积得越多"},{"k":"B","t":"低强度运动不会使体内产生大量"},{"k":"C","t":"有氧代谢时，体内ATP水解速度较慢"},{"k":"D","t":"高强度运动时，身体以无氧代谢为主"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-082-解析-p38-554-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-082-解析-p39-51-318.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"很多人在低强度运动比如慢跑的时候可以跑很长的时间，可一旦提高速度、加大强度，很快就会感到双腿像灌了铅一样沉，肌肉酸痛，这是因为提高速度、加大强度后，体内迅速产生并堆积了大量的氢离子（ ）。人在任何运动中都同时存在有氧代谢和无氧代谢。当以无氧代谢为主时，身体内的三磷酸腺苷（ATP）水解释放的 快速累积难以清除，抑制肌肉收缩并导致肌肉酸痛。因此，高强度运动使身体感到酸痛。\n\n以下哪项最可能作为上述论证的前提？（    ）","options":[{"k":"A","t":"无氧代谢越多，体内 堆积得越多"},{"k":"B","t":"低强度运动不会使体内产生大量"},{"k":"C","t":"有氧代谢时，体内ATP水解速度较慢"},{"k":"D","t":"高强度运动时，身体以无氧代谢为主"}],"material":"","explanation":"82\n\n第一步：找出论点和论据。\n\n论点：高强度运动使身体感到酸痛。\n\n论据：人在任何运动中都同时存在有氧代谢和无氧代谢。当以无氧代谢为主时，身体内的三磷酸腺苷（ATP）水解释放的快速累积难以清除，抑制肌肉收缩并导致肌肉酸痛。\n\n论点讨论的是高强度运动使身体感到酸痛，论据讨论的是以无氧代谢为主时会导致肌肉酸痛。\n\n论点论据话题不一致，优先考虑搭桥，即建立“高强度运动”和“以无氧代谢为主”的关系。\n\n第二步：逐一分析选项。\n\nA 项：该选项说明无氧代谢越多，体内堆积得越多，加强论据，但与论点所说的高强度运动是否会使身体感到酸痛无关，不是论证成立的前提，排除；\n\nB 项：该选项说明低强度运动不会使体内产生大量，与论点讨论的高强度运动是否会使身体感到酸痛无关，不能加强，排除；\n\nC 项：该选项说明有氧代谢时，体内ATP 水解速度较慢，与论点讨论的高强度运动是否会使身体感到酸痛无关，不能加强，排除；\n\nD 项：该选项说明高强度运动时，身体以无氧代谢为主，建立了“高强度运动”和“以无氧代谢为主”的关系，为搭桥项，是论证成立的前提，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[15],"answerPages":[38,39]},"idx":81,"pid":"p56f583c407"},{"qid":"sy-c-20251025-083","no":83,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"前提假设","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"前提","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15],"answer":[39]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-083-题目-p15-518-673.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"绿色能源能够为人工智能提供持续、稳定、不断的电力保障"},{"k":"B","t":"煤炭、石油提供的电力资源已无法满足人工智能的发展需求"},{"k":"C","t":"利用人工智能的电力需求可以促进下一代绿色能源技术发展"},{"k":"D","t":"人工智能竞争的关键是能否提供全天候稳定可靠的电力保障"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-083-解析-p39-314-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-083-解析-p40-51-103.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"未来，人工智能或将成为主宰全球经济的最关键因素，各国都在争相发展人工智能。人工智能数据中心需要全天候稳定可靠的电力保障，这些吉瓦（1吉瓦=10亿瓦）级“用户”对于电力的规模和密度需求出现前所未有的激增。现有的发电方案难以满足上述需求，必须建立一套新发电解决方案，为人工智能的发展提供不断的电力支持。因此，人工智能竞争到最后是绿色能源的竞争。\n\n上述论证的成立需要补充以下哪项作为前提？（    ）","options":[{"k":"A","t":"绿色能源能够为人工智能提供持续、稳定、不断的电力保障"},{"k":"B","t":"煤炭、石油提供的电力资源已无法满足人工智能的发展需求"},{"k":"C","t":"利用人工智能的电力需求可以促进下一代绿色能源技术发展"},{"k":"D","t":"人工智能竞争的关键是能否提供全天候稳定可靠的电力保障"}],"material":"","explanation":"83\n\n第一步：找出论点和论据。\n\n论点：人工智能竞争到最后是绿色能源的竞争。\n\n论据：人工智能数据中心需要全天候稳定可靠的电力保障，这些吉瓦（1 吉瓦=10 亿瓦）级“用户”对于电力的规模和密度需求出现前所未有的激增。现有的发电方案难以满足上述需求，必须建立一套新发电解决方案，为人工智能的发展提供不断的电力支持。\n\n论点讨论“人工智能”与“绿色能源”，论据讨论“人工智能”与“电力保障”，话题不一致，优先考虑搭桥。\n\n第二步：逐一分析选项。\n\nA 项：该项说明绿色能源能够为人工智能提供持续、稳定、不断的电力保障，建立论点论据之间的联系，为搭桥项，可以作为论证成立的前提，当选；\n\nB 项：该项说明煤炭、石油提供的电力资源无法满足人工智能的发展需求，与绿色能源无关，不能作为论证成立的前提，排除；\n\nC 项：该项说明利用人工智能的电力需求可以促进下一代绿色能源技术发展，指出人工智能对绿色能源技术发展的促进作用，而题干讨论的是绿色能源能否为人工智能提供电力支持，话题不一致，不能作为论证成立的前提，排除；\n\nD 项：该项说明人工智能竞争的关键是能否提供全天候稳定可靠的电力保障，是对题干信息的重复，且与绿色能源无关，不能作为论证成立的前提，排除。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[15],"answerPages":[39]},"idx":82,"pid":"p56f583c407"},{"qid":"sy-c-20251025-084","no":84,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"前提假设","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"前提","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[15,16],"answer":[40]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-084-题目-p15-669-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-084-题目-p16-51-175.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"为了确保基因表达的平衡，雌性体内的每个细胞都会随机遗传一条X染色体，另一条则会关闭或失活"},{"k":"B","t":"在小鼠这一种群中，雌性小鼠的大脑衰老速度比雄性小鼠更快，其在认知、记忆方面的表现也不如雄性小鼠"},{"k":"C","t":"在仅表达母体X染色体的雌性小鼠的大脑中，母体X染色体加速了对学习和记忆有重要影响的海马体的衰老"},{"k":"D","t":"对仅表达母体X染色体的雌性小鼠，研究人员使用基因编辑技术激活其父体X染色体时，小鼠的智力水平得到了提高"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-084-解析-p40-99-582.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"雌性天生拥有两条X染色体，一条遗传自母体，一条遗传自父体。为了探究父母X染色体对雌性后代大脑的影响，研究人员培育了几只雌性小鼠，它们中有的仅表达来自母体的X染色体，有的同时表达母体和父体两者的X染色体。研究人员最终得出结论，当雌性小鼠的脑细胞仅依赖从母体继承的X染色体时，大脑衰老速度会更快。\n\n上述论证的成立需要补充以下哪项作为前提？（    ）","options":[{"k":"A","t":"为了确保基因表达的平衡，雌性体内的每个细胞都会随机遗传一条X染色体，另一条则会关闭或失活"},{"k":"B","t":"在小鼠这一种群中，雌性小鼠的大脑衰老速度比雄性小鼠更快，其在认知、记忆方面的表现也不如雄性小鼠"},{"k":"C","t":"在仅表达母体X染色体的雌性小鼠的大脑中，母体X染色体加速了对学习和记忆有重要影响的海马体的衰老"},{"k":"D","t":"对仅表达母体X染色体的雌性小鼠，研究人员使用基因编辑技术激活其父体X染色体时，小鼠的智力水平得到了提高"}],"material":"","explanation":"84\n\n第一步：找出论点和论据。\n\n论点：当雌性小鼠的脑细胞仅依赖从母体继承的X 染色体时，大脑衰老速度会更快。\n\n论据：无。\n\n只有论点，加强优先考虑补充论据。\n\n第二步：逐一分析选项。\n\nA 项：该项说明雌性体内的每个细胞都会随机遗传一条X 染色体，另一条则会关闭或失活，讨论的是X 染色体遗传的随机性，与雌性小鼠的脑细胞仅依赖从母体继承的X 染色体是否会导致大脑衰老速度更快无关，不能加强，排除；\n\nB 项：该项说明雌性小鼠的大脑衰老速度比雄性小鼠更快，且在认知、记忆方面的表现不如雄性小鼠，与雌性小鼠的脑细胞仅依赖从母体继承的X 染色体是否会导致大脑衰老速度更快无关，不能加强，排除；\n\nC 项：该项说明在仅表达母体X 染色体的雌性小鼠的大脑中，母体X 染色体加速了海马体的衰老，表明仅依赖从母体继承的X 染色体时，大脑衰老速度会加快，补充论据，为加强项，当选；\n\nD 项：该项说明激活仅表达母体X 染色体的雌性小鼠的父体X 染色体，可以提高其智力，强调父体X 染色体可以提高智力，与雌性小鼠的脑细胞仅依赖从母体继承的X 染色体是否会导致大脑衰老速度更快无关，不能加强，排除。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[15,16],"answerPages":[40]},"idx":83,"pid":"p56f583c407"},{"qid":"sy-c-20251025-085","no":85,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"加强论证","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"支持","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[16],"answer":[40,41]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-085-题目-p16-170-325.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"高被引代表了学术影响力，“早熟”科学家都想进入这个行列"},{"k":"B","t":"如果排除自我引用，20%的“早熟”科学家会跌出高被引行列"},{"k":"C","t":"过度自我引用标志着不正常的发表行为，会引发科研诚信问题"},{"k":"D","t":"有一些“早熟”科学家发表了大量被认为是无意义的科研论文"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-085-解析-p40-578-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-085-解析-p41-51-343.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"据统计，科学家从首次发表论文到进入高被引行列的平均时长为36年。然而最新研究发现，近5年“早熟”科学家（在首次发表论文后的8年内进入高被引行列的人）从213名增加到469名。在这些“早熟”科学家中，有相当一部分人自我引用的比例显著高于平均水平。研究人员认为，过度自引是导致“早熟”科学家数量激增的原因。\n\n以下哪项如果为真，最能支持上述结论？（    ）","options":[{"k":"A","t":"高被引代表了学术影响力，“早熟”科学家都想进入这个行列"},{"k":"B","t":"如果排除自我引用，20%的“早熟”科学家会跌出高被引行列"},{"k":"C","t":"过度自我引用标志着不正常的发表行为，会引发科研诚信问题"},{"k":"D","t":"有一些“早熟”科学家发表了大量被认为是无意义的科研论文"}],"material":"","explanation":"85\n\n第一步：找出论点和论据。\n\n论点：过度自引是导致“早熟”科学家数量激增的原因。\n\n论据：近5 年“早熟”科学家（在首次发表论文后的8 年内进入高被引行列的人）从213 名增加到469 名。在这些“早熟”科学家中，有相当一部分人自我引用的比例显著高于平均水平。\n\n论点和论据均围绕“自我引用”和“‘早熟’科学家数量”展开讨论，话题一致，加强优先考虑补充论据。\n\n第二步：逐一分析选项。\n\nA 项：该项说明“早熟”科学家都想进入高被引行列，指出科学家的心理想法，与过度自引是否导致“早熟”科学家数量激增无关，不能支持，排除；\n\nB 项：该项说明如果排除自我引用，20%的“早熟”科学家会跌出高被引行列，即自我引用使得20%的“早熟”科学家进入高被引行列，证明过度自引使得“早熟”科学家数量激增，补充论据，可以支持，当选；\n\nC 项：该项说明过度自我引用会引发科研诚信问题，指出过度自引的危害，与过度自引是否导致“早熟”科学家数量激增无关，不能支持，排除；\n\nD 项：该项说明有些“早熟”科学家发表了大量无意义的科研论文，指出科研论文发表现状，与过度自引是否导致“早熟”科学家数量激增无关，不能支持，排除。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[16],"answerPages":[40,41]},"idx":84,"pid":"p56f583c407"},{"qid":"sy-c-20251025-086","no":86,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"加强论证","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"支持","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[16],"answer":[41]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-086-题目-p16-321-460.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"开在医院附近的母婴用品门店，其线下销售渠道的销售额日益增加"},{"k":"B","t":"婴幼儿食品的概念和功能较为复杂，线下导购能提供更个性化的服务"},{"k":"C","t":"母婴品类线下销售渠道，其售后服务更直接便捷，能直接处理问题产品"},{"k":"D","t":"线下销售的母婴产品能让消费者直接看到和触摸到，提升购买的安心感"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-086-解析-p41-339-750.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2022~2024年，母婴品类线下渠道销售额占比逐年下降，分别为69.4%、64.9%和59.7%。有业内人士认为，虽然销售额占比逐年下降，但母婴品类线下销售渠道仍然具有很强的不可替代性，尤其在婴幼儿食品销售中，线下渠道的重要性更为显著。\n\n以下哪项如果为真，不能支持该业内人士的观点？（    ）","options":[{"k":"A","t":"开在医院附近的母婴用品门店，其线下销售渠道的销售额日益增加"},{"k":"B","t":"婴幼儿食品的概念和功能较为复杂，线下导购能提供更个性化的服务"},{"k":"C","t":"母婴品类线下销售渠道，其售后服务更直接便捷，能直接处理问题产品"},{"k":"D","t":"线下销售的母婴产品能让消费者直接看到和触摸到，提升购买的安心感"}],"material":"","explanation":"86\n\n第一步：找出论点和论据。\n\n论点：虽然销售额占比逐年下降，但母婴品类线下销售渠道仍然具有很强的不可替代性，尤其在婴幼儿食品销售中，线下渠道的重要性更为显著。\n\n论据：无。\n\n本题只有论点没有论据，加强优先考虑补充论据。\n\n第二步：逐一分析选项。\n\nA 项：该项说明开在医院附近的母婴用品门店线下销售渠道的销售额日益增加，仅指出线下销售渠道的销售额增加，不明确线下销售渠道是否具有不可替代性，不能支持，当选；\n\nB 项：该项说明婴幼儿食品的概念和功能较为复杂，线下导购能提供更个性化的服务，指出婴幼儿食品领域线下销售更具优势，可以体现线下销售渠道的不可替代性，可以支持，排除；\n\nC 项：该项说明母婴品类线下销售渠道售后服务更直接便捷，能直接处理问题产品，指出母婴品类线下销售渠道的优势，可以体现线下销售渠道的不可替代性，可以支持，排除；\n\nD 项：该项说明线下销售的母婴产品能让消费者提升购买的安心感，指出母婴品类线下销售渠道的优势，可以体现线下销售渠道的不可替代性，可以支持，排除。\n\n本题为选非题，故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[16],"answerPages":[41]},"idx":85,"pid":"p56f583c407"},{"qid":"sy-c-20251025-087","no":87,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"加强论证","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"支持","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[16],"answer":[41,42]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-087-题目-p16-455-626.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"土卫二的冰层厚度为5-20公里，木卫二的冰层厚度为15-30公里"},{"k":"B","t":"木卫二表面辐射剂量是地球的数百万倍，登陆需额外研发防护技术"},{"k":"C","t":"质谱分析显示土卫二羽流中存在磷化物，这种物质未在木卫二表面发现"},{"k":"D","t":"土卫二海底热泉区域存在与地球马里亚纳海沟热液喷口相似的温度和结构"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-087-解析-p41-746-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-087-解析-p42-51-583.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"某天文学家团队提交的论证报告指出，土卫二具备完整的生命孕育要素，应成为未来二十年深空生命探测的首要目标。该星体南极区域存在周期性喷发的冰晶羽流，其中检测到的氯化钠、碳酸氢化合物及微量甲烷。更关键的是，其冰壳下方存在全球性液态海洋，平均深度30公里，且海底岩层与海水交界处存在持续的热液活动。\n\n有研究表明，地球海底热液口附近是生命诞生的理想区域。反对者认为，木卫二同样具备冰下海洋特征，且表面冰层裂缝中已发现类似海底的色素沉积物，更可能孕育生命，应首先探测。\n\n以下哪项如果为真，最能支持该天文学家团队的观点？（    ）","options":[{"k":"A","t":"土卫二的冰层厚度为5-20公里，木卫二的冰层厚度为15-30公里"},{"k":"B","t":"木卫二表面辐射剂量是地球的数百万倍，登陆需额外研发防护技术"},{"k":"C","t":"质谱分析显示土卫二羽流中存在磷化物，这种物质未在木卫二表面发现"},{"k":"D","t":"土卫二海底热泉区域存在与地球马里亚纳海沟热液喷口相似的温度和结构"}],"material":"","explanation":"87\n\n第一步：找出论点和论据。\n\n论点：土卫二具备完整的生命孕育要素，应成为未来二十年深空生命探测的首要目标。\n\n论据：该星体南极区域存在周期性喷发的冰晶羽流，其中检测到的氯化钠、碳酸氢化合物及微量甲烷。更关键的是，其冰壳下方存在全球性液态海洋，平均深度30 公里，且海底岩层与海水交界处存在持续的热液活动。有研究表明，地球海底热液口附近是生命诞生的理想区域。\n\n论点论据均围绕“土卫二”和“生命探测”展开讨论，话题一致，加强考虑补充论据。\n\n第二步：逐一分析选项。\n\nA 项：该项讨论的是土卫二和木卫二的冰层厚度，与土卫二是否应成为未来二十年深空生命探测的首要目标无关，不能支持，排除；\n\nB 项：该项说明木卫二表面辐射剂量高，登陆需额外研发防护技术，与论点讨论的土卫二，主体不一致，不能支持，排除；\n\nC 项：该项说明土卫二羽流中存在磷化物未在木卫二表面发现，但该磷化物是否为生命孕育要素未知，且土卫二是否应成为未来二十年深空生命探测的首要目标不确定，不能支持，排除；\n\nD 项：该项说明土卫二海底热泉区域存在与地球马里亚纳海沟热液喷口相似的温度和结构，论据指出地球海底热液口附近是生命诞生的理想区域，那么与地球海底热液口环境相似的土卫二海底热泉区域就更有可能存在生命，土卫二应该成为未来二十年深空生命探测的首要目标，补充论据，可以支持，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[16],"answerPages":[41,42]},"idx":86,"pid":"p56f583c407"},{"qid":"sy-c-20251025-088","no":88,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"加强论证","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"支持","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[16],"answer":[42,43]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-088-题目-p16-622-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-088-题目-p17-51-91.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"根据地质模拟分析，这些橄榄岩受到板块运动的影响后不断地被抬升"},{"k":"B","t":"地幔中的锂同位素分布不均匀，不是所有地幔橄榄岩都含有锂同位素"},{"k":"C","t":"地幔橄榄岩温度较高，进入海洋后会让海水中锂元素扩散进入岩石边缘"},{"k":"D","t":"橄榄岩的边缘呈现海水锂同位素的特征，中心呈现地幔锂同位素的特征"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-088-解析-p42-579-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-088-解析-p43-51-295.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"近日，某研究团队对青藏高原地区挖掘出的早期地幔橄榄岩进行分析后发现，这些橄榄岩的矿物颗粒中均含有海水锂同位素和地幔锂同位素的特征。由于青藏高原早期曾经是一片海洋，因此该研究团队认为，这些地幔橄榄岩一定是从地层深处上升到了海洋，在海水浸润中获取了海水锂同位素。\n\n以下哪项如果为真，不能支持上述观点？（    ）","options":[{"k":"A","t":"根据地质模拟分析，这些橄榄岩受到板块运动的影响后不断地被抬升"},{"k":"B","t":"地幔中的锂同位素分布不均匀，不是所有地幔橄榄岩都含有锂同位素"},{"k":"C","t":"地幔橄榄岩温度较高，进入海洋后会让海水中锂元素扩散进入岩石边缘"},{"k":"D","t":"橄榄岩的边缘呈现海水锂同位素的特征，中心呈现地幔锂同位素的特征"}],"material":"","explanation":"88\n\n第一步：找出论点和论据。\n\n论点：这些地幔橄榄岩一定是从地层深处上升到了海洋，在海水浸润中获取了海水锂同位素。\n\n论据：某研究团队对青藏高原地区挖掘出的早期地幔橄榄岩进行分析后发现，这些橄榄岩的矿物颗粒中均含有海水锂同位素和地幔锂同位素的特征，且青藏高原早期曾经是一片海洋。\n\n第二步：逐一分析选项。\n\nA 项：该项指出这些橄榄岩受到板块运动的影响后不断地被抬升，解释了橄榄岩从地层深处上升到海洋的原因，补充论据，可以加强，排除；\n\nB 项：该项指出不是所有地幔橄榄岩都含有锂同位素，与论点讨论的地幔橄榄岩是否从地层深处上升到海洋并获取海水锂同位素无关，话题不一致，无法加强，当选；\n\nC 项：该项指出地幔橄榄岩温度较高，进入海洋后会让海水中锂元素扩散进入岩石边缘，解释说明了橄榄岩确实可以在海水浸润中获取海水锂同位素，补充论据，可以加强，排除；\n\nD 项：该项指出橄榄岩的边缘呈现海水锂同位素的特征，中心呈现地幔锂同位素的特征，说明这些橄榄岩是先存在于地幔中获取了地幔中锂同位素，后上升到海洋，在海水浸润中获取了海水锂同位素，补充论据，可以加强，排除。\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[16],"answerPages":[42,43]},"idx":87,"pid":"p56f583c407"},{"qid":"sy-c-20251025-089","no":89,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"削弱论证","auxiliary":[],"methods":[],"forms":[],"confidence":"高","needsReview":false,"rule":"logic.request","evidence":"质疑","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[17],"answer":[43]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-089-题目-p17-87-242.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"人工投食区的设置使短尾雄鸟存活率提升了25%"},{"k":"B","t":"白鹇雌鸟视网膜中感知色彩的视锥细胞数仅为雄鸟的60%"},{"k":"C","t":"尾羽生长需要消耗大量蛋白质，老年雄鸟尾羽长度会逐年缩短"},{"k":"D","t":"在隔绝声音的环境中，雌鸟对长尾或短尾雄鸟的偏好率相差无几"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-089-解析-p43-291-726.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"研究人员针对白鹇的求偶行为展开研究。白鹇雄鸟羽色黑白分明、尾羽修长，求偶时伴有高频鸣叫；雌鸟羽色灰褐，无明显装饰性特征。研究人员在观测6个白鹇种群时发现，尾羽长度排名前20%的雄鸟，其求偶成功率是群体平均值的23倍。研究人员在保护区内设置人工投食区，确保所有雄鸟食物供给均等。一年后数据显示，尾羽长度与求偶成功率仍呈强正相关。研究人员据此认为，尾羽长度是雌鸟选择配偶的核心标准。\n\n以下哪项如果为真，最能质疑上述论证？（    ）","options":[{"k":"A","t":"人工投食区的设置使短尾雄鸟存活率提升了25%"},{"k":"B","t":"白鹇雌鸟视网膜中感知色彩的视锥细胞数仅为雄鸟的60%"},{"k":"C","t":"尾羽生长需要消耗大量蛋白质，老年雄鸟尾羽长度会逐年缩短"},{"k":"D","t":"在隔绝声音的环境中，雌鸟对长尾或短尾雄鸟的偏好率相差无几"}],"material":"","explanation":"89\n\n第一步：找出论点和论据。\n\n论点：尾羽长度是雌鸟选择配偶的核心标准。\n\n论据：研究人员在观测6 个白鹇种群时发现，尾羽长度排名前20%的雄鸟，其求偶成功率是群体平均值的23 倍。研究人员在保护区内设置人工投食区，确保所有雄鸟食物供给均等。\n\n一年后数据显示，尾羽长度与求偶成功率仍呈强正相关。\n\n论点和论据均围绕“尾羽长度”和“雌鸟择偶”展开讨论，话题一致，削弱时优先考虑否定论点。\n\n第二步：逐一分析选项。\n\nA 项：该项说明人工投食区的设置提升了短尾雄鸟存活率，与尾羽长度是否为雌鸟选择配偶的核心标准无关，不能质疑，排除；\n\nB 项：该项说明白鹇雌鸟视网膜中感知色彩的视锥细胞数比雄鸟少，即白鹇雌鸟的色彩感知能力比雄鸟差，与尾羽长度是否为雌鸟选择配偶的核心标准无关，不能质疑，排除；\n\nC 项：该项说明老年雄鸟尾羽长度会逐年缩短，与尾羽长度是否为雌鸟选择配偶的核心标准无关，不能质疑，排除；\n\nD 项：该项说明控制声音这一因素后，尾羽长度对雌鸟选择的影响较低，即尾羽长度并非雌鸟择偶的核心标准，而声音是雌鸟择偶的因素之一，直接否定论点，可以质疑，当选。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[17],"answerPages":[43]},"idx":88,"pid":"p56f583c407"},{"qid":"sy-c-20251025-090","no":90,"type":"逻辑判断","module":"判断推理","classification":{"version":"shiye-v1.20261011","group":"逻辑判断","tag":"日常结论","auxiliary":[],"methods":[],"forms":[],"confidence":"中","needsReview":false,"rule":"logic.request-inference","evidence":"推出","curriculum":{"file":"判断推理.pdf","pages":"59–99","map":"2.判断推理.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[17],"answer":[43,44]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-090-题目-p17-237-546.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"抗战剧和偶像剧都播出"},{"k":"B","t":"年代剧和偶像剧都不播出"},{"k":"C","t":"播出年代剧，不播出偶像剧"},{"k":"D","t":"播出偶像剧，不播出年代剧"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-090-解析-p43-722-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-090-解析-p44-51-488.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"为了提高收视率，某电视台准备在偶像剧、年代剧、抗战剧、古装剧四种类型的电视剧中选择若干类型播出，热心观众对播出的电视剧有如下猜测：（1）如果播出偶像剧，就播出年代剧；\n\n（2）偶像剧、抗战剧、古装剧至少播两种；\n\n（3）偶像剧和年代剧均不播出；\n\n（4）如果播出古装剧，则播出抗战剧；\n\n（5）不播出年代剧，但播出偶像剧。\n\n结果发现，上述五个猜测中有且仅有四个是错误的。\n\n根据以上信息，可以推出（    ）。","options":[{"k":"A","t":"抗战剧和偶像剧都播出"},{"k":"B","t":"年代剧和偶像剧都不播出"},{"k":"C","t":"播出年代剧，不播出偶像剧"},{"k":"D","t":"播出偶像剧，不播出年代剧"}],"material":"","explanation":"90\n\n第一步：整理题干信息。\n\n（1）偶像剧年代剧；\n\n（2）偶像剧、抗战剧、古装剧至少播出两种；\n\n（3）偶像剧且年代剧；\n\n（4）古装剧抗战剧；\n\n（5）偶像剧且年代剧。\n\n第二步：分析题干。\n\n由提问可知，本题为真假推理。先找矛盾关系，（1）和（5）互为矛盾关系，必有一真一假，结合提问，五个猜测中有且仅有四个是错误的，说明真话在（1）和（5）之中，则（2）（3）（4）为假话，其矛盾则为真。\n\n根据（2）矛盾为真，可得“偶像剧、抗战剧、古装剧最多播出一种”；\n\n根据（3）矛盾为真，可得“偶像剧或年代剧”；\n\n根据（4）矛盾为真，可得“古装剧且抗战剧”。\n\n因为播出古装剧且偶像剧、抗战剧、古装剧最多播出一种，可知偶像剧一定不播。该结论是对“偶像剧或年代剧”中一项的否定，根据否一推一，可以推出一定播年代剧。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/判断推理.md","module":"判断推理","sourceModule":"判断推理","sourceType":"逻辑判断","questionPages":[17],"answerPages":[43,44]},"idx":89,"pid":"p56f583c407"},{"qid":"sy-c-20251025-091","no":91,"type":"综合分析","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"综合分析","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"如工厂每天可生产1000件A产品，为了避免废弃，一次最多购入甲材料多少千克？（    ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[44]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-091-题目-p17-541-584.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m91-材料-p17-437-541.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":91,"options":[{"k":"A","t":"200"},{"k":"B","t":"500"},{"k":"C","t":"2000"},{"k":"D","t":"5000"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-091-解析-p44-484-597.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如工厂每天可生产1000件A产品，为了避免废弃，一次最多购入甲材料多少千克？（    ）","options":[{"k":"A","t":"200"},{"k":"B","t":"500"},{"k":"C","t":"2000"},{"k":"D","t":"5000"}],"material":"分析、比较、计算和判断处理。\n\n（一）工厂生产A产品1件，需要100克甲材料、60克乙材料和200克丙材料。已知甲、乙、丙材料的进货价格分别为60元/千克，200元/千克，80元/千克，这三种材料的进货成本占这种产品总成本的40%。\n\n甲、乙、丙材料在采购后，必须分别在20天、30天、20天内用于制作产品，超过此期限的材料必须废弃，废弃材料的处理成本为10元/千克。","explanation":"91根据题意，为了避免废弃，所有材料必须在20天内完成产品制作，则工厂最多生产A产品1000×20=20000件，每件A产品需要100克=0.1千克甲材料，因此一次最多购入甲材料0.1×20000=2000干克。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"综合分析C","questionPages":[17],"answerPages":[44]},"idx":90,"pid":"p56f583c407"},{"qid":"sy-c-20251025-092","no":92,"type":"综合分析","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"综合分析","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"工厂至少需要将A产品的出厂价定为多少元/件，才能保证销售利润（出厂价-成本）达到总成本的20%？（    ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[44]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-092-题目-p17-579-622.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m91-材料-p17-437-541.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":91,"options":[{"k":"A","t":"96"},{"k":"B","t":"102"},{"k":"C","t":"108"},{"k":"D","t":"114"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-092-解析-p44-593-737.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"工厂至少需要将A产品的出厂价定为多少元/件，才能保证销售利润（出厂价-成本）达到总成本的20%？（    ）","options":[{"k":"A","t":"96"},{"k":"B","t":"102"},{"k":"C","t":"108"},{"k":"D","t":"114"}],"material":"分析、比较、计算和判断处理。\n\n（一）工厂生产A产品1件，需要100克甲材料、60克乙材料和200克丙材料。已知甲、乙、丙材料的进货价格分别为60元/千克，200元/千克，80元/千克，这三种材料的进货成本占这种产品总成本的40%。\n\n甲、乙、丙材料在采购后，必须分别在20天、30天、20天内用于制作产品，超过此期限的材料必须废弃，废弃材料的处理成本为10元/千克。","explanation":"92根据题意，工厂生产1件A产品需要甲材料100克=0.1千克，乙材料60克=0.06千克，丙材料200克=0.2千克，这三种材料的进货成本为60×0.1+200×0.06+80×0.2=34元，可得1件A出厂价－85=85×20%，求得出厂价=102元，因此A产品出厂价至少定为102元/件。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"综合分析C","questionPages":[17],"answerPages":[44]},"idx":91,"pid":"p56f583c407"},{"qid":"sy-c-20251025-093","no":93,"type":"资料分析","module":"资料分析","classification":{"version":"shiye-v1.20261011","group":"资料分析","tag":"未细分","auxiliary":[],"methods":[],"forms":[],"confidence":"待复核","needsReview":true,"rule":"unresolved","evidence":"题面与解析不足以可靠确定细分考点","curriculum":{"file":"资料分析.pdf","pages":"1–68","map":"3.数量关系&资料分析.pdf"},"basis":"讲义体系 + 题面/解析规则识别","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[17],"answer":[44,45]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-093-题目-p17-618-676.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m91-材料-p17-437-618.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":91,"options":[{"k":"A","t":"82"},{"k":"B","t":"87.5"},{"k":"C","t":"96"},{"k":"D","t":"102.5"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-093-解析-p44-733-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-093-解析-p45-51-216.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如丙材料按进货价格一次采购25天的用量，且将废弃材料的处理成本计算在内后、实际使用丙材料的成本为多少元/千克？（    ）","options":[{"k":"A","t":"82"},{"k":"B","t":"87.5"},{"k":"C","t":"96"},{"k":"D","t":"102.5"}],"material":"分析、比较、计算和判断处理。\n\n（一）工厂生产A产品1件，需要100克甲材料、60克乙材料和200克丙材料。已知甲、乙、丙材料的进货价格分别为60元/千克，200元/千克，80元/千克，这三种材料的进货成本占这种产品总成本的40%。\n\n甲、乙、丙材料在采购后，必须分别在20天、30天、20天内用于制作产品，超过此期限的材料必须废弃，废弃材料的处理成本为10元/千克。","explanation":"93设丙材料每天的用量为千克，则25天的用量为25千克，采购成本为25z×80=2000元；定位第二段可知，丙材料必须20天内用于制作产品，则丙材料20天内实际使用量为20起千克，超出期限的废弃材料有25起-20=5起千克，处理成本为5起×10=50元，故将实际使用量20\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/资料分析.md","module":"资料分析","sourceModule":"综合分析","sourceType":"资料分析","questionPages":[17],"answerPages":[44,45]},"idx":92,"pid":"p56f583c407"},{"qid":"sy-c-20251025-094","no":94,"type":"综合分析","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"综合分析","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"成本不会上升？（    ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17],"answer":[45]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-094-题目-p17-672-747.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m91-材料-p17-437-541.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":91,"options":[{"k":"A","t":"50"},{"k":"B","t":"60"},{"k":"C","t":"75"},{"k":"D","t":"90"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-094-解析-p45-211-387.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"现有丁材料可用于替代甲、乙和丙三种材料（只能全部替代、不能部分替代），其用量为甲、乙、丙材料之和的1.5倍。且会使除丁材料之外的其他成本增加7元/件，问丁材料的价格不高于多少元/千克，A产品的单件生产成本不会上升？（    ）","options":[{"k":"A","t":"50"},{"k":"B","t":"60"},{"k":"C","t":"75"},{"k":"D","t":"90"}],"material":"分析、比较、计算和判断处理。\n\n（一）工厂生产A产品1件，需要100克甲材料、60克乙材料和200克丙材料。已知甲、乙、丙材料的进货价格分别为60元/千克，200元/千克，80元/千克，这三种材料的进货成本占这种产品总成本的40%。\n\n甲、乙、丙材料在采购后，必须分别在20天、30天、20天内用于制作产品，超过此期限的材料必须废弃，废弃材料的处理成本为10元/千克。","explanation":"94若使A产品的单件生产成本不会上升，则使用丁材料后的成本不能超过甲、乙、丙这三种材料的进货成本。定位第一段可知，生产1件A产品，使用甲、乙、丙这三种材料的进货成本为_10060200×80=6+12+16=34元，这三种材料用量之和为× 60 +× 200+100010001000100+60+200=360克，故利用丁材料代替时，用量为360×1.5=540克。设丁材料的价格540×2+7≤34，解得≤50，即当丁材料的价格不为元/千克，根据题意可列不等式：1000高于50元/干克时，A产品的单件生产成本不会上升。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"综合分析C","questionPages":[17],"answerPages":[45]},"idx":93,"pid":"p56f583c407"},{"qid":"sy-c-20251025-095","no":95,"type":"综合分析","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"综合分析","tag":"未细分","confidence":"待复核","needsReview":true,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.unresolved","evidence":"折优惠，哪种材料批量购买成本更低？（     ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[17,18],"answer":[45]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-095-题目-p17-742-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-095-题目-p18-51-373.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m91-材料-p17-437-541.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":91,"options":[{"k":"A","t":"仅甲材料批量购买成本更低"},{"k":"B","t":"仅乙材料批量购买成本更低"},{"k":"C","t":"甲、乙批量购买成本均更高"},{"k":"D","t":"甲、乙批量购买成本均更低"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-095-解析-p45-383-603.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"如工厂每天消耗1吨丙材料用于A产品的生产，且甲材料每次批量购买12吨或乙材料每次批量购买10吨可享受八折优惠，哪种材料批量购买成本更低？（     ）","options":[{"k":"A","t":"仅甲材料批量购买成本更低"},{"k":"B","t":"仅乙材料批量购买成本更低"},{"k":"C","t":"甲、乙批量购买成本均更高"},{"k":"D","t":"甲、乙批量购买成本均更低"}],"material":"分析、比较、计算和判断处理。\n\n（一）工厂生产A产品1件，需要100克甲材料、60克乙材料和200克丙材料。已知甲、乙、丙材料的进货价格分别为60元/千克，200元/千克，80元/千克，这三种材料的进货成本占这种产品总成本的40%。\n\n甲、乙、丙材料在采购后，必须分别在20天、30天、20天内用于制作产品，超过此期限的材料必须废弃，废弃材料的处理成本为10元/千克。","explanation":"95根据题意可得生产A产品所需甲、乙、丙材料的比例为5:3:10，若丙材料为1吨/天，则甲、乙材料分别为0.5、0.3吨/天。\n\n甲材料：20天使用量为0.5×20=10吨，随买随用甲材料20天费用：10×1000×60=600000元；若甲每批次购买12吨，故废弃材料数量为12－10=2吨（甲材料有效期为20天）废料处理费用为2×1000×10=20000元，成本共计12×1000×60×80%+20000=596000元，故甲材料批量购买成本更低。\n\n乙材料：30天使用量为0.3×30=9吨，随买随用甲材料30天费用：9×1000×200=1800000元；若乙每批次购买10吨，故废弃材料数量为10－9=1吨（乙材料有效期为30天），废料处理费用为1×1000×10=10000元，成本共计10×1000×200×80%+10000=1610000元，故乙材料批量购买成本更低。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"综合分析C","questionPages":[17,18],"answerPages":[45]},"idx":94,"pid":"p56f583c407"},{"qid":"sy-c-20251025-096","no":96,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"上述实验步骤（2）～（7）是被打乱的，正确的实验步骤应为（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18],"answer":[45,46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-096-题目-p18-368-427.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m96-材料-p18-120-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"（2）（4）（3）（7）（5）（6）"},{"k":"B","t":"（2）（6）（4）（3）（7）（5）"},{"k":"C","t":"（4）（3）（2）（7）（6）（5）"},{"k":"D","t":"（4）（6）（2）（7）（5）（3）"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-096-解析-p45-598-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-096-解析-p46-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"上述实验步骤（2）～（7）是被打乱的，正确的实验步骤应为（    ）。","options":[{"k":"A","t":"（2）（4）（3）（7）（5）（6）"},{"k":"B","t":"（2）（6）（4）（3）（7）（5）"},{"k":"C","t":"（4）（3）（2）（7）（6）（5）"},{"k":"D","t":"（4）（6）（2）（7）（5）（3）"}],"material":"（二）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理选出最符合每道题要求的一项。\n\n（—）实验目的：用硬币测量表面张力实验材料：硬币、滴管、小碗、自来水、肥皂、纸巾实验步骤：（1）把硬币放在一个水平的表面上。\n\n（2）在小碗中倒入自来水。\n\n（3）小心地在硬币顶部一次加一滴水。\n\n（4）将滴管放在硬币正上方并不要碰到硬币。\n\n（5）用纸巾彻底擦干硬币和周围表面。\n\n（6）用滴管吸取小碗中的水。\n\n（7）观察水滴，在水溢出硬币边缘时对滴落的水滴进行计数。\n\n（8）将少量的肥皂与自来水混合，用肥皂水重复实验并对比两个计数。","explanation":"96\n\n本题考查物理实验。\n\n步骤（2）“在小碗中倒入自来水”——这是实验的基础准备，必须最先进行（没有水，后续吸水、滴加都无法完成），排除C、D 项。\n\n对比步骤（4）和（6），步骤（4）是将滴管放在硬币正上方，步骤（6）是用滴管吸取小碗中的水，应当先吸取水，才能进行后续实验步骤，故步骤（6）不可能是最后一步，应当紧跟在步骤（2）之后，排除A 项。\n\n验证后续实验步骤：步骤（6）吸取水后，再进行步骤（4）调整滴管位置，步骤（3）开始滴水，步骤（7）是滴水后进入观察和计数环节，步骤（5）实验结束，清理硬币，为后续重复实验（如用肥皂水）做准备。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18],"answerPages":[45,46]},"idx":95,"pid":"p56f583c407"},{"qid":"sy-c-20251025-097","no":97,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"的计数相同，则最有可能是（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-097-题目-p18-423-760.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m96-材料-p18-120-368.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":96,"options":[{"k":"A","t":"肥皂水中含有其他的杂质"},{"k":"B","t":"水中含有与肥皂类似的杂质"},{"k":"C","t":"用水做实验后硬币未彻底干燥"},{"k":"D","t":"硬币未放置在绝对水平的表面上"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-097-解析-p46-195-486.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"已知肥皂水的表面张力和水存在较大差异，在用肥皂水做实验时，如果步骤（7）得出的计数与用水做实验时的计数相同，则最有可能是（    ）。","options":[{"k":"A","t":"肥皂水中含有其他的杂质"},{"k":"B","t":"水中含有与肥皂类似的杂质"},{"k":"C","t":"用水做实验后硬币未彻底干燥"},{"k":"D","t":"硬币未放置在绝对水平的表面上"}],"material":"（二）实验设计：请根据实验提供的信息，通过分析、比较、判断和处理选出最符合每道题要求的一项。\n\n（—）实验目的：用硬币测量表面张力实验材料：硬币、滴管、小碗、自来水、肥皂、纸巾实验步骤：（1）把硬币放在一个水平的表面上。\n\n（2）在小碗中倒入自来水。\n\n（3）小心地在硬币顶部一次加一滴水。\n\n（4）将滴管放在硬币正上方并不要碰到硬币。\n\n（5）用纸巾彻底擦干硬币和周围表面。\n\n（6）用滴管吸取小碗中的水。\n\n（7）观察水滴，在水溢出硬币边缘时对滴落的水滴进行计数。\n\n（8）将少量的肥皂与自来水混合，用肥皂水重复实验并对比两个计数。","explanation":"97\n\n本题考查物理实验。\n\nA、B 项错误，杂质可能增大或降低液体的表面张力，选项并未明确是何种杂质，因此加入杂质后并不能确定液体表面张力的变化方向，既有可能增大，也有可能减小，属于可能性较低的猜测。\n\nC 项正确，假设水的表面张力是m，肥皂水的表面张力是n。若用水做实验后硬币未彻底干燥，残留的水会稀释后续的肥皂水，使其表面张力介于m 和n 之间，即趋近于水的表面张力，从而导致两者能承载的水滴数接近，计数相同。\n\nD 项错误，硬币未放置在绝对水平的表面上可能会影响实验中硬币承载的水滴数，但这对于对照试验（肥皂水组）的影响同样存在的，不会造成两组实验计数相同。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18],"answerPages":[46]},"idx":96,"pid":"p56f583c407"},{"qid":"sy-c-20251025-098","no":98,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验方案","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"上述实验步骤（1）—（5）是被打乱的，正确的实验步骤应为（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[18,19],"answer":[46]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-098-题目-p18-755-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-098-题目-p19-51-126.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"（1）（4）（5）（3）（2）"},{"k":"B","t":"（3）（5）（1）（2）（4）"},{"k":"C","t":"（4）（5）（3）（1）（2）"},{"k":"D","t":"（5）（3）（4）（1）（2）"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-098-解析-p46-482-709.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"上述实验步骤（1）—（5）是被打乱的，正确的实验步骤应为（    ）。","options":[{"k":"A","t":"（1）（4）（5）（3）（2）"},{"k":"B","t":"（3）（5）（1）（2）（4）"},{"k":"C","t":"（4）（5）（3）（1）（2）"},{"k":"D","t":"（5）（3）（4）（1）（2）"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"98\n\n本题考查生物实验。\n\n步骤（1）在玻片两侧放入血液，并使血液与血清混合，因此在步骤（1）之前，玻片中应先滴入血清，观察实验步骤，步骤（3）和步骤（5）是向玻片中滴入血清，因此步骤（3）（5）在步骤（1）之前，且由步骤（3）（5）中的“用小滴管”“用另一个小滴管”可知步骤（5）在（3）之前，排除A、B 项。\n\n步骤（4）是对玻片做记号，应当是先对玻片做记号，这是实验的准备工作，再进行实验其他操作，故（4）在（5）之前，排除D 项。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[18,19],"answerPages":[46]},"idx":97,"pid":"p56f583c407"},{"qid":"sy-c-20251025-099","no":99,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"以下哪项最可能是本实验的目的？（    ）","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[46,47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-099-题目-p19-122-181.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"掌握血型的鉴定方法和原理"},{"k":"B","t":"检验不同血型的输血安全性"},{"k":"C","t":"探寻不同血型的抗原和抗体"},{"k":"D","t":"观察红细胞的凝集现象和时长"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-099-解析-p46-705-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-099-解析-p47-51-367.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"以下哪项最可能是本实验的目的？（    ）","options":[{"k":"A","t":"掌握血型的鉴定方法和原理"},{"k":"B","t":"检验不同血型的输血安全性"},{"k":"C","t":"探寻不同血型的抗原和抗体"},{"k":"D","t":"观察红细胞的凝集现象和时长"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"99\n\n本题考查生物实验。\n\nA 项正确，实验原理明确“根据红细胞抗原与血清抗体的凝集反应分血型”，步骤是“加标准血判断血型”（如a 侧凝集为A 型），结果判断直接指向“鉴定血型”，清加血看凝集整个实验围绕“如何用标准血清鉴定血型”展开，同时体现了“抗原抗体反应”的原理，符合实验核心目的。\n\nB 项错误，该实验仅能鉴定单一血样类型，并未进行不同血型间的交叉配血实验，无法直接检验输血安全性。\n\nC 项错误，实验原理已明确给出“A 型血有A 抗原、B 抗体；B 型血有B 抗原、A 抗体”，属于“已知原理的应用”，而非“未知抗原抗体的探寻”。\n\nD 项错误，虽然实验中会观察凝集现象，但这只是达成“鉴定血型”目的的手段和过程，而非实验的根本目的。\n\n故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[46,47]},"idx":98,"pid":"p56f583c407"},{"qid":"sy-c-20251025-100","no":100,"type":"实验设计","module":"综合分析","classification":{"version":"shiye-v1.20261011","group":"实验设计","tag":"实验分析","confidence":"中","needsReview":false,"auxiliary":[],"methods":[],"forms":[],"rule":"shiye.experiment-request","evidence":"根据上述实验，可知AB型血清中（    ）。","basis":"事业编问法与原件解析；未提供独立讲义的细分体系","sourcePages":{"paper":[19],"answer":[47]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-100-题目-p19-176-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","material":"<div class=\"source-material\"><img src=\"assets/img/institution/C-2025-10-25-m98-材料-p18-491-755.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","materialNo":98,"options":[{"k":"A","t":"既含有A抗体又含有B抗体"},{"k":"B","t":"含有A抗体但不含B抗体"},{"k":"C","t":"含有B抗体但不含A抗体"},{"k":"D","t":"既不含A抗体也不含B抗体"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-100-解析-p47-363-808.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"根据上述实验，可知AB型血清中（    ）。","options":[{"k":"A","t":"既含有A抗体又含有B抗体"},{"k":"B","t":"含有A抗体但不含B抗体"},{"k":"C","t":"含有B抗体但不含A抗体"},{"k":"D","t":"既不含A抗体也不含B抗体"}],"material":"（三）实验材料与器材：双凹载玻片、消毒牙签、刺血针、A型和B型标准血清、生理盐水、酒精棉球、显微镜实验原理：根据红细胞膜外表面是否存在特异性的抗原A或B，将人的血型分为A、B、AB、O四个类型，A型血中红细胞表面含有A抗原，血清里含有B抗体；B型血中红细胞表面含有B抗原，血清里含有A抗体。当抗体与相应抗原起反应时，红细胞发生凝集，最后溶解，为了避免这一点，确保安全输血，临床上输血前必须鉴定血型，一般血型相同才能输血。\n\n实验步骤：（1）穿刺被试手指取血，玻片的a、b两侧各放入一小滴血，用牙签搅拌，使每侧标准血清和血液混合，每侧用一支牙签，切勿混用。\n\n（2）室温下静置10-15分钟，观察有无凝集现象。若只是a侧发生凝集，则血型为A型；若只是b侧发生凝集，则血型为B型；若两侧均未凝集，则为O型；若两侧均发生凝集，则为AB型。\n\n（3）用另一个小滴管吸B型标准血清一滴加入左侧。\n\n（4）取一块清洁玻片，用笔做记号，左上角写a字，右上角写b字。\n\n（5）用小滴管吸A型标准血清一滴加入右侧。","explanation":"100\n\n本题考查生物实验。\n\n实验步骤（2）说明，若为AB 型血，则两侧（a 侧为B 型标准血清——含有A 抗体，b 侧为A 型标准血清——含有B 抗体）均会发生凝集。这说明AB 型血的红细胞既与A 抗体反应，也与B 抗体反应，证明其红细胞上同时存在A 抗原和B 抗原。根据免疫学原理，人体不会产生对抗自身红细胞抗原的抗体。因此，AB 型血的血清中既不含有抗A 抗体，也不含有抗B 抗体。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/综合分析.md","module":"综合分析","sourceModule":"综合分析","sourceType":"实验设计","questionPages":[19],"answerPages":[47]},"idx":99,"pid":"p56f583c407"}]};
